window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-04"]={"block":"med:med-clinica-medica-med-clm-04","label":"MED · MED CLM 04","count":457,"questions":[{"id":"med-clinica-medica-med-clm-04-345456","number":"345456","sourceNumber":"345456","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nos indivíduos com diabetes melitus tipo 2 (DM2), a necessidade de insulina aumenta à\nmedida que a doença avança no tempo, devido ao declínio progressivo da função da célula ?.\n\nAnalise as afirmativas abaixo sobre a terapia baseada em insulina: 1. Está indicada em momentos\ndo tratamento farmacológico em que haja\nintercorrências que causem descompensação da\nhiperglicemia. 2. Está indicada quando outras opções de tratamento tiverem falhado ou estiverem\ncontraindicadas e persistir a hiperglicemia. 3. Poderá ser considerada quando a HbA1c estiver\nacima de 9,0%, seja em combinação com outros agentes ou em monoterapia. 4. É recomendada\nna presença de sintomas de hiperglicemia, incluindo polidipsia, poliúria e perda de peso, devendo\nesta ser substituída posteriormente, respeitando as limitações da função renal e os efeitos adversos\ndos demais anti-hiperglicemiantes. Assinale a alternativa que indica todas as afirmativas\nCORRETAS:","options":{"A":"São corretas apenas as afirmativas 1 e 2.","B":"São corretas apenas as afirmativas 1, 2 e 3.","C":"São corretas apenas as afirmativas 1, 2 e 4.","D":"São corretas as afirmativas 1, 2, 3 e 4."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-343806","number":"343806","sourceNumber":"343806","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"José das Neves, de 60 anos, chega à Unidade Básica de Saúde e fala ao enfermeiro\nque deseja marcar uma nova consulta, pois já\npassaram 3 meses da anterior. O enfermeiro, que já\nsabe que José é portador de diabetes e já se trata na Unidade há 4 anos, desde que se mudou\npara o bairro, marca a consulta para o dia seguinte na parte da tarde. No dia seguinte na hora\nmarcada, seu José comparece e o médico o recebe com simpatia, perguntando como ele tinha\npassado os meses anteriores. Fala que manteria o tratamento, mas que estava na hora de realizar\nnovos exames de sangue para acompanhar seu quadro, que vinha sendo controlado já há 3 anos,\nquando iniciou nova medicação. Considerando ainda o caso clínico da questão anterior, assinale\ndos testes abaixo, aquele que proporciona ao médico uma visão mais a longo prazo de controle\nglicêmico do paciente, sendo atualmente uma valiosa medida para manejo dos pacientes com\nDiabetes Mellitus.","options":{"A":"Medida da glicemia capilar por glicosímetro em jejum.","B":"Dosagem da Glicose em laboratório em jejum.","C":"Dosagem sérica de Hemoglobina glicada.","D":"Teste de tolerância à glicose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-343844","number":"343844","sourceNumber":"343844","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Não é característica Fisiopatológica do Diabetes Mellitus tipo II:","options":{"A":"Deficiência relativa de insulina para manter os níveis de glicose normais, caracterizada pela\nresistência insulínica.","B":"Anti GAD negativo.","C":"Presença de Acantose Nigrans.","D":"Deficiência absoluta de insulina para manter os níveis normais de glicose no sangue."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-291757","number":"291757","sourceNumber":"291757","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Considerando as Diretrizes da Sociedade Brasileira de\nDiabetes, em relação ao tratamento desse paciente, é correto afirmar:","options":{"A":"A dose total diária de insulina, inicialmente, deve ser em torno de 20 a 40 unidades.","B":"A dose de insulina basal deve ser entre 60% a 80% da dose total para evitar hipoglicemia.","C":"Devido à aderência, deve-se optar por administrar a insulina 1 a 2 vezes ao dia.","D":"O paciente não é candidato ao uso de bomba de insulina, por maior risco de hipoglicemia que\napresente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-291758","number":"291758","sourceNumber":"291758","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Identifique a alternativa que contém uma combinação\nadequada de insulinas para esse paciente.","options":{"A":"Glargina, degludeca.","B":"NPH, glargina.","C":"Lispro, regular.","D":"Glulisina, detemir."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283274","number":"283274","sourceNumber":"283274","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente de 70 anos, deu entrada em unidade de pronto atendimento apresentando\nquadro de confusão mental, sonolência e\nvertigem. Ao exame o paciente se apresenta hipocorado,\ncom turgor cutâneo reduzido e mucosas desidratadas. Acompanhante refere que o paciente é\ndiabético e acerca de duas semanas não tem utilizado medicação de forma adequada. No\nmomento, a glicemia capilar é de 420 mg/dL. Em relação ao quadro clínico assinale a alternativa\ncorreta quanto à conduta.","options":{"A":"Deve-se iniciar insulina regular em bomba de infusão.","B":"Deve-se iniciar 15 unidades de insulina regular.","C":"Deve-se iniciar 0,15U/kg de insulina NPH.","D":"Deve-se iniciar hidratação venosa com soro fisiológico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-291759","number":"291759","sourceNumber":"291759","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Indique a orientação que deve ser fornecida ao paciente em\nrelação à insulinoterapia:","options":{"A":"A insulina que ainda não foi aberta deve ser mantida no congelador, em torno de -10o C a -20o\nC.","B":"Após aberta, a insulina pode ser mantida em temperatura ambiente por 30 dias.","C":"A aplicação da insulina deve ser realizada sempre no abdome, na região próxima ao umbigo.","D":"A insulina de ação rápida nunca deve ser combinada com uma de ação intermediária na mesma\nseringa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283275","number":"283275","sourceNumber":"283275","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo feminino, 59 anos, com diabetes mellitus tipo 2 em seguimento há 10\nanos com boa adesão à terapia não\nfarmacológica e uso regular de metformina e sulfonilureia há 5\nanos. Comparece para consulta de controle com hemoglobina glicada de 12%. Em relação à\nproposta terapêutica, assinale a alternativa correta.","options":{"A":"Iniciar insulina NPH 0,3UI/kg em dose única à noite.","B":"Iniciar insulina regular 0,3UI/kg em dose única no almoço.","C":"Iniciar insulina regular 0,3UI/kg em dose única à noite.","D":"Iniciar insulina NPH 0,3UI/kg em dose única no almoço."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-281118","number":"281118","sourceNumber":"281118","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem, 45 anos, refere poliúria, polidipsia e emagrecimento de seis quilos, há 4\nmeses. O mesmo faz uso constante de álcool,\ndiariamente, desde os 18 anos de idade. Glicemia\nem jejum de 250 mg/dl, realizada há cinco dias quando foi iniciado 1g de metformina no café da\nmanhã e no jantar. Desde então, apresenta intensa flatulência e diarreia aquosa. Assinale a\nalternativa que apresenta a melhor conduta em relação ao uso da metformina.","options":{"A":"A dose deve ser reduzida pela metade, uma vez que os sintomas tendem desaparecer com o\ntempo.","B":"Deve ser prontamente suspensa.","C":"Manter a dose e suspender caso haja ocorrência de neuropatia periférica.","D":"A dose deve ser mantida, uma vez que o benefício supera o risco do uso.","E":"Realizar avaliação da função renal e, caso a creatinina seja superior a 1,7mEq/L, deve ser\nsuspensa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283319","number":"283319","sourceNumber":"283319","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Estando de plantão na UPA, você atende um paciente portador de diabetes devido a\numa lesão no pé esquerdo, com mais de 1 mês\nde evolução, piora referida há 4 dias e nota ferida\nna região plantar e drenagem de secreção purulenta além de halo de eritema com mais de 3 cm.\nPaciente nega dor. Exames laboratoriais informam glicemia de 456 mg/dl, creatinina 1,9 mg/dl e\nleucometria 13.000 cel/mm3. Qual das afirmações abaixo informa a melhor alternativa na condução\ndo caso?","options":{"A":"Tratamento ambulatorial, com antibioticoterapia de largo espectro, ajuste dos hipoglicemiantes\norais e curativos em serviço especializado.","B":"Iniciar antibióticos orais e encaminhar ao serviço de cirurgia vascular de referência.","C":"Suporte clínico com internação hospitalar, antibioticoterapia parenteral e avaliação da\nnefrologia.","D":"Internação hospitalar, antibioticoterapia parental e avaliação cirúrgica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283366","number":"283366","sourceNumber":"283366","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A metformina é um hipoglicemiante oral amplamente utilizado no tratamento\nfarmacológico do diabetes mellitus tipo 2.\nAnalise as afirmativas abaixo e assinale a alternativa\ncorreta. I. O uso prolongado de metformina pode estar associado à deficiência bioquímica de\nvitamina B1. II. A metformina é o agente farmacológico inicial preferencial para o tratamento do\ndiabetes tipo 2. III. Uma vez iniciada, a metformina deve ser continuada desde que seja tolerada e\nnão contraindicada; outros agentes, exceto a insulina, podem ser adicionados à metformina. IV. A\nterapêutica com metformina para prevenção da diabetes tipo 2 deve ser considerada em indivíduos\ncom pré-diabetes, especialmente para aqueles com IMC? 35 kg/m2, aqueles com idade < 60 anos,\ne mulheres com diabetes mellitus gestacional prévio.","options":{"A":"Apenas as afirmativas II e IV estão corretas.","B":"Apenas as afirmativas I, II e IV estão corretas.","C":"As afirmativas I, II, III e IV estão corretas.","D":"Apenas as afirmativas II e III estão corretas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-251866","number":"251866","sourceNumber":"251866","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A manifestação mais precoce de doença renal crônica em pacientes portadores de\ndiabetes é a presença de:","options":{"A":"Aumento da creatinina.","B":"Proteinúria nefrótica.","C":"Microalbuminúria.","D":"Fibrose tubulointersticial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-247154","number":"247154","sourceNumber":"247154","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 42 anos de idade com diabete melito insulinodependente por 20 anos,\napresenta retinopatia diabética, protenúria e\ndepuração de creatinina normal. A pessoa arterial é de\n164x108mmhg e um discreto edema tibial é observado. A maneira mais eficiente de se preservar a\nfunção renal dessa paciente é:","options":{"A":"Controle da pressão arterial com inibidores da ECA.","B":"Dieta pobre em proteínas e diurético.","C":"Controle da pressão arterial e dieta pobre em proteínas.","D":"Controle rigoroso da glicemia e diuréticos.","E":"Controle da pressão arterial com bloqueadores dos canais de cálcio."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-247156","number":"247156","sourceNumber":"247156","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação ao controle glicêmico intensivo em pacientes internados, é correto dizer\nque:","options":{"A":"Em geral o uso de antidiabéticos orais pode e deve ser mantido durante o período de internação.","B":"A hipoglicemia associada ao tratamento intensivo não parece ser fator de risco independente\npara mortalidade.","C":"Metas glicêmicas entre 140 e 180 mg/dl, estão associadas a menor mortalidade e ocorrência de\nhipoglicemia.","D":"O uso de terapia intravenosa com insulina não está indicado em pacientes hemodinamicamente\ninstáveis.","E":"O uso de insulina rápida subcutânea em doses fixas é superior e mais seguro que o esquema\nbasal/bolus."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-251910","number":"251910","sourceNumber":"251910","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O risco cardiovascular global deve ser avaliado em cada indivíduo hipertenso, pois\nauxilia na decisão terapêutica e permite uma análise prognóstica. São fatores de risco\ncardiovascular na avaliação do risco adicional no hipertenso:","options":{"A":"Homens com idade ? 55 anos ou mulheres com idade ? 65 anos; tabagismo; triglicerídeos >\n300mg/dl.","B":"Circunferência abdominal ? 100 cm nos homens ou ? 88 cm nas mulheres; IMC ? 30 kg/m2;\nHemoglobina glicada entre 5,7 - 6,4%.","C":"História de doença cardiovascular prematura em parentes de 1° grau Homens < 55 anos ou\nmulheres < 65 anos; Circunferência abdominal ? 102 cm nos homens ou ? 88 cm nas mulheres;\netilismo.","D":"Sexo masculino; História de doença cardiovascular prematura em parentes de 1° grau Homens\n\n< 55 anos ou mulheres < 65 anos; Circunferência abdominal ? 102 cm nos homens ou ? 88 cm nas\nmulheres."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-251949","number":"251949","sourceNumber":"251949","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Após realização de By Pass gástrico para tratamento de obesidade mórbida, qual das\nvitaminas abaixo deve ser suplementada e qual a repercussão disso?","options":{"A":"Vitamina B12 - anemia megalobástrica.","B":"Vitamina K - diatese hemorrágica.","C":"Vitamina C - anemia microcitica.","D":"Vitamina D - osteoporose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-217651","number":"217651","sourceNumber":"217651","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca dos medicamentos usados no tratamento do diabetes tipo 2, assinale a\nalternativa CORRETA.","options":{"A":"Sulfonilureias ocasionam perda de peso.","B":"Tiazolidinedionas associadas à metformina causam hipoglicemia grave.","C":"A metformina tende a melhorar a hipertrigliceridemia e a hiperglicemia de jejum em diabéticos\ntipo 2 obesos, sem promover ganho de peso.","D":"A acarbose pode causar hipoglicemia grave."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-217720","number":"217720","sourceNumber":"217720","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A diabetes melito tipo I (DM1) costuma ser diagnosticada em crianças e adolescentes\nsem preferência por gênero e, mais raramente, em\nadultos. Quanto à DM está CORRETO afirmar\nque:","options":{"A":"Os pacientes com DM1 geralmente são obesos e apresentam predisposição para outras\ndoenças autoimunes, como tireoidite de Hashimoto,\ndoença celíaca, miastenia grave e doença de\nAddison.","B":"A maioria dos casos se inicia abruptamente, com sinais e sintomas típicos: poliúria, polidipsia,\npolifagia e perda de peso, que progredirão\npara desidratação, chegando a cetoacidose diabética,\nse o diagnóstico não for realizado.","C":"O diagnóstico de diabetes melito é realizado com uma dosagem de glicemia de jejum ? 126\nmg/dl (jejum definido por 12 horas sem ingesta calórica).","D":"A forma idiopática é responsável pela maioria dos casos na pediatria."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-217732","number":"217732","sourceNumber":"217732","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente de 52 anos, sexo masculino, IMC = 23 apresentando emagrecimento rápido e\ninexplicável, poliúria, polidipsia e polifagia, vem à consulta para avaliação. Nega qualquer\nproblema\nde saúde até o momento. Você solicita exames de laboratório e chama a atenção uma glicemia de\n282 mg/dl. Com o diagnóstico de diabetes tipo II em mente, além de orientar mudanças no estilo de\nvida e dieta (primeiro passo terapêutico para mais de 80% dos pacientes recém-diagnosticados),\ndeve-se inciar imediatamente o tratamento com:","options":{"A":"Metformina.","B":"Insulina NPH.","C":"Glibenclamida.","D":"Pioglitazona."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-182686","number":"182686","sourceNumber":"182686","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual o diagnóstico de um paciente com glicemia de jejum de 108 mg/dl e após Teste de\nsobrecarga oral de dextrose 75g em 2 horas, resultou 180 mg/dl?","options":{"A":"Sem anormalidades.","B":"Pré-diabetes.","C":"Diabetes mellitus.","D":"Síndrome metabólica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183151","number":"183151","sourceNumber":"183151","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A hemorragia vítrea causa baixa de acuidade visual pela opacificação hemática do\nvítreo. É importante investigar antecedentes oculares como traumas e cirurgias, bem como\npatologias sistêmicas. Assinale, a seguir, a causa mais frequente de hemorragia vítrea.","options":{"A":"Oclusão venosa.","B":"Descolamento de retina.","C":"Descolamento do vítreo posterior.","D":"Retinopatia diabética proliferativa.","E":"Uveíte."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183167","number":"183167","sourceNumber":"183167","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre a retinopatia diabética, analise. I. Uma das complicações mais comuns, presente\ntanto no diabetes tipo 1 quanto no tipo 2,\nespecialmente em pacientes com longo tempo de doença\ne mau controle glicêmico. II. Os efeitos colaterais decorrentes da fotocoagulação consistem em\nescotomas centrais, dificuldade para leitura, aceleração da catarata e, principalmente, na perda da\nvisão periférica ou na diminuição do campo visual. III. A fisiopatologia das alterações\nmicrovasculares do tecido retiniano está relacionada à hiperglicemia crônica, que leva a alterações\ncirculatórias, como perda do tônus vascular, alteração do fluxo sanguíneo, diminuição da\npermeabilidade vascular e, consequentemente, extravasamentos, edemas e obstrução vascular, a\nqual leva à neovascularização, com vasos frágeis que se rompem, causando hemorragia e\ndescolamento da retina. IV. O exame oftalmológico completo, incluindo oftalmoscopia (direta e\nindireta) e a biomicroscopia da retina sob midríase medicamentosa, é fundamental para a detecção\n(86%) e estadiamento da retinopatia. Estão CORRETAS as afirmativas:","options":{"A":"I, II, III e IV.","B":"I e II, apenas.","C":"Il e III, apenas.","D":"III e IV, apenas.","E":"I, II e IV, apenas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183194","number":"183194","sourceNumber":"183194","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O diabetes mellitus é uma doença sistêmica crônica, relacionada a uma deficiência\nabsoluta ou relativa de insulina, podendo\nprovocar alteração ocular, sendo a mais prevalente o(a):","options":{"A":"Catarata.","B":"Glaucoma.","C":"Retinopatia.","D":"Conjuntivite crônica.","E":"Paralisia transitória da musculatura extrínseca do olho."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-159056","number":"159056","sourceNumber":"159056","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"JBS, 12 anos de idade, apresenta diabetes há 5 anos. Faz uso de: insulina glargina 16\nUI pela manhã e insulina lispro 4 UI antes do café, 4 UI antes do almoço e 6 ui antes do jantar.\n\nNega episódios de hipoglicemia. Traz o seguinte esquema de dextro, aferido nos últimos 3 dias: -\nGlicemia de jejum: 108,116,112 mg/dL.; - 2 horas pós-café: 170, 130, 133 mg/dL.; - Antes do\n\nalmoço: 110, 120, 122 mg/dL.; -2 horas após o almoço: 208, 220, 201 mg/dL.; -Antes do jantar: 140,\n\n120, 122 mg/dL.; - 2 horas após o jantar: 242, 238, 231 mg/dL.; Sobre o caso, assinale a alternativa\ncorreta:","options":{"A":"A paciente faz uso de análogos de insulina. A insulina glargina é uma insulina de ação\nprolongada e a lispro é uma insulina de ação\nultrarrápida. A paciente apresenta descontrole das\nglicemias pós-prandiais, e deve aumentar a dose da insulina glargina.","B":"A paciente provavelmente apresenta a dosagem dos Anticorpos anti-GAD ou anti-ilhota\nnegativo.","C":"A paciente apresenta níveis de glicemia basais (jejum) adequados, com descontrole das\nglicemias pós-prandiais.Deve aumentar a dose da lispro pré café e lispro pré almoço.","D":"A vantagem da insulina glargina sobre a insulina NPH está principalmente na meia-vida da\ninsulina glargina, que, por ser maior em\nrelação a NPH, faz com que possa ser aplicada uma vez ao\ndia. A conduta mais adequada seria manter a dose da Insulina glargina e aumentar as doses de\ninsulina lispro antes do almoço e antes do jantar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-135974","number":"135974","sourceNumber":"135974","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere as ações dos antidiabéticos orais: I - São secretagogos de insulina que\nagem nas células Beta pancreáticas,\nresultando em liberação de insulina. II - Atuam diminuindo a\nneoglicogênese hepática e pode aumentar o aproveitamento periférico de glicose. III - Inibem a\natividade da dipeptidilpeptidase IV, diminuindo a degradação do GLP-1 e GIP. IV - Inibem a\nreabsorção da glicose nos túbulos renais, provocam um aumento da glicosúria e assim promovem\numa diminuição da glicemia de modo totalmente independente da ação da insulina. A - Metformina;\nB - Sitagliptina; C - Glibenclamida; D - Dapaglifozina. Quais as associações CORRETAS?","options":{"A":"IA, IID, IIIB E IVC;","B":"IC, IIA, IIIB e IVD;","C":"IC, IIB, IIIA e IVD;","D":"IB, IIA, IIID e IVC."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108672","number":"108672","sourceNumber":"108672","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre a avaliação do controle do DIABETES, é CORRETO afirmar que:","options":{"A":"A Glicemia de jejum e a Automonitorização da Glicemia capilar são suficientes para o\nacompanhamento do controle do Diabetes.","B":"Apenas a Hemoglobina Glicada é necessária.","C":"A Automonitorização da Glicemia capilar está em desuso da prática clínica para controle do\nDiabetes.","D":"A Glicemia de jejum, a Automonitorização da Glicemia capilar fornecem informações\ncomplementares necessárias, sendo todos os exames\nimportantes para avaliação do controle do\nDiabetes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-84523","number":"84523","sourceNumber":"84523","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A respeito do Diabetes mellitus, classifique as seguintes sentenças em verdadeiro (V)\nou falso (F). ( ) O Diabetes mellitus\napresenta alta morbimortalidade podendo levar a\ncomprometimento importante da qualidade de vida. ( ) O termo tipo I refere-se ao diabetes gerado\npela destruição das células-beta do pâncreas. ( ) O termo tipo II refere-se ao diabetes gerado pela\ndiminuição da resistência à ação da insulina. ( ) O Diabetes gestacional refere-se à hiperglicemia\ndiagnosticada durante a gravidez. Assinale a alternativa que corresponde à classificação correta,\nde cima para baixo.","options":{"A":"V, V, V, V.","B":"F, V, V, V.","C":"V, F, F, V.","D":"V, F, F, F.","E":"V, V, F, V."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-84548","number":"84548","sourceNumber":"84548","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São características do Diabetes Mellitus tipo II, exceto?","options":{"A":"Deficiência relativa de insulina para manter os níveis de glicose normais, caracterizada pela\nresistência insulínica;","B":"Anti-GAD negativo;","C":"Presença de Acantose Nigrans;","D":"Se apresenta de forma insidiosa;","E":"Deficiência absoluta de insulina para manter os níveis normais de glicose no sangue."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-66957","number":"66957","sourceNumber":"66957","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Rosa de 54 anos é professora e está realizando exames pré-operatórios para uma\ncirurgia ginecológica. Preocupada, leva os exames para seu médico da UBS (Unidade Básica de\nSaúde) analisar e ele lhe comunica que sua glicemia de jejum está alterada (100-125 mg/dl)\nhavendo intolerância à glicose. Diante do exposto, podemos considerar:","options":{"A":"Diabetes;","B":"Pré-diabetes;","C":"Glicemia de jejum alterada e baixa tolerância à glicose não são parâmetros confiáveis no\ndiagnóstico da diabetes;","D":"Nenhuma das acima está correta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-66933","number":"66933","sourceNumber":"66933","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 40 anos, com sobrepeso (índice de massa corporal = 27 Kg/m²), hipertensa\ncontrolada com medicações e com antecedente de diabetes gestacional, procura atendimento\nmédico para investigação laboratorial, a fim de avaliar sua regulação glicêmica. Foi solicitado\nglicemia de jejum, que resultou 114/mg/dl. O próximo passo será:","options":{"A":"Solicitar glicemia casual;","B":"Investigar diabetes mellitus durante 3 a 7 anos, dependendo do grau de suspeita clínica;","C":"Solicitar Teste Oral de tolerância à glicose (TOTG-75g);","D":"Orientar retorno se apresentar poliúria e polidipsia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-66921","number":"66921","sourceNumber":"66921","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente em tratamento de Diabetes Mellitus tipo II com medicamento que retarda o\nesvaziamento gástrico induz a saciedade alimentar, restaura a primeira fase de secreção de\ninsulina e é resistente à ação da DPP-IV, logo funciona como agonista dos receptores de GLP-1.\nQual o medicamento que deverá estar usando?","options":{"A":"Metformina;","B":"Glibenclamida;","C":"Sitagliptina;","D":"Liraglutide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-66928","number":"66928","sourceNumber":"66928","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São critérios diagnósticos de Diabetes Mellitus, EXCETO:","options":{"A":"Hemoglobina glicada (A1c) \"maior ou igual a\" 6,5%.","B":"Glicemia de jejum \"maior ou igual a\" 126 mg/dl.","C":"Teste Oral de Tolerância à glicose \"maior ou igual a\" 200 mg/dl.","D":"Glicemia pós-prandial \"maior ou igual a\" 146 mg/dl."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-67008","number":"67008","sourceNumber":"67008","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São características fisiopatológicas do Diabetes Mellitus II, EXCETO:","options":{"A":"Resistência insulina;","B":"Aumento da gliconeogênese hepática;","C":"Concentração diminuída do GLP-1 no sangue;","D":"Aumento das incretinas no sangue."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-50118","number":"50118","sourceNumber":"50118","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Senhor de 52 anos, hipertenso em uso de captopril 75 mg/dia, hidroclorotiazida 25\nmg/dia, dislipidemia em uso de atorvastatina 20 mg/dia, esteatose hepática detectada no último\nultrassom. Ao exame físico apresenta: IMC - 37 kg/m², PA - 125 x 85 mmHg, FC - 80 bpm, Pele -\nAcantose nigricans em cotovelos. Exames recentes - Glicemia jejum - 128 mg/dl, Hemoglobina\nglicada - 7,6, Colesterol Total - 208, HDL c - 38 mg/dl, Triglicerídeos - 200. Responda a questão\ncom base no caso clínico. Quais os diagnósticos do CASO CLÍNICO?","options":{"A":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau I, Diabetes Mellitus e Síndrome\nmetabólica;","B":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau II, Intolerância à Glicose e Síndrome\nmetabólica;","C":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau II, Diabetes Mellitus e Síndrome\nmetabólica;","D":"HAS, Dislipidemia, Estatose hepática, Obesidade grau I, Intolerância à Glicose e Síndrome\nmetabólica;"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-50120","number":"50120","sourceNumber":"50120","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Senhor de 52 anos, hipertenso em uso de captopril 75 mg/dia, hidroclorotiazida 25\nmg/dia, dislipidemia em uso de atorvastatina 20\nmg/dia, esteatose hepática detectada no último\nultrassom. Ao exame físico, apresenta: IMC - 37 kg/m², PA - 125 x 85 mmHg, FC - 80 bpm, Pele -\nAcantose nigricans em cotovelos. Exames recentes - Glicemia jejum - 128 mg/dl, Hemoglobina\nglicada - 7,6, Colesterol Total - 208, HDL c - 38 mg/dl, Triglicerídeos - 200. Responda a questão\ncom base no caso clínico. Levando em consideração o CASO CLÍNICO e com base na\nfisiopatologia do Diabetes m=Mellitus, a classe de medicamento (s) que você escolherá deverá agir:","options":{"A":"Diminuindo a neoglicogênese hepática, aumentando a sensibilidade dos receptores periféricos à\ninsulina (fígado).","B":"Aumentando a produção de insulina pelas células beta do pâncreas.","C":"Diminuindo a secreção do Glucagon pelo pâncreas.","D":"Retardando a absorção de carboidratos pelo trato gastrointestinal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37068","number":"37068","sourceNumber":"37068","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São doenças consideradas comorbidades da obesidade, EXCETO:","options":{"A":"Diabetes mellitus tipo 2, hipoventilação alveolar, esteato-hepatite não alcoólica.","B":"Hipertrofia ventricular esquerda, hipertensão arterial, diabete melito tipo 1.","C":"Hipertrofia ventricular direita, esofagite de refluxo, gota.","D":"Anovulação, diabetes gestacional, doença hemorroidária.","E":"Apneia do sono, aumento do risco cirúrgico e anestésico, hirsutismo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37063","number":"37063","sourceNumber":"37063","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, diabético, 52 anos, em uso de hipoglicemiante oral, refere que há 3\ndias iniciou quadro de prurido em bolsa escrotal, evoluindo com dor local e hiperemia. Ao exame\nfísico apresenta bolsa escrotal edemaciada com hiperemia e áreas de necrose de pele e crepitação\nque se estendem até a região perineal. O diagnóstico mais provável?","options":{"A":"Gangrena de Fournier.","B":"Epididimite aguda.","C":"Torção testicular com necrose.","D":"Furunculose necrótica.","E":"Síndrome de Élan."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-29381","number":"29381","sourceNumber":"29381","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Senhora de 50 anos, peso de 78 Kg, estatura de 1.60 m, diabética, hemoglobina\nglicada de 9g%, hipertensa em uso de\nanti-hipertensivos e hipolipemiante oral. Qual a medicação\nde primeira escolha para o caso?","options":{"A":"Sulfonilureias","B":"Biguanidas","C":"Tiazolenedionas","D":"Inibidores da alfa glicosidase","E":"Insulinas"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-372047","number":"372047","sourceNumber":"372047","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando o paciente apresenta quadro de Cetoacidose Diabética, a insulina análoga de\nação prolongada (glargina, detemir) ou a insulina\nhumana de ação intermediária (NPH):","options":{"A":"Não podem ser administradas após a recuperação da cetoacidose, antes da descontinuação da\ninsulina IV, para evitar que a insulina adequada esteja disponível quando a insulina IV for\ndescontinuada.","B":"São suspensas após a recuperação da cetoacidose, pois a descontinuação da insulina IV, para\ngarantir que a insulina adequada esteja indisponível quando a insulina IV for descontinuada.","C":"São administradas após a recuperação da cetoacidose, antes da descontinuação da insulina IV,\npara garantir que a insulina adequada esteja disponível quando a insulina IV for descontinuada.","D":"São administradas somente antes da recuperação da cetoacidose, depois da descontinuação da\ninsulina IV, para garantir que a insulina adequada esteja disponível quando a insulina IV for\ndescontinuada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-372074","number":"372074","sourceNumber":"372074","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A hipofosfatemia leve é um achado comum e geralmente assintomático durante a\nterapia da Cetoacidose Diabética - CAD. Podemos indicar como correto o item:","options":{"A":"Não se indica reposição de sais de fosfato de rotina, em parte devido ao risco de hipocalcemia,\nnão havendo evidências suficientes que demonstrem\na melhora do prognóstico quando em\ncomparação com o não uso.","B":"Sempre está indicado reposição de sais de fosfato de rotina, em parte devido ao risco de\nhipocalcemia, não havendo evidências suficientes que demonstrem a melhora do prognóstico\nquando em comparação com o não uso.","C":"Se indica reposição de sais de fosfato de rotina, em parte devido ao risco de hipercalcemia,\nhavendo evidências suficientes que demonstrem a\nmelhora do prognóstico quando em comparação\ncom o não uso.","D":"Dentro dos protocolos se indica reposição de sais de fosfato de rotina, em parte devido ao risco\nde hipercalcemia, havendo evidências suficientes que demonstrem a melhora do prognóstico\nquando em comparação com o não uso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-369509","number":"369509","sourceNumber":"369509","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem, 77 anos de idade, portador de hipertensão arterial sistêmica, diabetes mellitus\ntipo 2, ansiedade e depressão, está sob\ntratamento farmacológico com múltiplas medicações,\nincluindo anti-hipertensivos (losartana e amlodipina) diurético (furosemida), hipoglicemiante orais\n(glibenclamida. metformina,dapaglifozina), ansiolítico (alprazolan) e antidepressivo (venlafaxina).\nO\npaciente mantém boa funcionalidade e cognição mas, durante uma consulta de rotina na Unidade\nBásica de Saúde, relata fadiga constante, fraqueza muscular, câimbras, dificuldade de deambular,\nperda de concentração e episódios ocasionais de tontura. Entre as medicações comumente\nprescritas em regime ambulatorial para diabetes mellitus tipo 2, indique a que aumenta o risco de\nhipoglicemia em idosos como esse, especialmente quando usada em conjunto com outros\nhipoglicemiantes:","options":{"A":"Metformina.","B":"Pioglitazona.","C":"Dapagliflozina.","D":"Glibenclamida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-343159","number":"343159","sourceNumber":"343159","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em pessoas com DM2 e insuficiência cardíaca IC, em terapia combinada de metformina\ncom inibidores da proteína co-transportadora\nSGLT2 (ISGLT2) e HbA1c acima da meta:","options":{"A":"É recomendado adicionar um terceiro e, se necessário, um quarto fármaco de uso seguro na IC,\npara controle da hiperglicemia.","B":"É recomendado adicionar um terceiro e, nunca um quarto fármaco de uso seguro na IC, para\ncontrole da hiperglicemia.","C":"É recomendado adicionar um terceiro e, se necessário, um quarto fármaco de uso seguro na IC,\nmas não para controle da hiperglicemia.","D":"Nunca é recomendado adicionar um terceiro fármaco de uso seguro na IC, para controle da\nhiperglicemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-341077","number":"341077","sourceNumber":"341077","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Considerando o caso clínico, indique os exames essenciais que devem\nser realizados de imediato, ainda na Emergência:","options":{"A":"Hemograma e Estudo do Liquor.","B":"Hemograma e Sumário de Urina.","C":"Glicemia capilar, Cetonúria e Hemogasometria.","D":"Glicemia capilar, Hemograma e Hemoculturas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-341078","number":"341078","sourceNumber":"341078","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Indique o dado de história clínica que, se presente, reforçaria a principal\nsuspeita diagnóstica por sua especificidade:","options":{"A":"Febre.","B":"Poliúria.","C":"Inapetência.","D":"Hiperatividade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-341079","number":"341079","sourceNumber":"341079","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Especifique as condutas terapêuticas essenciais para esse paciente,\nimediatamente após a avaliação inicial:","options":{"A":"Reposição volêmica e administração de dobutamina.","B":"Oxigenoterapia e administração de dobutamina.","C":"Reposição volêmica e administração de insulina.","D":"Monitorização do ECG e antibioticoterapia empírica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-314231","number":"314231","sourceNumber":"314231","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em pacientes com DM estabelecido e microalbuminúria, foi demonstrado que uma\nabordagem multifatorial sobre estilo de vida","options":{"A":"Diminuiu significativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional.","B":"Aumenta significativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional.","C":"Não altera a morbi-mortalidade Cardiovascular (CV) em comparação ao tratamento\nconvencional.","D":"Diminuiu insignificativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-313467","number":"313467","sourceNumber":"313467","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"As variáveis incluídas no escore de risco de Framingham Heart Failure Risk Score são\nidade, sexo, DAC, diabetes, entre outros listados abaixo, indique o item errado:","options":{"A":"Hipertrofia ventricular esquerda não baseada em eletrocardiograma (ECG).","B":"Doença valvar.","C":"Frequência cardíaca.","D":"Pressão Arterial Sistólica (PAS)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-314234","number":"314234","sourceNumber":"314234","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Para a predição do Risco Individual de Doença Arterial Coronária em Pacientes com\nSíndrome Metabólica e Diabetes Mellitus, podemos entender que esta correto o item:","options":{"A":"O DM não é considerado fator de risco Cardiovascular - CV independente tanto em homens\nquanto em mulheres, elevando em cerca de duas\na quatro vezes a probabilidade de manifestar\nDAC, comparativamente àqueles indivíduos sem DM.","B":"O DM é considerado fator de risco Cardiovascular - CV dependente tanto em homens quanto em\nmulheres, reduzindo em cerca de duas a quatro vezes a probabilidade de manifestar DAC,\ncomparativamente àqueles indivíduos sem DM.","C":"O DM é considerado fator de risco Cardiovascular - CV dependente somente em homens ,\nelevando em cerca de duas a quatro vezes a probabilidade de manifestar DAC, comparativamente\nàqueles indivíduos com DM.","D":"O DM é considerado fator de risco Cardiovascular - CV independente tanto em homens quanto\nem mulheres, elevando em cerca de duas a quatro\nvezes a probabilidade de manifestar DAC,\ncomparativamente àqueles indivíduos sem DM."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-275967","number":"275967","sourceNumber":"275967","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação ao diabetes mellitus podemos afirmar que:","options":{"A":"O tipo I e II são causados por fatores autoimunes.","B":"A diferenciação entre os dois tipos é apenas temporal, ou seja, surgem em fases distintas da\nvida.","C":"Em ambas a hiperglicemia está relacionada a resistência periférica a insulina.","D":"O tipo I é de caráter autoimune e no tipo II há resistência periférica a insulina.","E":"Nenhuma das alternativas anteriores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283712","number":"283712","sourceNumber":"283712","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Considerando as Diretrizes da Sociedade Brasileira de\nDiabetes, em relação ao tratamento desse paciente, é correto afirmar:","options":{"A":"A dose total diária de insulina, inicialmente, deve ser em torno de 20 a 40 unidades.","B":"A dose de insulina basal deve ser entre 60% a 80% da dose total para evitar hipoglicemia.","C":"Devido à aderência, deve-se optar por administrar a insulina 1 a 2 vezes ao dia.","D":"O paciente não é candidato ao uso de bomba de insulina, por maior risco de hipoglicemia que\napresente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283713","number":"283713","sourceNumber":"283713","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Identifique a alternativa que contém uma combinação\nadequada de insulinas para esse paciente.","options":{"A":"Glargina, degludeca.","B":"NPH, glargina.","C":"Lispro, regular.","D":"Glulisina, detemir."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278608","number":"278608","sourceNumber":"278608","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Se a vítima de hipoglicemia estiver alerta, o socorrista pode administrar glicose por via\noral dando preferência para utilização de comprimidos de glicose, sendo correto que:","options":{"A":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","B":"Comprimidos de glicose que demostraram não aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes de glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","C":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nlenta em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","D":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente não podem ser utilizadas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-283714","number":"283714","sourceNumber":"283714","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Indique a orientação que deve ser fornecida ao paciente em\nrelação à insulinoterapia:","options":{"A":"A insulina que ainda não foi aberta deve ser mantida no congelador, em torno de -10°C a -20°C.","B":"Após aberta, a insulina pode ser mantida em temperatura ambiente por 30 dias.","C":"A aplicação da insulina deve ser realizada sempre no abdome, na região próxima ao umbigo.","D":"A insulina de ação rápida nunca deve ser combinada com uma de ação intermediária na mesma\nseringa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278081","number":"278081","sourceNumber":"278081","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Inúmeras evidências têm demonstrado que o bom controle glicêmico, geralmente,\napresenta como correta a alternativa.","options":{"A":"Não previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes.","B":"Previne o surgimento das complicações crônicas, que não constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes.","C":"Previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e não da piora da qualidade de vida do paciente com diabetes.","D":"Previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-280406","number":"280406","sourceNumber":"280406","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O Diabetes leva à depressão devido a fatores orgânicos através de alterações no ritmo\ncircadiano e na arquitetura do sono (diminuição de ondas lentas e aumento de movimentos\noculares) e apneia do sono, alteração do sistema imunológico levando a processos inflamatórios.\nSendo correto que:","options":{"A":"Ativação da imunidade inata, redução de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nindução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","B":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\ninibição de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","C":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nindução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","D":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nredução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-280458","number":"280458","sourceNumber":"280458","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um controle menos rígido da glicemia também parece razoável em indivíduos com\nlonga duração do DM que tenham mantido inadequado controle metabólico por longos períodos,\nsendo compatível com o item correto.","options":{"A":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada não estiveram associadas ao aumento da mortalidade.","B":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas à redução da mortalidade.","C":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas ao aumento da mortalidade.","D":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas à manutenção da mortalidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278669","number":"278669","sourceNumber":"278669","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nos países desenvolvidos, o aumento da prevalência ocorrerá principalmente pela\ncontribuição de indivíduos com diabetes nas faixas etárias mais avançadas, em decorrência do\naumento da expectativa de vida e do crescimento populacional, podemos assim concordar com o\nitem:","options":{"A":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 60 anos, em que a prevalência deverá duplicar.","B":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 20 a 44 anos, em que a prevalência deverá duplicar.","C":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 20 a 44 anos, em que a prevalência deverá reduzir.","D":"Nos países em desenvolvimento, indivíduos de faixas etárias mais idosas somente serão\natingidos, com destaque para a faixa etária de\n20 a 44 anos, em que a prevalência deverá duplicar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-279089","number":"279089","sourceNumber":"279089","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ainda nos anos 1930, Himsworth e Kerr introduziram o primeiro procedimento-padrão\npara o estudo da resistência à insulina in\nvivo. Demonstrando que pequenas doses de insulina\neram adequadas para indivíduos jovens com formas mais intensas da doença e propensos à\ncetose. Sendo correto o item:","options":{"A":"Indivíduos jovens e magros, menos propensos à cetose, são mais sensíveis à insulina do que os\nmais velhos e obesos não propensos à cetose.","B":"Indivíduos jovens e magros, propensos à cetose, são mais sensíveis à insulina do que os mais\nvelhos e obesos propensos à cetose.","C":"Indivíduos jovens e magros, propensos à cetose, são mais sensíveis à insulina do que os mais\nvelhos e obesos não propensos à cetose.","D":"Indivíduos jovens e magros, propensos à cetose, são mais resistentes à insulina do que os mais\nvelhos e obesos não propensos à cetose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-280459","number":"280459","sourceNumber":"280459","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A monitorização da glicemia capilar diariamente por indivíduos com DM1 de qualquer\nfaixa etária traz grandes benefícios, sendo\ncorreto o item:","options":{"A":"Por aumentar o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os determinantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","B":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por não\npermitir que o paciente entenda os determinantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","C":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os\ndeterminantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","D":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os\ndeterminantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos, mas não da prática de atividade física, por\nexemplo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-279093","number":"279093","sourceNumber":"279093","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É objetivo do tratamento do paciente com diabetes mellitus (DM) o bom controle\nmetabólico, diminuindo, assim, os riscos de\ncomplicações micro e macrovasculares. No arsenal\ndisponível à avaliação do controle glicêmico, podemos indicar como correto o item:","options":{"A":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que permitem o\ncálculo da glicemia média estimada), o desvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da faixa\nrecomendada de glicemia.","B":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que não permitem\no cálculo da glicemia média estimada), o\ndesvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da faixa\nrecomendada de glicemia.","C":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que permitem o\ncálculo da glicemia média estimada), o desvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve fora da faixa\nrecomendada de glicemia.","D":"Encontram-se a hemoglobina glicada (HbA1c), e não as glicemias capilares diárias (que\npermitem o cálculo da glicemia média\nestimada), o desvio-padrão da média da glicemia (que ilustra\na variabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da\nfaixa recomendada de glicemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-280463","number":"280463","sourceNumber":"280463","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A automonitorização evita glicemias fora do alvo além de possibilitar ajustes da insulina\nbasal, sendo adequado o item:","options":{"A":"Seja no esquema de múltiplas doses de insulina, mas não para bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária.","B":"Seja no esquema de múltiplas doses de insulina, seja na bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária.","C":"Seja no esquema de múltiplas doses de insulina, seja na bomba de infusão, para tanto, não\nsendo importante conhecer os objetivos glicêmicos\npara cada faixa etária.","D":"Somente no esquema de múltiplas doses de insulina, e não na bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-279095","number":"279095","sourceNumber":"279095","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"HbA1c é considerada o exame padrão-ouro para avaliar o controle metabólico do\nindivíduo com DM1, já que ficou\nconsistentemente demonstrada a relação entre níveis aumentados\ne risco de complicação microvascular. Podemos indicar como correto que:","options":{"A":"A determinação da HbA1c não possibilita estimar quão elevadas as glicemias estiveram nos\núltimos 3 a 4 meses. Tal estimativa torna-se possível pelo fato de a glicose sanguínea ligar-se de\nmaneira irreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração.","B":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\npossível pelo fato de a glicose sanguínea ligar-se de maneira\nirreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração.","C":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\npossível pelo fato de a glicose sanguínea ligar-se de maneira\nirreversível à hemoglobina durante o período de vida da hemácia, que não tem essa duração.","D":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\nimpossível pelo fato de a glicose sanguínea ligar-se de\nmaneira irreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-280467","number":"280467","sourceNumber":"280467","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A automonitorização favorece estratégias a fim de tratar ou evitar glicemias fora do\nalvo, modificar a razão insulina/carboidrato, sendo adequado o item:","options":{"A":"Otimizando a contagem de carboidratos, ou ajustar o fator de sensibilidade e propiciando uma\ncorreção ineficaz da hiperglicemia.","B":"Otimizando a contagem de carboidratos, mas não para ajustar o fator de sensibilidade e\npropiciando uma correção eficaz da hiperglicemia.","C":"Otimizando a contagem de carboidratos, ou ajustar o fator de sensibilidade e propiciando uma\ncorreção eficaz da hiperglicemia.","D":"Otimizando a contagem de carboidratos, ou ajustar o fator de especificidade e propiciando uma\ncorreção eficaz da hiperglicemia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278149","number":"278149","sourceNumber":"278149","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A prevalência é um indicador da magnitude da carga atual que a doença representa\npara os serviços de saúde e para a sociedade,\nsendo adequado que:","options":{"A":"Não como um preditor da futura carga que as complicações crônicas do diabetes representarão.","B":"Como um preditor da atual carga que as complicações crônicas do diabetes representarão.","C":"Como um preditor da futura carga que as complicações crônicas do diabetes representarão.","D":"Como um desvinculador da futura carga que as complicações crônicas do diabetes\nrepresentarão."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278680","number":"278680","sourceNumber":"278680","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ao realizar o upload dos glicosímetros para análise dos gráficos ou diários de glicemias,\né possível obter duas outras ferramentas para o\ncontrole glicêmico: o desvio-padrão da média das\nglicemias e o tempo no alvo. O desvio-padrão avalia a variabilidade glicêmica, que, idealmente,\ndeve ser inferior a 50 mg/dL ou de, no máximo, 1/3 da média das glicemias. Está correto que:","options":{"A":"Quanto menor o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","B":"Quanto maior o desvio-padrão, mais estável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","C":"Quanto maior o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","D":"Quanto maior o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de raras hipoglicemias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-279101","number":"279101","sourceNumber":"279101","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A porcentagem da hemoglobina que sofreu glicação será tanto maior quanto maior a\nconcentração de glicose sanguínea. Esse resultado expresso em porcentagem refere-se à média\ndas glicemias diárias, sendo 50% correspondente ao mês que precedeu o exame, 25% ao mês\nanterior à coleta e 25% ao terceiro e quarto meses anteriores. Sendo adequado o item:","options":{"A":"Em outras situações clínicas, como insuficiência renal ou hepática, que protegem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais elevado do que o habitual.","B":"Em outras situações clínicas, como insuficiência renal ou hepática, que predispõem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais baixo do que o habitual.","C":"Em outras situações clínicas, como insuficiência renal ou hepática, que predispõem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais elevado do que o habitual.","D":"Em outras situações clínicas, como insuficiência renal ou hepática, que não predispõem ao\naparecimento de hipoglicemia, o alvo glicêmico pode ser um pouco mais elevado do que o habitual."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-278682","number":"278682","sourceNumber":"278682","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O conceito de resistência à ação da insulina surgiu no final da década de 1930, quando\npesquisadores administraram extrato de pâncreas purificado a indivíduos com hiperglicemia e\nobservaram surpreendentes resultados quanto à variabilidade de resposta glicêmica entre eles.\n\nSendo correto o item:","options":{"A":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais velhos.","B":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais jovens.","C":"Mínimas doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais velhos.","D":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos femininos e jovens."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249185","number":"249185","sourceNumber":"249185","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"No diabetes, a hipotensão ortostática (HO) ocorre, frequentemente, consiste em\nredução da PA sistólica, de pelo menos 20\nmmHg, ou da PA diastólica, de pelo menos 10 mmHg,\nem 1 a 3 minutos após se assumir posição ortostática. Sendo correto que:","options":{"A":"Consequência de denervação parassimpática vasomotora eferente, reduzindo a vasoconstrição\ndo leito vascular esplâncnico e periférico.","B":"Consequência de denervação simpática vasomotora aferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","C":"Consequência de denervação simpática vasomotora eferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","D":"Consequência de denervação simpática vasomotora eferente, aumentando a vasoconstrição do\nleito vascular esplâncnico e periférico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249287","number":"249287","sourceNumber":"249287","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O controle intensivo do diabetes, com o objetivo de alcançar valores de glicemia\npróximos aos dos indivíduos sem diabetes, é capaz de prevenir ou pelo menos retardar o\ndesenvolvimento e a progressão da retinopatia. Somente se mostra errado o item:","options":{"A":"Essa proteção mostrou-se persistente em longo prazo.","B":"Dá-se o nome de legado glicêmico a esse fenômeno, obtido pelo controle rigoroso da glicose por\ndeterminado período de tempo.","C":"Esse ?legado? se deve, possivelmente, a alterações epigenéticas ocorridas na fase de mau\ncontrole.","D":"O contrário também não pode ocorrer, e pacientes que apresentaram mau controle podem\ndesenvolver quadros de complicações vasculares leves apenas quando passam a ter,\nposteriormente, bom controle da doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249390","number":"249390","sourceNumber":"249390","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Existem indicações relativas para o uso de SICI abaixo listada, qual não faz parte?","options":{"A":"Indivíduos não propensos a ter cetose.","B":"Ocorrência do fenômeno do alvorecer, com níveis de glicemia de jejum > 140 a 160 mg/dl.","C":"Pacientes com hipoglicemias noturnas frequentes e intensas.","D":"Ocorrência do fenômeno do entardecer."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249191","number":"249191","sourceNumber":"249191","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A insulina é medida em unidade internacional (UI). No Brasil, dispõe-se de preparações\nde insulina na concentração U100; indique o item\nerrado:","options":{"A":"A seringa possui escala graduada em unidades adequadas à concentração de insulina U100.","B":"Também é identificada como seringa U100.","C":"Não se deve usar seringa graduada em mL, pelo alto risco de erros no registro da dose.","D":"1 mL de solução tem 10 unidades de insulina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249194","number":"249194","sourceNumber":"249194","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A absorção de insulina injetada em locais com lipo-hipertrofia é imprevisível, podendo\ncausar hiperglicemias, hipoglicemias inexplicáveis\ne maior variabilidade glicêmica. Sendo adequado\no item:","options":{"A":"Locais com lipo-hipertrofia, a sensibilidade à dor pode aumentar significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas.","B":"Locais com lipo-hipertrofia, a sensibilidade à dor não pode diminuir significativamente, o que\nleva\nalguns indivíduos ao reúso intensificado de agulhas.","C":"Locais com lipo-hipotrofia, a sensibilidade à dor pode diminuir significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas.","D":"Locais com lipo-hipertrofia, a sensibilidade à dor pode diminuir significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249196","number":"249196","sourceNumber":"249196","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considerando como via de aplicação e velocidade de absorção da insulina, como usual\npara aplicação de insulina a subcutânea (SC), podemos concordar que:","options":{"A":"A extensa rede de capilares não possibilita a absorção gradativa da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","B":"A extensa rede de capilares possibilita a absorção súbita da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","C":"A extensa rede de capilares possibilita a absorção gradativa da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","D":"A extensa rede de capilares possibilita a absorção gradativa da insulina e não garante o perfil\nfarmacocinético descrito pelo fabricante."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249325","number":"249325","sourceNumber":"249325","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os fatores de estratificação estão referidos abaixo. Na presença de qualquer um deles,\no paciente com diabetes passa a ser classificado\ncomo de risco alto, independentemente da idade.\nIndique o item com erro:","options":{"A":"Taxa de filtração glomerular estimada < 60 mL/min.","B":"Albuminúria > 10 mg/g de creatinina.","C":"Neuropatia autonômica cardiovascular.","D":"Retinopatia diabética."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249452","number":"249452","sourceNumber":"249452","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Medidas não farmacológicas como cessação do tabagismo, perda de peso, atividade\nfísica regular, controle dietético e de fatores\nde risco estão indicadas para todos os pacientes com\nDM portadores de doença arterial coronariana (DAC). Nesse contexto, apenas não podemos\nconcordar que:","options":{"A":"a prevenção secundária com uso de AAS e estatinas (com alvo de LDL-C < 70 mg/dl) está\nindicada para todos, salvo contraindicações.","B":"o uso de IECAs está recomendado (salvo contraindicações) para pacientes portadores de DAC e\nDM para redução de risco cardiovascular.","C":"BRAs não devem substituir IECAs quando o paciente apresentar tosse relacionada com o IECA.","D":"betabloqueadores estão indicados para pacientes portadores de DAC e DM com disfunção\nventricular esquerda, observando-se as indicações da diretriz de IC."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249453","number":"249453","sourceNumber":"249453","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Pesquisa Nacional de Saúde realizada pelo Instituto Brasileiro de Geografia e\nEstatística (IBGE, 2013) mostrou prevalência\nde diabetes melito de 19,9% nos indivíduos na faixa\netária de 65 a 74 anos de idade. Podemos assim aceitar que:","options":{"A":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","B":"No idoso diabético há aumento da mortalidade sem redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","C":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente redução do risco de institucionalização.","D":"No idoso diabético não ocorre aumento da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249274","number":"249274","sourceNumber":"249274","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro dos cuidados e considerações especiais com ao abordagem do DM2 no idoso,\nnão é correto afirmar que:","options":{"A":"no idoso, além da perda de função da célula beta, ocorre aumento da adiposidade central, com\ndiminuição da massa magra e menor resistência à insulina.","B":"a resistência insulínica no idoso está relacionada, também, à diminuição do tecido muscular, que\npode configurar a sarcopenia, que aumenta o\nrisco de queda e fraturas, de eventos\ncardiovasculares e de perda da autossuficiência.","C":"a sarcopenia é três vezes mais frequente na pessoa com diabetes.","D":"o risco de sarcopenia aumenta com o tempo de diagnóstico, o mau controle glicêmico e o\nsedentarismo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216221","number":"216221","sourceNumber":"216221","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A principal indicação do transplante isolado de pâncreas (TIP) é a ocorrência de\nhipoglicemia grave ou de internações por hiperglicemia ou cetoacidose, nesse contexto o item\nCORRETO é:","options":{"A":"Apesar do uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, nunca por\nuso de bomba de infusão subcutânea de insulina.","B":"Sem tentar uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, seja por\nuso\nde bomba de infusão subcutânea de insulina.","C":"Apesar do uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, seja por uso\nde bomba de infusão subcutânea de insulina.","D":"Apesar do uso de terapia insulínica não intensiva, seja com múltiplas doses de insulina, seja por\nuso de bomba de infusão subcutânea de insulina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215221","number":"215221","sourceNumber":"215221","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Análise de estudos dos benefícios e os danos de baixa dose de AAS em pacientes com\ndiabetes e sem doença cardiovascular (DCV) conhecida. Sendo INCORRETO, apenas, que,","options":{"A":"Pacientes diabéticos sem Doença Aterosclerótica Clínica (DACL) não devem receber terapia\nantiplaquetária para prevenção primária de eventos cardiovasculares.","B":"Indivíduos diabéticos e sem doença aterosclerótica manifesta classificados na categoria de alto\nrisco, com idade > 65 anos e baixo risco de sangramento, o AAS pode ser considerado\nindividualmente para prevenção primária de doença cardiovascular.","C":"AAS esteve associado a reduções dos principais eventos cardiovasculares.","D":"Não houve aumento de AVC hemorrágico e sangramento maior com AAS."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215235","number":"215235","sourceNumber":"215235","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O Terapia Combinada de insulina com Drogas Antidiabéticas Orais ou DAOs permite\num controle similar ou até superior ao obtido\ncom o uso isolado de insulina, quando ela é\nadministrada. Podemos, apenas, concordar que, a eficácia dos resultados:","options":{"A":"Não dependerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em\nvista, também, os potenciais efeitos colaterais individuais das diferentes drogas orais.","B":"Dependerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em vista,\ntambém, os potenciais efeitos colaterais individuais das diferentes drogas orais.","C":"Independerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em vista,\ntambém, os potenciais efeitos colaterais individuais das diferentes drogas orais.","D":"Dependerá, entretanto, das características clínicas e, mas não fisiológicas do paciente, tendo em\nvista, também, os potenciais efeitos colaterais individuais das diferentes drogas orais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216294","number":"216294","sourceNumber":"216294","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os princípios básicos do diagnóstico e da classificação de idosos com diabetes não\ndiferem daqueles estabelecidos para indivíduos\nmais jovens. Não podemos apenas concordar que:","options":{"A":"Cabe ressaltar, apenas, que a solicitação do teste oral de tolerância à glicose (TOTG) é ponto\nfundamental para o diagnóstico precoce do diabetes mellitus (DM) nesse grupo etário.","B":"A primeira alteração fisiopatológica a ocorrer é justamente a diminuição da capacidade de\ncaptação da glicose pelos músculos e pelo tecido adiposo no período pós-alimentar.","C":"Aspecto da resistência à insulina relacionado com a sarcopenia, situação frequente no idoso.","D":"A alteração fisiopatológica a ocorrer é justamente a diminuição da capacidade de captação da\nglicose pelos músculos, mas não pelo tecido adiposo no período pós-alimentar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216313","number":"216313","sourceNumber":"216313","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"As neuropatias diabéticas (NDs) são complicações crônicas em indivíduos com\ndiabetes mellitus (DM), são consideradas presentes corretamente de acordo com o item:","options":{"A":"As NDs são consideradas presentes somente após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, além das neuropatias\nhereditárias.","B":"As NDs são consideradas presentes mesmo após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, além das neuropatias\nhereditárias.","C":"As NDs são consideradas presentes somente após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, mas não das neuropatias\nhereditárias.","D":"As NDs não são consideradas presentes somente após a exclusão de outras causas, tais como\nas polineuropatias (PNPs) resultantes de doenças\nmetabólicas, sistêmicas, infecciosas,\ninflamatórias e nutricionais, a intoxicação por agentes industriais, drogas e metais, além das\nneuropatias hereditárias."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216332","number":"216332","sourceNumber":"216332","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro do quadro clinico de neuropatias diabéticas (NDs), podemos apenas concordar\nque:","options":{"A":"Tendo em vista a possibilidade de acometimento de todos os tipos de fibras nervosas, de todas\nas regiões do organismo, as manifestações\nclínicas não podem ser muito variadas.","B":"Tendo em vista a possibilidade de acometimento de todos os tipos de fibras nervosas, de todas\nas regiões do organismo, as manifestações\nclínicas podem ser muito variadas.","C":"Tendo em vista a possibilidade de acometimento somente de um dos tipos de fibras nervosas,\nde todas as regiões do organismo, as\nmanifestações clínicas podem ser muito variadas.","D":"Tendo em vista a impossibilidade de acometimento de todos os tipos de fibras nervosas, de\ntodas as regiões do organismo, as manifestações clínicas podem ser muito variadas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215480","number":"215480","sourceNumber":"215480","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Felizmente, nos dias de hoje, com a melhora da expectativa de vida dos pacientes com\nDM1, observam-se cada vez mais indivíduos com DM1 que alcançam faixas etárias geriátricas.\n\nPodemos apenas aceitar como CORRETO:","options":{"A":"Eles, muitas vezes, desenvolvem sobrepeso, mas nunca obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo.","B":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo.","C":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes simples.","D":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por se curar da\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216226","number":"216226","sourceNumber":"216226","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O reconhecimento precoce e o tratamento das neuropatias diabéticas - NDs são\nimportantes pelos seguintes motivos explicado no item abaixo:","options":{"A":"À medida que progridem, as neuropatias diabéticas - NDs nunca são fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar.","B":"À medida que progridem, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés e amputações, sem alterar o equilíbrio ao andar.","C":"À medida que melhoram, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar.","D":"À medida que progridem, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215523","number":"215523","sourceNumber":"215523","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A diferenciação entre os tipos 1 e 2 pode não ser tarefa fácil, principalmente em\npacientes com DM1, observam-se cada vez mais\nindivíduos com DM1 que alcançam elevadas\nfaixas etárias e desenvolvem obesidade; assim, acaba por coexistir a resistência à insulina no que\nse convencionou chamar de diabetes tipo 1 + 2. Podemos aceitar como CORRETO:","options":{"A":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais não há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou\n\napós estímulo com glucagon ou refeição mista pode ser utilizada.","B":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou após estímulo com glucagon ou refeição mista não pode ser\nutilizada.","C":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou após\nestímulo com glucagon ou refeição mista pode ser utilizada.","D":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal, sem usar estímulo com glucagon ou refeição mista pode ser\nutilizada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216251","number":"216251","sourceNumber":"216251","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Conforme progridem, as Neuropatias diabéticas ? NDs tornam-se fatores de risco para\nmanifestações clínicas relacionadas com distúrbios cardiovasculares, sendo CORRETO que:","options":{"A":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nmas são incapazes de provocar morte súbita por\narritmias cardíacas.","B":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nalém da possibilidade de morte súbita por\narritmias cardíacas.","C":"Assim, não podem afetar a qualidade de vida pelas dores neuropáticas frequentemente\nassociadas, e sim causar morte súbita por\narritmias cardíacas.","D":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nmas sem possibilidade de morte súbita por\narritmias cardíacas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215548","number":"215548","sourceNumber":"215548","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O diabetes também tem um relevante impacto econômico nos países e nos sistemas de\nsaúde. Isso decorre de maior utilização dos serviços de saúde, perda de produtividade e cuidados\nprolongados requeridos para tratar suas complicações crônicas, como insuficiência renal, cegueira,\nproblemas cardíacos e pé diabético. Não consideramos apenas o seguinte item que se mostra\nERRADO:","options":{"A":"A maioria dos países despende em casos de diabetes entre 5 e 20% do seu gasto total com\nsaúde.","B":"O diabetes é um importante desafio para os sistemas de saúde e um obstáculo para o\ndesenvolvimento econômico sustentável.","C":"Indivíduos com diabetes apresentam maiores taxas de hospitalizações em comparação com os\nque não têm diabetes, além de menor duração\nda hospitalização para um mesmo problema de\nsaúde.","D":"As hospitalizações consomem parcela significativa dos recursos de saúde."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216277","number":"216277","sourceNumber":"216277","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Sociedade Brasileira de Diabetes (SBD) preconiza uma meta de tratamento\nindividualizada, de acordo com as características\napresentadas anteriormente, sendo necessário\nencontrar um ponto de equilíbrio, evitando-se hipoglicemias frequentes, mas, ao mesmo tempo,\nsem permissividade excessiva de hiperglicemia. Somente não podemos concordar que:","options":{"A":"Comorbidades associadas.","B":"Polifarmácia.","C":"Capacidade de autocuidado.","D":"Risco associado a uma eventual hipoglicemia não deve ser considerado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215304","number":"215304","sourceNumber":"215304","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A maioria dos estudos compara o uso de insulina em monoterapia com o Tratamento\nCombinado (TC) de insulina com metformina, sulfonilureias ou ambas, por serem as drogas com\nmaior número de anos de utilização e mais amplamente empregadas. O terapia combinada de\ninsulina com o uso de metformina apresenta menor risco de hipoglicemia e de ganho de peso,\npodemos apenas considerar INADEQUADO que.","options":{"A":"DM2, o uso de terapia combinada de insulina com metformina, sulfonilureias ou ambas,\napresenta resultados semelhantes aos da insulinoterapia.","B":"Observando um maior ganho de peso quando se a metformina era adicionada e maior redução\ndo requerimento de insulina com o uso da\nsulfonilureias.","C":"Nos demais parâmetros, em todos os estudos com TC, poucos foram os pacientes que\napresentaram alguma alteração na qualidade de\nvida e nos níveis de lipoproteínas, triglicérides e\noutros lipídios.","D":"Faltam estudos que indiquem as vantagens do TC no desenvolvimento de complicações macro\ne microvasculares."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215194","number":"215194","sourceNumber":"215194","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O diagnóstico de Cetoacidose Diabética (CAD) envolve a caracterização de alterações\nclínicas e laboratoriais. Os principais\nsintomas dessa complicação são, EXCETO","options":{"A":"polidipsia.","B":"Poliúria.","C":"Náuseas e vômitos.","D":"Disúria."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215196","number":"215196","sourceNumber":"215196","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quanto à hidratação no tratamento da cetoacidose diabética, marque a afirmativa\nCORRETA.","options":{"A":"Tanto o soro de manutenção como o soro de reposição é administrado de forma isotônica.","B":"Deve ser realizada com soro hipotônico para evitar a ocorrência de edema cerebral.","C":"Deve ser realizada com correção rápida de hipercalemia.","D":"O soro de manutenção deve ser administrado junto com a solução hipotônica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215200","number":"215200","sourceNumber":"215200","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quanto aos fatores relacionados à fisiopatologia da cetoacidose diabética (CAD),\nassinale a alternativa CORRETA.","options":{"A":"O aumento do fluxo de água livre do compartimento intracelular para o extracelular, decorrente\nda elevação da osmolaridade\n\nplasmática, leva à hipernatremia.","B":"O aumento do fluxo de água livre do compartimento intracelular para o extracelular, decorrente\nda elevação da osmolaridade plasmática, leva à\nhiponatremia dilucional.","C":"O equilíbrio entre os compartimentos intracelular e extracelular raramente leva à alteração nos\nníveis de sódio.","D":"A elevação de ácidos graxos livres no plasma contribui para o aumento da natremia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215206","number":"215206","sourceNumber":"215206","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao tratamento da cetoacidose diabética\n(CAD).","options":{"A":"A reposição de insulina pode ser iniciada junto com a fase de expansão ou na segunda hora do\ntratamento, após a expansão inicial.","B":"A administração de insulina regular por via endovenosa e em infusão contínua é recomendada\npelos especialistas.","C":"A infusão endovenosa contínua de insulina deve ser evitada, pois leva à queda brusca de\nglicemia.","D":"A infusão de insulina por via endovenosa, de forma contínua, permite a redução gradual da\nglicemia, com menores riscos de complicações, como hipoglicemia e edema cerebral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215210","number":"215210","sourceNumber":"215210","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à reposição do bicarbonato no tratamento\nda cetoacidose diabética.","options":{"A":"Atualmente não há indicação para que seja realizada no tratamento da cetoacidose diabética,\nexceto durante a ressuscitação, com o intuito\nde se preservar a ação da insulina.","B":"É considerada um dos recursos que evitam a ocorrência de edema cerebral em crianças.","C":"Pode levar à hipóxia cerebral decorrente da diminuição da afinidade da hemoglobina pelo\noxigênio.","D":"Também pode causar hiponatremia e hipocalemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-212209","number":"212209","sourceNumber":"212209","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"P.J.M., 45 anos, assintomático, realizou exames laboratoriais de rotina após consulta\nmédica no posto de saúde. Paciente ficou\npreocupado com o resultado da glicemia de jejum de 138\nmg/dL. Retornou à unidade de saúde e o clínico geral solicitou uma nova glicemia de jejum, cujo\nresultado foi de 155 mg/dL. Dadas as afirmativas a respeito do mecanismo de ação dos\nmedicamentos antidiabéticos, I. As gliptinas aumentam o nível de GLP-1, com aumento da síntese\ne da secreção de insulina, além da redução de glucagon. II. As biguanidas reduzem a produção\nhepática de glicose com menor ação sensibilizadora da ação insulínica. III. As sulfonilureias\naumentam a sensibilidade à insulina em músculo, adipócito e hepatócito. IV. As glitazonas\npromovem retardo da absorção de carboidratos. verifica-se que está(ão) correta(s) apenas","options":{"A":"III.","B":"I e II.","C":"II e IV.","D":"I, II e III.","E":"I, III e IV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-201776","number":"201776","sourceNumber":"201776","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente, com cinquenta e seis anos de idade, tabagista, diagnosticado com\ndiabetes mellitus há mais de vinte anos, não\ninsulinodependente, hipertenso controlado, em uso de\nanlodipino 10 mg/dia e metformina 850 mg duas vezes ao dia. Os exames laboratoriais com:\nmicroalbuminúria = 300 mg/24 horas; creatinina sérica =1,4 mg/dl; potássio sérico = 4,8 mEq/L e\nhemoglobina glicosilada = 7,5 %. Considerando o caso relatado, assinale a alternativa CORRETA:","options":{"A":"Os níveis de pressão arterial e o hábito de fumar não são fatores de risco para a progressão da\nnefropatia.","B":"A utilização de drogas inibidoras da enzima de conversão da angiotensina ou inibidoras do\nreceptor AT1 da angiotensina está contraindiciada no caso de tendência à hiperpotassemia.","C":"A ausência de elevada excreção urinária de albumina exclui o diagnóstico de nefropatia\ndiabética.","D":"Em pacientes com diabetes tipo II, o aparecimento da nefropatia diabética é muito raro.","E":"Em pacientes com diabetes tipo II, a presença de microalbuminúria é um marcador de risco para\ndoenças cardiovasculares."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216321","number":"216321","sourceNumber":"216321","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Analisando o impacto global do diabetes mellitus e sua epidemiologia, atualmente\npodemos aceitar como CORRETO que vários estudos epidemiológicos","options":{"A":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida.","B":"negam um importante papel do meio ambiente nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida.","C":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, mas não na fase\nintrauterina e nos primeiros anos de vida.","D":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, mas não na fase\nintrauterina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216342","number":"216342","sourceNumber":"216342","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Na epidemiologia e impacto global do diabetes mellitus está determinado que ocorra\nimportante papel do meio ambiente nos períodos iniciais da vida, assim, podemos apenas\nACEITAR que","options":{"A":"indivíduos com peso elevado ao nascer apresentam níveis plasmáticos mais elevados de\n\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2, e menor da\nsíndrome metabólica.","B":"indivíduos com peso normal ao nascer apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica.","C":"indivíduos com baixo peso ao nascer não apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica.","D":"indivíduos com baixo peso ao nascer apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-216216","number":"216216","sourceNumber":"216216","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Estudos sugerem um importante papel nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida. Nesse momento atual, as evidencias INDICAM que\nestudos mais recentes","options":{"A":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é maior\nnos nascidos com baixo peso como nos com peso elevado (? 4 kg).","B":"não evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é\nmaior nos nascidos com baixo peso como nos com peso elevado (? 4 kg).","C":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é menor\nnos nascidos com baixo peso como nos com peso\nelevado (? 4 kg).","D":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é maior\nnos nascidos com baixo peso como nos com peso elevado (? 2 kg)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-180116","number":"180116","sourceNumber":"180116","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É correto afirmar sobre as manifestações cutâneas observadas no Diabetes Mellitus.","options":{"A":"A necrobiose lipoídica que acomete pacientes\n\ndiabéticos ocorre mais freqüentemente naqueles que são insulino-dependentes.","B":"A úlcera crônica do pé diabético está relacionada, na maioria dos casos, à isquemia vascular\nperiférica.","C":"A Doença Bolhosa (bullosis diabeticorum) é a\ndermatose mais comum em pacientes com diabetes.","D":"A dermopatia diabética manifesta-se por lesões\nacastanhadas nos membros inferiores, mais comum\nnas mulheres.","E":"A infecção fúngica mais comum no diabetes é a\npitiríase vesicolor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183041","number":"183041","sourceNumber":"183041","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em geral, o acometimento patológico do sistema nervoso é muito amplo e, inúmeras\nvezes, bastante grave no diabetes mellitus (DM).\nMostra-se INADEQUADO o conceito de que","options":{"A":"As principais manifestações clínicas de comprometimento somático são de dormência ou\nqueimação em membros inferiores,\n\nformigamento, pontadas, choques, agulhadas em pernas e pés, desconforto ou dor ao toque de\nlençóis e cobertores e queixas de\n\ndiminuição ou perda de sensibilidade tátil ou dolorosa, apenas.","B":"O diagnóstico das formas mais frequentes de neuropatia diabética baseia-se na caracterização\ndo quadro clínico com os sintomas\n\ne sinais clínicos mais típicos e na realização de testes neurológicos.","C":"Os testes neurológicos básicos envolvem a avaliação de sensibilidade, pesquisa de reflexos\ntendinosos e medidas de pressão\n\narterial (deitado e em pé) e de frequência cardíaca.","D":"É importante destacar que a ausência de sintomas e sinais de parestesia anteriormente\nmencionada, não exclui a neuropatia, pois\n\nalguns pacientes evoluem direto para a perda total de sensibilidade."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183054","number":"183054","sourceNumber":"183054","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os testes neurológicos básicos para diagnóstico das formas mais frequentes de\nneuropatia diabética envolvem a avaliação de\nsensibilidade, pesquisa de reflexos tendinosos e\nmedidas de pressão arterial (deitado e em pé) e de frequência cardíaca. Podemos, apenas, aceitar\no seguinte:","options":{"A":"Medida de pressão arterial sistêmica em posição deitada, apenas. Frequência cardíaca de\nrepouso: sugestiva de disautonomia\n\ncardiovascular quando o valor estiver acima de 100 bpm.","B":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n20 mmHg 1 min após assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular\n\nquando o valor estiver acima de 60 bpm.","C":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n30 mmHg ao assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular quando o\n\nvalor estiver acima de 100 bpm.","D":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n20 mmHg 1 min após assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular\n\nquando o valor estiver acima de 100 bpm."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183636","number":"183636","sourceNumber":"183636","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os inibidores da alfa-glicosidase, como a acarbose, agem inibindo a digestão de\ncarboidratos complexos sendo, entretanto, INCORRETO que:","options":{"A":"Os inibidores da alfa-glicosidase, sendo a acarbose o principal representante desta classe, agem\ninibindo a digestão de carboidratos complexos e, com isso, diminuindo a incursão glicêmica\n\npós-prandial ? sabidamente um risco cardiovascular.","B":"O uso desta classe de medicamentos em pacientes com pré-DM diminui o risco de hipertensão,\nmas não de doença cardiovascular, todavia não\ntem ação aparente no desenvolvimento de\ninsuficiência cardíaca - IC.","C":"Não há estudos randomizados cujo objetivo seja avaliar a ação do uso da acarbose em\npacientes com IC.","D":"Em estudo em ratos, observou-se que o uso de inibidores de alfa-glicosidase (voglibose) levou à\ndiminuição do remodelamento cardíaco e da progressão para insuficiência cardíaca - IC."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183082","number":"183082","sourceNumber":"183082","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sabe-se que uma grande proporção dos leitos hospitalares e sem emergências e\nenfermarias nos países em desenvolvimento é ocupada por pé diabético e a causa mais comum de\ninternações prolongadas. Podemos aceitar como CORRETO que,","options":{"A":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios precoces ocorre\nfraqueza muscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição rápida à hiperglicemia associada a fatores cardiovasculares.","B":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios avançados, fraqueza\nmuscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição prolongada à hiperglicemia associada a fatores cardiovasculares.","C":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular, sem alterar o\n\nfeedback da percepção de posição pelos receptores nas pernas e nos pés e, em estágios\navançados, fraqueza muscular e\n\nalterações estruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às\nfibras nervosas finas (tipos C\n\ne delta) pela exposição prolongada à hiperglicemia associada a fatores cardiovasculares.","D":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios avançados, fraqueza\nmuscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição aguda à hiperglicemia associada a fatores cardiovasculares."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183639","number":"183639","sourceNumber":"183639","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação pouco reconhecida,\napesar da sua grande importância clínica e do\nimpacto negativo na morbimortalidade de pacientes\ncom DM. Quando detectada NAD sintomática, estima-se mortalidade cardiovascular de 50% em\ncinco anos. Estando equivocada, somente, a seguinte alternativa:","options":{"A":"O Sistema Nervoso Autônomo (SNA) é acometido de forma ampla, no setor simpático.","B":"A doença pode ser assintomática, diagnosticada apenas em exames complementares. A\nmanifestação clínica é resultante da disfunção de um ou mais órgãos (cardiovascular,\ngastrointestinal, genitourinário, sudomotor e ocular).","C":"Os sinais e sintomas clássicos da disautonomia cardiovascular são: taquicardia em repouso,\nhipotensão ortostática, pré-síncope, síncope,\nlabilidade hemodinâmica durante cirurgias, isquemia\nmiocárdica silenciosa e baixa tolerância ao exercício físico.","D":"Outros sintomas correlatos são resultantes da gastroparesia, da hipomotilidade dos cólons."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183125","number":"183125","sourceNumber":"183125","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Alguns estudos também sugerem que o bom controle metabólico pode melhorar a\nneuropatia já estabelecida, além disso, têm sido indicadas outras medidas terapêuticas. Sendo que\no bom controle metabólico do diabetes é o principal fator preventivo da neuropatia. Podemos,\napenas, aceitar que","options":{"A":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhipoglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de elétrons, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica.","B":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de elétrons, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica.","C":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, não é a produção de\n\nsuperóxidos pela cadeia de transporte mitocondrial de elétrons. Esses podem ser revertidos pela\nativação da transcetolase, uma\n\nenzima dependente dos níveis de tiamina, a benfotiamina pode representar uma opção de\nterapêutica.","D":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de proteínas, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183050","number":"183050","sourceNumber":"183050","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Neuropatia diabética é o distúrbio neurológico demonstrável clinicamente ou por\nmétodos laboratoriais em pacientes diabéticos. A\npresença de neuropatia autonômica está\nassociada a aumento significativo de mortalidade na população diabética acometida. Podemos,\napenas, indicar como um conceito INADEQUADO o item:","options":{"A":"Neuropatia diabética é o distúrbio neurológico demonstrável clinicamente ou por métodos\nlaboratoriais em pacientes diabéticos, quando excluídas outras causas de neuropatia.","B":"O acometimento patológico na neuropatia diabética geralmente é amplo no organismo,\napresentando-se de duas formas principais:\npolineuropatia sensorimotora simétrica e neuropatia\nautonômica (cardiovascular, respiratória, digestiva e geniturinária).","C":"O bom controle metabólico do diabetes reduz apenas intensidade da lesão neurológica.","D":"Os testes neurológicos básicos envolvem a avaliação de sensibilidade, pesquisa de reflexos\ntendinosos e medidas de pressão arterial (deitado e em pé) e frequência cardíaca."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183618","number":"183618","sourceNumber":"183618","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação de grande importância\nclínica e do impacto negativo na\nmorbimortalidade de pacientes com DM. NÃO podemos apenas\nconcordar que:","options":{"A":"Os fatores de risco para NAD são tempo de doença e controle glicêmico.","B":"A neuropatia mais comumente relacionada com a NAD é a polineuropatia periférica (PNP)\nclássica (simétrica, distal e com\n\npredomínio sensitivo).","C":"É recomendado investigação da NAD em todos os pacientes com diagnóstico na DM2 e após\ndez anos no DM1.","D":"No seguimento, os exames devem ser feitos anualmente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183631","number":"183631","sourceNumber":"183631","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação clínica de impacto\nnegativo na morbimortalidade de pacientes com DM. Sendo ADEQUADO o seguinte conceito:","options":{"A":"Trata-se de uma polineuropatia de fibras grossas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por perda\nde óxido nítrico e lesão da célula de Schwann por\nacúmulo de radicais livres.","B":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\nreplicativo, disfunção de microcirculação por perda\nde óxido nítrico e lesão da célula de Schwann\npor acúmulo de radicais livres.","C":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por\nperda de óxido nítrico e lesão da célula de Schwann por\nacúmulo de radicais livres.","D":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por perda\nde óxido nítroso e lesão da célula de Schwann\npor acúmulo de radicais livres."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-181363","number":"181363","sourceNumber":"181363","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Senhora branca, 65 anos, há 10 anos hipertensa, com infecção urinária de repetição.\nEm uso de captopril. Queixa-se de\nemagrecimento, polidipsia, polifagia e poliúria. Ao exame físico,\nbom estado geral, peso 60 kg, pressão arterial sistêmica 150 x 85 mmHg; FC 65 bpm. Nos exames\nlaboratoriais observamos: sumário de urina com glicosúria; Hemoglobina 12 g/dL, hematócrito 36%;\nglicemia de jejum 260 mg/dL; hemoglobina glicada 11%; creatinina 2,5 mg/dl. Qual a melhor opção\nterapêutica, além de recomendações para modificação do estilo de vida?","options":{"A":"Insulina.","B":"Metformina.","C":"Glimepirida.","D":"Dapagliflozina.","E":"Clorpropamida."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-181339","number":"181339","sourceNumber":"181339","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual paciente é considerado pré-diabético, conforme os critérios propostos pela\nAmerican Diabetes Association em 2017?","options":{"A":"Homem, 38 anos, com glicemia de 150 mg/dL, após jejum de 8 h em duas ocasiões.","B":"Homem, 56 anos, com glicemia 2 h, após ingestão de uma sobrecarga de 75 g de glicose anidra,\ndissolvida em água de 210 mg/dL.","C":"Homem, 65 anos, com glicemia 2 h, após sobrecarga com 75 g de glicose de 160 mg/dL.","D":"Mulher, 70 anos, que da entrada na emergência com queixa de perda ponderal e fadiga e\nglicemia 230 mg/dL.","E":"Mulher, 48 anos, com hemoglobina glicada (A1C) de 8%."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183576","number":"183576","sourceNumber":"183576","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Diversos algoritmos e escores de risco baseados em estudos populacionais foram\ncriados nas últimas décadas, mas,\nconsiderando a ausência de dados brasileiros para uma\navaliação mais precisa do Risco Cardiovascular CV na nossa população, deve-se evitar o uso de\num único escore de risco para basear as decisões terapêuticas. É CORRETO que, o risco\nCardiovascular CV global","options":{"A":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, é fundamental para uma orientação\nterapêutica mais agressiva.","B":"não deve ser avaliado em cada indivíduo hipertenso, pois não auxilia na decisão terapêutica e\npermite uma análise prognóstica. A identificação dos indivíduos hipertensos que estão mais\npredispostos às complicações CV, especialmente infarto do miocárdio e AVE, é fundamental para\numa orientação terapêutica mais agressiva.","C":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, não é fundamental para uma\norientação terapêutica mais agressiva.","D":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, é fundamental para uma orientação\nterapêutica menos agressiva."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-182786","number":"182786","sourceNumber":"182786","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considerando que na Cetoacidose Diabética (CAD) e no Estado Hiperglicêmico\nHiperosmolar (EHH) observa-se desidratação e\nglicosúria de graus variáveis, diurese osmótica e\nperda de fluidos e eletrólitos, assinale a alternativa INCORRETA:","options":{"A":"A maioria dos pacientes com crises hiperglicêmicas agudas apresenta-se com leucocitose,\nverificada em até 55% dos casos, e pode\ntraduzir apenas intensa atividade adrenocortical.","B":"O sódio sérico mostra-se abaixo do normal em 77% dos casos na CAD devido à transferência\nosmótica de líquidos do espaço intra para o\nextracelular, vômitos e também pela perda renal\nassociada aos corpos cetônicos.","C":"No diagnóstico da CAD, o potássio sérico pode ser elevado em 37% dos casos, secundário à\nacidose, normal em 58% ou baixo em 5% dos casos, dependendo das reservas prévias nos\nespaços intra e extracelulares, e exige muito cuidado durante o tratamento pelo risco de arritmias\nou até parada cardíaca.","D":"Os valores de fosfato plasmático podem encontrar-se normais (54% dos casos) ou reduzidos\n(80% dos casos) no diagnóstico e tendem a\naumentar com a terapia insulínica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-182730","number":"182730","sourceNumber":"182730","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A identificação dos indivíduos hipertensos que estão mais predispostos às\ncomplicações Cardiovasculares ? CV, especialmente\nInfarto do Miocárdio e AVE, é fundamental\npara uma orientação terapêutica mais agressiva. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"O risco Cardiovascular global deve ser avaliado em cada indivíduo hipertenso, pois auxilia na\ndecisão terapêutica e permite uma análise prognóstica .","B":"Diversos algoritmos e escores de risco baseados em estudos populacionais foram criados nas\núltimas décadas, mas, considerando a ausência de dados brasileiros para uma avaliação mais\nprecisa do risco CV na nossa população, deve-se evitar o uso de um único escore de risco para\nbasear as decisões terapêuticas.","C":"Modelos multifatoriais de estratificação de risco podem ser utilizados para uma classificação de\nrisco individual mais precisa.","D":"Informar ao paciente os seus Fatores de Risco - FR pode piorar a eficiência das medidas\nfarmacológicas e não-farmacológicas para redução do risco global."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-182765","number":"182765","sourceNumber":"182765","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Cetoacidose Diabética (CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH) devem\nser tratados em Unidade De Terapia Intensiva\ne, fundamentalmente, são as duas complicações\nagudas graves que podem ocorrer durante a evolução do Diabetes Mellitus tipos 1 e 2 (DM1 e\nDM2). As principais causas de morte por CAD e EHH são edema cerebral, hipopotassemia,\nhipofosfatemia, hipoglicemia, complicações intracerebrais, trombose venosa periférica,\nmucormicose, rabdomiólise e pancreatite aguda. Quanto as taxas de mortalidade, assinale a\nalternativa CORRETA:","options":{"A":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 10%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 5%. Atualmente, em centros de excelência no tratamento de CAD,\né inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos casos de\nEHH, ainda permanece elevada, ao redor de 15%.","B":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 90%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 10%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%.","C":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 50%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 30%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%.","D":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 90%. Da\n\ndécada de 1950 em diante, com a evolução de todo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle\neletrolítico e o uso de insulina regular, essa taxa foi\nreduzida para aproximadamente 10%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 90% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183081","number":"183081","sourceNumber":"183081","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro das limitações impostas à atividade física na presença de complicações crônicas\ndo Diabético, determine a alternativa CORRETA.","options":{"A":"A presença de retinopatia restringe o tipo de exercício que pode ser praticado, já que esforços\nque causem grandes elevações de pressão\narterial, especialmente contrações isométricas e\nmanobra de Valsalva, podem ser contraindicados dependendo da presença de retinopatia.","B":"A presença de retinopatia não restringe o tipo de exercício que pode ser praticado, já que\nesforços que não causam grandes elevações de\npressão arterial, mesmo contrações isométricas e\nmanobra de Valsalva, podem ser contraindicados dependendo da presença de retinopatia.","C":"A presença de retinopatia restringe o tipo de exercício que pode ser praticado, já que esforços\nque pequenas elevações de pressão arterial,\nespecialmente contrações isométricas e podem ser\ncontraindicados dependendo da presença de retinopatia.","D":"A presença de retinopatia proíbe qualquer tipo de exercício a ser praticado, ja que esforços que\ncausem grandes elevações de pressão arterial,\nespecialmente contrações isométricas e manobra\nde Valsalva, podem ser contraindicados independendo da presença de retinopatia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183114","number":"183114","sourceNumber":"183114","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nas escolas e nos locais de treinamento, devem estar disponíveis alimentos que\ncontêm carboidratos, glucagon injetável e\norientações sobre o tratamento da hipoglicemia. Outros\ncuidados com diabéticos na prática esportiva são listados abaixo, determine o INADEQUADO.","options":{"A":"Anotar os dados referentes aos treinos, ao uso de insulina e à alimentação, além das glicemias\nrelacionadas, para possibilitar a individualização.","B":"Encorajar o uso de novas tecnologias, como sensores, monitores contínuos, aplicativos em\nsmartphones e relógios monitores.","C":"Para a reposição de CHO no caso de atividade física se deve esperar a queda dos níveis de\nglicose, quando a hipoglicemia já será inevitável.","D":"Os monitores de glicemia contínua e as bombas de insulina com tecnologias de autossuspensão\ne manejo programado de hipoglicemia são úteis e\npodem beneficiar pacientes que usam essas\ntecnologias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161165","number":"161165","sourceNumber":"161165","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Você se encontrava de plantão em um grande hospital terciário, como clínico, e o\nresidente médico da oftalmologia solicitou o\nseu parecer clínico para um paciente diabético que\nestava internando de urgência por grave complicação oftalmológica. Sendo a Retinopatia Diabética\n(RD) umas das principais complicações relacionadas ao Diabetes Mellitus (DM) e a principal causa\nde cegueira em pessoas com idade entre 20 e 74 anos, para ajudar no controle do paciente, você\nCORRETAMENTE orientou que:","options":{"A":"O tempo de duração do diabetes e o controle glicêmico não se relacionam com a gravidade da\nRD.","B":"É fundamental que seja feito o controle glicêmico adequado para a prevenção e diminuição das\ncomplicações relacionadas à doença.","C":"Os pacientes submetidos ao controle intensivo não apresentaram redução no risco de\ndesenvolvimento de retinopatia.","D":"De maneira geral, a de redução da hemoglobina glicada não leva a uma diminuição no risco de\naparecimento da retinopatia, somente de sua progressão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-158789","number":"158789","sourceNumber":"158789","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentre as opções de antidiabéticos orais, qual droga promove glicosúria, tem baixo\nrisco de hipoglicemia, promove perda de peso, redução da pressão arterial sistólica e tem como\nefeito colateral risco aumentado para infecções genitais e de trato urinário?","options":{"A":"Acarbose.","B":"Sitagliptina.","C":"Metformina.","D":"Pioglitazona.","E":"Dapagliflozina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161198","number":"161198","sourceNumber":"161198","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nesta manhã, durante seu atendimento ambulatorial, um paciente seu, que também é\nda área da saúde, na verdade Bioquímico,\npediu sua orientação a respeito de dieta, pois estava\npreocupado com sua hipertensão. Foi uma excelente discussão, uma vez que ele também conhecia\nbastante sobre assunto. Apenas um dos conceitos a seguir foi questionado por ele, sendo que você\nse prontificou a estudar e corrigir eventual ERRO, que está contido em uma das alternativas.\n\nIndique-a.","options":{"A":"De um modo geral, a base fisiopatológica para os eventos cardiovasculares é a aterosclerose,\nprocesso que se desenvolve ao longo de\ndécadas de maneira insidiosa, podendo os primeiros\nsinais ser fatais ou altamente limitantes.","B":"A formação da placa de ateroma na parede dos vasos sanguíneos, bem como suas\nconsequências clínicas (infarto do miocárdio e\nAcidente Vascular Encefálico ? AVE) associam-se\nintimamente com determinados fatores de risco cardiovascular, como\n\nhipercolesterolêmia, hipertrigliceridemia, diminuição do HDL-c, hipertensão arterial sistêmica,\nDiabetes Mellitus e obesidade.","C":"A aterosclerose caracteriza-se por um processo inflamatório agudo da parede vascular, e a\nelevação de marcadores inflamatórios\nséricos, como a proteína C-reativa, tem se associado a maior\nrisco de eventos cardiovasculares.","D":"A base para a prevenção de eventos cardiovasculares tem sido, nas últimas décadas, o controle\nrigoroso dos fatores de risco ardiovascular. O controle da pressão arterial efetivamente diminui a\nchance de eventos cardiovasculares, sobretudo de AVE."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161243","number":"161243","sourceNumber":"161243","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Cetoacidose Diabética (CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH) são as\nduas complicações agudas graves que podem ocorrer\ndurante a evolução do Diabetes Mellitus. A\nCAD está presente em aproximadamente 25% dos casos no momento do diagnóstico do DM1 e é a\ncausa mais comum de morte entre crianças e adolescentes com DM1, sendo também responsável\npor metade das mortes nesses pacientes com DM1 com menos de 24 anos. São importantes\naspectos sobre sua gênese os descritos a seguir, com EXCEÇÃO de um deles. Indique-o.","options":{"A":"Os estados infecciosos são as etiologias mais comuns de CAD e EHH. Entre as infecções, as\nmais frequentes são as do trato respiratório superior, as pneumonias e as infecções de vias\nurinárias.","B":"Ocorre a necessidade valorizar outros fatores importantes, como Acidente Vascular Cerebral\n(AVC), ingestão excessiva de álcool, pancreatite\naguda, Infarto Agudo do Miocárdio (IAM), traumas\ne uso de glicocorticoides.","C":"Ocorre os maiores riscos com o uso de risperidona e quetiapina.","D":"Os distúrbios psiquiátricos associados a irregularidades na condução da dieta ou no uso diário\nde insulina também podem contribuir para a CAD."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161180","number":"161180","sourceNumber":"161180","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 45 anos de idade, gostaria de realizar um Eletrocardiograma\n(ECG) e, por isso, procurou atendimento\nambulatorial referindo ser diabético e que tinha muito\nmedo de que apresentasse simultaneamente um problema cardíaco, isso porque seu irmão mais\nvelho e diabético acabara de falecer de ?ataque cardíaco. Em termos de diagnóstico de Isquemia\nMiocárdica no diabético, podemos ADEQUADAMENTE afirmar que:","options":{"A":"A sobrecarga ventricular esquerda no ECG indica risco baixo de eventos cardiovasculares no\nDM.","B":"A presença de ondas ?Q? no ECG indica risco moderado de eventos cardiovasculares no DM.","C":"A Isquemia Miocárdica ao Eletrocardiograma (ECG) indica risco moderado de eventos\ncardiovasculares no DM.","D":"O ECG se apresenta como um exame pouco sensível."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161184","number":"161184","sourceNumber":"161184","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Embora as diretrizes nacionais considerem os portadores de Diabetes Mellitus (DM) na\ncategoria de alto risco Doença Cardiovascular (DCV), o risco de desfechos cardiovasculares de\ncurto prazo nessa população é extremamente variável, sendo um dos grandes desafios clínicos a\ncorreta identificação de indivíduos assintomáticos, mas que apresentem risco elevado de desfechos\ncardiovasculares. Podemos assim considerar ADEQUADO que:","options":{"A":"Os diabéticos tipo 1, com o passar dos anos, apresentam maior risco de complicações\ncardiovasculares, principalmente após os\n\n60 anos de idade.","B":"Contudo, esse intervalo pode variar independente do tempo de duração da doença.","C":"O risco cardiovascular se mostra independente do aparecimento de nefropatia, da hipertensão\narterial e do descontrole da glicemia.","D":"Mais recentemente, a obesidade e a SM associam-se a esse risco aumentado de Doença\nCardiovascular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161277","number":"161277","sourceNumber":"161277","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A presença de depressão tem impacto negativo sobre o controle metabólico e, por\noutro lado, o distúrbio psiquiátrico também\ninterage no tratamento medicamentoso do diabetes\ndevido à necessidade de uso de psicofármacos. Os efeitos dos antidepressivos sobre a glicose,\npeso, entre outros estão listados a seguir, com EXCEÇÃO de um. Assinale-o.","options":{"A":"O uso da fluoxetina parece estar associado à piora nos níveis de HbA1c, aumento da\nnecessidade de insulina e perda de peso. Esse efeito sobre a sensibilidade à insulina ocorre\nindependentemente do seu efeito sobre o peso.","B":"A sertralina pode também reduzir a HbA1c, e o seu efeito sobre o ganho de peso é incomum.","C":"Com o uso da paroxetina pode haver ganho de peso em uma significativa minoria.","D":"A nortriptilina melhorou a depressão, mas piorou o controle glicêmico em pacientes diabéticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161281","number":"161281","sourceNumber":"161281","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro do que consideramos modificações no estilo de vida na população exposta ao\ndiabetes, aponte a alternativa INCORRETA.","options":{"A":"As modificações positivas do estilo de vida podem ter papel decisivo na prevenção do diabetes.","B":"Pacientes devem alterar seu estilo de vida, com modificação dos hábitos alimentares, perda\nponderal (redução de ao menos 30% do peso\ncorporal) caso apresentem sobrepeso ou obesidade.","C":"Hábitos de vida mais saudáveis (dieta balanceada, rica em fibras, visando peso corporal\nrealisticamente adequado, associada à atividade\nfísica de, pelo menos, 150 minutos semanais) são\ncapazes ? em indivíduos pré-diabéticos de reduzir seu risco de DM.","D":"Estudos também demonstraram a eficácia da acarbose, da metformina e da pioglitazona na\nprevenção do DM2."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-158745","number":"158745","sourceNumber":"158745","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A hemoglobina glicada (HbA1c) é o resultado de uma reação não enzimática de ligação\nda glicose à hemoglobina. Reflete a média do\ncontrole glicêmico dos últimos 4 meses, sendo,\nportanto, um reflexo mais confiável da existência de hiperglicemia; porém existem condições\nclínicas e interferentes técnicos que podem alterar seu resultado. Qual a condição clínica que\npromove a redução do valor real da HbA1c?","options":{"A":"Policitemia.","B":"Mieloma múltiplo.","C":"Alcoolismo crônico.","D":"Hipertrigliceridemia.","E":"Deficiência nutricional de ferro."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161291","number":"161291","sourceNumber":"161291","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Durante a prática diária, é necessário valorizar outros fatores importantes, como\nAcidente Vascular Cerebral (AVC), ingestão\nexcessiva de álcool, pancreatite aguda, Infarto Agudo\ndo Miocárdio (IAM), traumas e uso de glicocorticoides, como associados à Cetoacidose Diabética\n(CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH), que são as duas complicações agudas\ngraves que podem ocorrer durante a evolução do diabetes mellitus. Dentre essas associações,\naponte a ERRADA.","options":{"A":"Atualmente, com o uso mais frequente de bombas de infusão contínua subcutânea de insulina\nultrarrápida, tem-se observado aumento na incidência de CAD. Tal fato pode ocorrer em razão da\nobstrução parcial ou total do cateter, provocando redução aguda de infusão de insulina.","B":"A descompensação glicêmica costuma ser mais prolongada e mais grave em pacientes com\nDM1 recém-diagnosticados.","C":"A descompensação glicêmica costuma ser mais prolongada e mais grave em idosos com\ndiabetes associado a processos infecciosos ou\ncom limitações no autocontrole físico ou psíquico.","D":"A utilização crescente na prática psiquiátrica de compostos denominados de antipsicóticos\natípicos para tratamento de transtorno de humor\nbipolar e esquizofrenia (por ex.: clozapina,\nolanzapina, risperidona e quetiapina) é capaz de diminuir o risco de distúrbios metabólicos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161295","number":"161295","sourceNumber":"161295","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A depressão pode ser estudada como um dos possíveis fatores etiológicos do diabetes.\nAlguns estudos evidenciaram que a depressão prediz a ocorrência posterior da doença. A partir\ndessa análise, é possível a existência de um efeito sinérgico entre a depressão e o diabetes, ou\nseja, o resultado das duas condições juntas seria maior do que apenas o somatório dos seus\nefeitos. Estudos demonstram que os hábitos de vida (exercícios, controle do peso corporal e\ntabagismo) explicam uma parte considerável da associação entre depressão e controle glicêmico\nem diabéticos tipo 2 ao longo de anos. São adequadas as alternativas a seguir, com EXCEÇÃO de\numa. Indique-a.","options":{"A":"Um estudo brasileiro avaliou pacientes diabéticos tipo 2 e encontrou não apenas elevada\nprevalência de depressão, mas também\ncorrelação positiva entre a gravidade do quadro depressivo\ne a gravidade da polineuropatia diabética distal simétrica.","B":"Na população geral, a depressão é responsável por piora na morbidade e na mortalidade,\nmesmo na ausência de diabetes.","C":"A presença de depressão tem impacto negativo sobre o controle metabólico e, por outro lado,\num mau controle metabólico não altera a depressão.","D":"Um estudo demonstrou que a depressão seria um importante fator de risco para doenças micro\ne macrovasculares, perda da autonomia e até mesmo\nmortalidade pelo diabetes."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161297","number":"161297","sourceNumber":"161297","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro dos aspectos de prevenção do Diabetes, tanto farmacológico quanto\ncomportamental, na população de risco, assinale a alternativa INCORRETA.","options":{"A":"A metformina é indicação prioritária, sobretudo, em paciente com menor peso e com idade\nsuperior a 65 anos.","B":"Acarbose pode ser considerado, para pacientes jovens, risco moderado/alto para\ndesenvolvimento de DM2.","C":"Pioglitazona pode ser considerado, para pacientes jovens, risco moderado/alto para\ndesenvolvimento de DM2.","D":"Medicações podem ser indicadas, desde que não apresentem contraindicações outras para tais\nmedicamentos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161220","number":"161220","sourceNumber":"161220","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 45 anos de idade, gostaria de realizar um Eletrocardiograma\n(ECG) e, para isso, procurou atendimento\nambulatorial referindo ser diabético e que tinha muito\nmedo de que apresentasse simultaneamente um problema cardíaco, isso porque seu irmão mais\nvelho, que também era diabético, acabara de falecer de ?ataque cardíaco?. Em termos de\ndiagnóstico de Isquemia Miocárdica no diabético, podemos ADEQUADAMENTE afirmar que","options":{"A":"sobrecarga ventricular esquerda no ECG indica risco baixo de eventos cardiovasculares no DM.","B":"presença de ondas ?Q? no ECG indica risco moderado de eventos cardiovasculares no DM.","C":"isquemia miocárdica ao Eletrocardiograma (ECG) indica risco moderado de eventos\ncardiovasculares no DM.","D":"o ECG se apresenta como um exame pouco sensível."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161229","number":"161229","sourceNumber":"161229","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Embora as diretrizes nacionais considerem os portadores de Diabetes Mellitus (DM) na\ncategoria de alto risco para Doença Cardiovascular (DCV), o risco de desfechos cardiovasculares\nde curto prazo nessa população é extremamente variável, sendo um dos grandes desafios clínicos\na correta identificação de indivíduos assintomáticos, mas que apresentem risco elevado de\ndesfechos cardiovasculares. Assim, podemos considerar ADEQUADO que","options":{"A":"os Diabéticos tipo 1, com o passar dos anos, apresentam maior risco de complicações\ncardiovasculares, principalmente após os 60 anos de idade.","B":"mais recentemente, a obesidade e a SM associam-se a esse risco aumentado de Doença\nCardiovascular.","C":"contudo, esse intervalo pode variar independente do tempo de duração da doença.","D":"o risco cardiovascular se mostra independente do aparecimento de nefropatia, da hipertensão\narterial e do descontrole da glicemia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161234","number":"161234","sourceNumber":"161234","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quais são as metas de prevenção relacionadas ao tratamento de diabéticos jovens?","options":{"A":"As metas para o tratamento do DM2 no jovem são diferentes das propostas para o DM1.","B":"Manter assintomático, sustentar um ritmo normal de crescimento e desenvolvimento, além do\ncontrole do peso.","C":"Apenas prevenir complicações crônicas da hiperglicemia.","D":"Devemos tentar alcançar normoglicemia, mesmo causando hipoglicemias frequentes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161375","number":"161375","sourceNumber":"161375","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Podemos determinar fortes relações epidemiológicas da presença simultânea de\nDiabetes e de doenças cardiovasculares, mas\napenas uma das opções é considerada ADEQUADA.\nAssinale-a.","options":{"A":"Aproximadamente um terço dos indivíduos com o diagnóstico de Diabetes Mellitus (DM) acabam\npor falecer devido à Doença Arterial\nCoronariana (DAC) ou Doença Cerebrovascular (DCV).","B":"A confluência da menor incidência com a menor mortalidade tornará imprescindível o esforço\nconjunto de diversas especialidades médicas para a prevenção.","C":"Ocorre incidência do DM associado, na maioria das vezes, à obesidade.","D":"Ocorrerá manutenção na prevalência do DM no futuro próximo, se não houver uma redução\nimportante na incidência desta doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161240","number":"161240","sourceNumber":"161240","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A importância do apoio familiar de crianças diabéticas pode ser determinada pelo\nseguinte achado contido em uma das opções. Aponte-a.","options":{"A":"A supervisão direta da criança com DM2 não obteve efeito positivo no controle glicêmico.","B":"Nos pais, que treinam seus filhos a alimentarem-se melhor, não ocorre redução significativa do\nIMC.","C":"Ocorre que a obesidade pediátrica é um problema do complexo familiar.","D":"O ponto pouco importante do tratamento é a modificação do estilo de vida, a qual inclui\nmodificações dietéticas e aumento das atividades físicas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161390","number":"161390","sourceNumber":"161390","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considerando-se o conceito de risco cardiovascular, pacientes com DM, mesmo sem\ndoença aterosclerótica estabelecida, apresentam\nmaior risco de desenvolver eventos vasculares no\nfuturo. A Doença Aterosclerótica Coronariana é mais incidente e mais grave nos pacientes com DM\ndo que naqueles sem DM. Sobre isso, aponte a alternativa CORRETA.","options":{"A":"O risco relativo para DCV aumenta de dez vezes nos pacientes com DM2 em comparação com a\npopulação em geral.","B":"As mulheres com DM são particularmente afetadas pela DAC e seu risco de morte é 50% maior\ndo que o dos homens com DM.","C":"Estes pacientes apresentam raramente associação de fatores de risco cardiovascular: HAS,\nníveis séricos baixos de colesterol da\nlipoproteína de alta densidade (HDL-C), microalbuminúria e\ndoença renal, aumento do Índice de Massa Corporal (IMC) e da relação cintura-quadril.","D":"O DM, quando associado a fatores de risco clássicos para DAC, como hipercolesterolemia, fumo\ne HAS, aumenta o risco para DCV atribuído a\ncada um destes fatores de forma menos importante\ndo que é observado em indivíduos sem DM."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161407","number":"161407","sourceNumber":"161407","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Analisando o impacto da sobreposição de Hipertensão Arterial Periférica (DAP),\ndiabetes e doenças vasculares, o conhecimento dos dados epidemiológicos assume grande\nimportância. Acerca disso, marque a opção considerada INCORRETA.","options":{"A":"A Doença Arterial Periférica acomete duas a quatro vezes mais pacientes com DM.","B":"A presença do DM aumenta o risco de desenvolver isquemia crítica dos membros com Doença\nArterial Periférica.","C":"Além do aumento da frequência de DAP, o DM não afeta a distribuição da aterosclerose nos\nmembros inferiores, atingindo tipicamente as artérias tibiais, peroneais, femorais e poplíteas.","D":"A duração do DM e a hiperglicemia se associam positivamente à presença e à gravidade da\nDAP."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161264","number":"161264","sourceNumber":"161264","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro dos aspectos do diabético jovem, que apresentam vários desafios enfrentados\nno tratamento do DM2, podemos delimitar vários\nachados, com EXCEÇÃO","options":{"A":"da natureza insidiosa da síndrome.","B":"do atraso na procura pela assistência médica.","C":"do reconhecimento precoce pelo pediatra.","D":"da baixa adesão ao tratamento que decorre da resistência às mudanças de hábitos, somada às\ncaracterísticas próprias da idade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161206","number":"161206","sourceNumber":"161206","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando lidamos com conhecimento das complicações referente ao diabetes em longo\nprazo, assume grande importância o conhecimento dos conceitos referentes aos marcadores de\nhiperglicemia. Dentre esses conceitos, assinale o CORRETO.","options":{"A":"Genericamente, o termo hemoglobina glicada refere-se a um conjunto de substâncias formadas\ncom base em reações entre a hemoglobina A\n(HbA) e alguns açúcares.","B":"A HbA é a forma pouco importante e nativa da hemoglobina.","C":"No decorrer dos anos ou das décadas, a hiperglicemia prolongada promove o desenvolvimento\nde lesões orgânicas extensas e reversíveis.","D":"Os níveis de glicose sanguínea, persistentemente elevados, são atóxicos ao organismo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161210","number":"161210","sourceNumber":"161210","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Para entendermos a gênese dos achados clínicos decorrentes dos níveis,\npersistentemente elevados, de glicose sanguínea, que\npor sua vez são tóxicos ao organismo,\ndevemos considerar os diferentes mecanismos envolvidos, com EXCEÇÃO de um. Assinale-o.","options":{"A":"Mediante a promoção da glicação de proteínas.","B":"Hiperosmolalidade.","C":"Com manutenção dos níveis de sorbitol fora da célula.","D":"Aumento dos níveis de sorbitol dentro da célula."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161209","number":"161209","sourceNumber":"161209","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro da análise dos achados de alterações crônicas dos níveis de glicose sanguínea,\npodemos entender a importância de marcadores\nde elevação crônica da glicose. Assim, somente\numa das afirmativas se mostra completamente CORRETA. Aponte-a.","options":{"A":"A glicação da hemoglobina ocorre ao longo de todo o período de vida do glóbulo vermelho, que\né de aproximadamente 150 dias.","B":"Porém, dentro destes 150 dias, a glicemia recente é a que mais influencia o valor da HbA1c.","C":"O paciente em controle estável apresentará 50% de sua HbA1c formada no mês precedente ao\nexame, 25% no mês anterior a este e os 25% remanescentes no terceiro ou quarto mês antes do\nexame.","D":"O impacto de qualquer variação significativa (em sentido ascendente ou descendente), na\nglicemia média, será ?diluído? dentro de 6 meses, em termos de níveis de HbA1c."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161213","number":"161213","sourceNumber":"161213","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Para o correto uso do exame de monitorização dos níveis de glicose, existe uma\nfrequência recomendada para a realização dos testes\nde hemoglobina glicada. Sobre isso, assinale\na alternativa CORRETA.","options":{"A":"A quantidade de glicose ligada à hemoglobina é inversamente proporcional à concentração\nmédia de glicose no sangue.","B":"Uma vez que as hemácias têm um tempo de vida de aproximadamente 140 dias, a medida da\nquantidade de glicose ligada à hemoglobina pode fornecer uma avaliação do controle glicêmico\nmédio no período de 140 dias antes do exame.","C":"Em virtude de os resultados do exame concederem informação retrospectiva sobre 6 meses\nprecedentes, a realização de um teste de HbA1c a cada 3 meses fornecerá dados que expressam\na glicose sanguínea média no passado recente.","D":"Os exames de HbA1c devem ser realizados regularmente em todos os pacientes com diabetes.\n\nA princípio para documentar o grau de controle glicêmico em sua avaliação inicial e,\nsubsequentemente, como parte do atendimento contínuo do paciente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161286","number":"161286","sourceNumber":"161286","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando lidamos com prevenção secundária, devemos considerar que existem\nevidências científicas dos efeitos benéficos do\nexercício físico na prevenção e no tratamento do\nDiabetes Mellitus (DM). Sobre isso, assinale a opção considerada INCORRETA.","options":{"A":"O exercício previne o DM tipo 2 (DM2), principalmente nos grupos de maior risco, como os\nobesos e os familiares de diabético.","B":"Em adição, indivíduos fisicamente ativos e aqueles com melhor condição aeróbica apresentam\nmenor incidência de DM2.","C":"Diabéticos apresentam menor condição aeróbica, menos força muscular e menos flexibilidade\ndo que seus pares da mesma idade e sexo sem a\ndoença.","D":"Essa menor capacidade, decorrente das alterações metabólicas e suas consequências, assim\ncomo a menor capilarização tipicamente observada nos diabéticos, não podem ser\ncontrabalanceadas com o exercício físico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161245","number":"161245","sourceNumber":"161245","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro da análise da relação do exercício físico na população diabética, podemos\nafirmar diversos aspectos, com EXCEÇÃO de um deles. Assinale-o.","options":{"A":"Diabéticos fisicamente ativos ou em boa condição aeróbica apresentam melhor prognóstico do\nque aqueles inativos e com baixa condição\naeróbica.","B":"A observação, de que diabéticos sedentários têm maiores índices de consumo máximo de\noxigênio, de débito cardíaco e de\ncapacidade de extração tecidual de oxigênio, é refletida por uma\nmaior diferença arteriovenosa de oxigênio para exercícios submáximos e máximos, quando\ncomparados com sedentários não diabéticos.","C":"Ocorre importante impacto das alterações metabólicas que cronicamente atuam e comprometem\na capacidade física dos diabéticos.","D":"O treinamento aeróbico regular proporciona condições de reverter parcial ou totalmente algumas\ndas disfunções provocadas pela hiperglicemia\ncrônica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161134","number":"161134","sourceNumber":"161134","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro da monitorização do controle metabólico durante a gestação em mulheres que\nsão diabéticas, NÃO podemos considerar que:","options":{"A":"os níveis de HbA1c recomendados para minimizar os riscos também são os menores possíveis,\nnão devendo ultrapassar o limite de 2% acima do\nvalor normal do método.","B":"Durante a gestação, a HbA1c não deve ser usada como parâmetro de avaliação para eventuais\nalterações da conduta terapêutica devido ao longo período necessário para que os níveis\nglicêmicos alterados possam se refletir nos níveis de HbA1c observados.","C":"Durante a gravidez, é muito mais importante o controle rígido dos níveis de glicemias de jejum e\npós-prandiais do que dos níveis de HbA1c.","D":"A mulher diabética que pretende engravidar deve ser encorajada a obter o melhor controle\nmetabólico possível antes de engravidar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161257","number":"161257","sourceNumber":"161257","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Existem atualmente fortes evidências científicas dos efeitos benéficos do exercício\nfísico na prevenção e no tratamento do Diabetes\nMellitus (DM). O exercício previne o DM tipo 2\n(DM2), principalmente nos grupos de maior risco, como os obesos e os familiares de diabético.\nAponte a alternativa INCORRETA.","options":{"A":"O melhor momento do diabético se exercitar é cerca de 60 minutos após uma refeição, quando a\nglicose ingerida será utilizada como substrato energético, evitando a hiperglicemia pós-prandial.","B":"O exercício é um forte aliado na predição desse risco nos diabéticos, assim como na sua\nredução por meio da prática regular.","C":"O exercício físico reduz o risco cardiovascular também em pacientes com DM.","D":"Pacientes diabéticos que se exercitam regularmente mostram melhora clínica relevante no seu\nperfil lipídico, e diabéticos hipertensos tendem a ter um melhor controle dos níveis tensionais\nquando submetidos a treinamento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161142","number":"161142","sourceNumber":"161142","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro do entendimento da atual epidemia de diabéticos Tipo 2, aponte a alternativa\nINCORRETA.","options":{"A":"O aumento da incidência do Diabetes Mellitus tipo 2 (DM2) entre crianças e adolescentes vem\nsendo observado em várias regiões do mundo.","B":"O aumento da prevalência de DM2 tem sido ainda associado ao crescimento da industrialização\ne desenvolvimento socioeconômico.","C":"Já são conhecidos todos os motivos responsáveis pela eclosão da doença nessa faixa etária\n(entre crianças e adolescentes).","D":"Inicialmente, há duas décadas, esses relatos referiam-se a grupos homogêneos com maior\nsuscetibilidade à doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161284","number":"161284","sourceNumber":"161284","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quanto aos benefícios no controle do diabético, relacionado ao tipo de exercício\nproposto, somente NÃO podemos relacionar como\ncorreta uma das alternativas a seguir. Indique-a.","options":{"A":"Exercícios aeróbicos são normalmente realizados usando grandes grupos musculares e\ncaracterizam-se por atividades que costumam não demandar habilidades muito específicas, sendo\na caminhada o melhor exemplo disso.","B":"Aquecimento e desaquecimento são fundamentais, principalmente no subgrupo que apresenta\ndisautonomia.","C":"Exercícios de resistência/fortalecimento muscular devem ser incluídos no plano de atividades do\ndiabético, já que eles provocam elevação da sensibilidade da insulina de maior duração, mediado\ntambém pelo aumento da massa muscular.","D":"Exercícios de flexibilidade não devem ser contemplados, pois há redução da flexibilidade pela\nação deletéria da hiperglicemia crônica sobre as articulações, além da decorrente do\nenvelhecimento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161171","number":"161171","sourceNumber":"161171","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro do estudo do impacto da cada vez maior incidência de diabéticos na população\njovem, marque a opção INCORRETA.","options":{"A":"O aumento na predominância da obesidade na adolescência registrado nos últimos anos\nexplicaria, em grande parte, o avanço do DM2 nas populações jovens.","B":"O aumento na predominância da obesidade na adolescência, registrado nos últimos anos, se\nrelaciona com o desenvolvimento da síndrome metabólica e de doenças cardiovasculares na\nmaturidade.","C":"Em adolescentes com DM2, a avaliação do efeito do diabetes e da obesidade sobre\ncomplacência vascular encontrou aumento da rigidez dos vasos.","D":"DM2 de início precoce pode ser menos agressivo do ponto de vista cardiovascular do que em\nadultos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161301","number":"161301","sourceNumber":"161301","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando lidamos com prevenção e complicações relacionadas ao diabetes, podemos\nafirmar que existem diversos cuidados e considerações a respeito. Desse modo, indique a\nalternativa INCORRETA.","options":{"A":"Para os diabéticos, a recomendação de atividade aeróbica diária, ou pelo menos 3 dias da\nsemana sem permanecer mais de 2 dias sem\nrealizá-la, é reforçada para que os benefícios sobre o\nmetabolismo glicídico sejam alcançados.","B":"A duração necessária de uma sessão de exercício depende da intensidade e da frequência\nsemanal dos exercícios.","C":"Nos pacientes diabéticos, a duração de um exercício deve ser planejada para minimizar riscos\nde hipoglicemia, geralmente sendo necessária a\nreposição de carboidratos quando a atividade tiver\nduração > 30 minutos.","D":"A recomendação mais atual para diabéticos é de 150 minutos de exercícios de moderada\nintensidade ou 75 minutos de alta intensidade por semana ou uma combinação de ambos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161179","number":"161179","sourceNumber":"161179","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre o estudo da interação entre obesidade, descontrole metabólicos e diabetes no\npúblico mais jovem, podemos relacionar diversos aspectos, com EXCEÇÃO de um deles.\n\nIndique-o.","options":{"A":"As elevadas taxas de obesidade na infância e na adolescência estão relacionadas com\nsedentarismo crescente e mudança nos hábitos\nalimentares, frequentemente associadas a dietas\nhipercalóricas e hipergordurosas.","B":"Os possíveis candidatos que ligam obesidade à alteração do metabolismo dos carboidratos\nseriam os ácidos graxos livres aumentados, as\ncitocinas inflamatórias e os baixos níveis de\nadiponectina.","C":"A transição de tolerância normal à glicose para a intolerância à glicose e dessa etapa para o\ndiabetes está associada a um aumento discreto de peso.","D":"A elevação contínua do peso tem efeito sobre os níveis glicêmicos, independentemente de\nmudanças na sensibilidade insulínica ou na\ndemanda da célula beta."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161307","number":"161307","sourceNumber":"161307","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Embora a taxa de complicações crônicas relacionadas ao DM venham diminuindo nas\núltimas duas décadas, ainda é muito grande o número de pacientes afetados, pois a incidência de\nDM continua aumentando. Por este motivo, a Doença Renal do Diabetes (DRD) permanece sendo\na principal causa de doença renal crônica em pacientes ao ingressarem em programas de diálise,\ninclusive no Brasil. A DRD está associada ao aumento de mortalidade, principalmente relacionada à\ndoença cardiovascular. Em referência à enorme importância do adequado conhecimento de\nalterações achadas devido à sua evolução, indique a opção considerada INADEQUADA.","options":{"A":"A diminuição rápida e acentuada da taxa de filtração glomerular (> 80%) após o início de terapia\ncom Inibidores da Enzima Conversora da Angiotensina (IECA) ou Bloqueadores do Receptor AT1\nda Angiotensina (BRA) sugere estenose da artéria renal, devendo esta possibilidade ser avaliada,\nespecialmente em pacientes com vasculopatia.","B":"Todo teste de albuminúria anormal deve ser confirmado em duas de três amostras coletadas em\num intervalo de 3 a 6 meses, devido à\nvariabilidade diária da excreção urinária de albumina (EUA).","C":"Embora seja sugerido que infecção urinária possa interferir nos valores de EUA, recentemente\nfoi constatado que a existência de bacteriúria não\ninterfere de maneira apreciável nas medidas de\nalbuminúria.","D":"Fatores como exercício durante o período de coleta de urina, febre, insuficiência cardíaca,\nhiperglicemia grave e hipertensão arterial não controlada podem elevar os valores de Excreção\nUrinária de Albumina (EUA)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161186","number":"161186","sourceNumber":"161186","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando analisamos as características diferenciadas do diabetes na população jovem,\nestas apresentam diferenciais relacionados às suas características, NÃO sendo correta uma das\nopções apresentadas a seguir. Indique-a.","options":{"A":"Uma das grandes preocupações do diagnóstico de DM2 no jovem é que algumas comorbidades,\ncomo a neuropatia, apresentam-se tão comuns na\ncriança quanto no adulto DM2.","B":"Há um risco de desenvolvimento da doença em irmãos, semelhante à encontrada na população\ngeral.","C":"O desenvolvimento de complicações precoces terá implicações para o resto da vida, tanto para\ncriança quanto para orçamento da saúde pública.","D":"Um quarto das crianças obesas e 22% dos adolescentes obesos apresentam intolerância à\nglicose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161313","number":"161313","sourceNumber":"161313","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Atualmente, o uso do termo nefropatia diabética deve ser reservado somente para\npacientes com proteinúria detectável persistente, em geral associada à elevação da pressão\narterial. A respeito da relação entre o diabetes e a lesão renal, podemos considerar ADEQUADO\napenas o seguinte. Assinale-o:","options":{"A":"A Doença Renal do Diabetes (DRD), na forma de elevação da Excreção Urinária de Albumina\n(EUA), pode acometer 90% dos pacientes com diabetes.","B":"Embora a taxa de complicações crônicas relacionadas ao DM venha aumentando nas últimas\nduas décadas, tendo ocorrido uma redução\naproximada de 30% na Doença Renal do Diabetes\n(DRD), em suas fases mais avançadas ainda é muito grande o número de pacientes afetados, pois\na incidência de DM continua aumentando.","C":"A Doença Renal do Diabetes (DRD) está associada ao aumento de mortalidade, principalmente\nrelacionada à doença cardiovascular.","D":"O aumento da Excreção Urinária de Albumina (EUA) apresenta pouca importância como fator de\nrisco para eventos coronarianos e para desenvolvimento e progressão da Doença Renal do\nDiabetes (DRD)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161192","number":"161192","sourceNumber":"161192","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro da análise da associação entre a obesidade e o diabetes, indique a alternativa\nINCORRETA.","options":{"A":"A obesidade apresenta-se de modo constante no DM2 do jovem.","B":"Aproximadamente 70 a 90% das crianças são obesas; sendo que 38% apresentam obesidade\nmórbida.","C":"A obesidade e a história familiar parecem ter efeito aditivo no risco de desenvolvimento da\ndoença.","D":"O impacto da obesidade no risco do DM2 é menor em crianças com história familiar positiva\npara essa doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161315","number":"161315","sourceNumber":"161315","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A classificação atual da doença renal crônica, independentemente da etiologia, é\nbaseada na Taxa de Filtração Glomerular\n(TFG) e na Excreção Urinária de Albumina (EUA), pois\ntem sido extensamente reconhecida a relação desses dois parâmetros com desfechos adversos\nrenais e mortalidade. Sobre isso, marque a opção INCORRETA:","options":{"A":"Atualmente, tem havido uma ampliação do espectro das apresentações clínicas da Doença\nRenal do Diabetes (DRD), sendo o fenótipo da\ndoença renal não albuminúrica, caracterizada por\nredução isolada da TFG, cada vez mais reconhecido.","B":"Por este motivo, a Doença Renal do Diabetes (DRD) permanece sendo a quinta causa de\ndoença renal crônica em pacientes ao\ningressarem em programas de diálise, inclusive no Brasil.","C":"Em aproximadamente 1/5 dos casos, observa-se a redução isolada da Taxa de Filtração\nGlomerular (TFG). Em estudos realizados no Sul\ndo Brasil, verificou-se que 37% dos pacientes com\nDM tipo 2 (DM2) e 34% dos pacientes com DM tipo 1 (DM1) apresentam aumento da Excreção\nUrinária de Albumina (EUA).","D":"Atualmente, ainda é muito grande o número de pacientes afetados, pois a incidência de DM\ncontinua aumentando."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161199","number":"161199","sourceNumber":"161199","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre as características de fisiopatologia do diabetes que influenciam os achados\nepidemiológicos na população infantil, aponte a alternativa INCORRETA.","options":{"A":"Crianças que haviam nascido grandes para a idade gestacional (GIG) tinham menor risco de\nevoluir com obesidade, enquanto outras com antecedente familiar de DM2 apresentavam maior\nprevalência de síndrome metabólica.","B":"Ocorre elevação na Resistência à Insulina em portadores de excesso de peso com antecedentes\nfamiliares de DM2, sugerindo que, já nessa\nfaixa etária, como observado no adulto, a ação da\ninsulina pode ser dificultada pela obesidade, condição de risco para o desenvolvimento do diabetes.","C":"O antecedente familiar tem função fundamental na ocorrência do DM2 nessa faixa etária.","D":"Observou-se que irmãos de jovens com DM2, com sobrepeso, têm risco quatro vezes maior de\nmanifestar intolerância à glicose que outras crianças com sobrepeso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161316","number":"161316","sourceNumber":"161316","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O rastreamento da doença renal do diabetes (DRD), para que seja adequado, deve ser\niniciado logo ao diagnóstico do DM nos pacientes com DM2 e após 5 anos do início no DM1. No\nentanto, pacientes com DM1, que se encontrem na puberdade ou com DM persistentemente\ndescompensado, têm de ser rastreados independentemente dessas indicações. Acerca disso,\naponte a alternativa considerada INADEQUADA.","options":{"A":"O rastreamento precisa ser mensal e basear-se na medida da albuminúrica e na estimativa da\ntaxa de filtração glomerular (TFG).","B":"O rastreamento deve ser iniciado preferencialmente pela medida de albumina em amostra\nisolada de urina (primeira da manhã ou\ncasual), devido à acurácia diagnóstica e à facilidade desse\ntipo de coleta.","C":"Pode ser medido o índice de albumina-creatinina ou apenas a concentração de albumina.","D":"A vantagem da utilização da concentração da albumina é um menor custo sem perda de\nacurácia diagnóstica quando comparada com o índice."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161202","number":"161202","sourceNumber":"161202","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São achados do quadro clínico de jovens diabéticos os seguintes aspectos, com\nEXCEÇÃO de um deles. Marque-o.","options":{"A":"A idade de maior incidência do DM2 no jovem é próxima dos 13 anos, guardando relação com o\nestádio III da classificação de Tanner.","B":"Ocorre uma proporção de 2:1 em meninas, em relação aos meninos.","C":"As crianças com DM2 são geralmente assintomáticas ou oligossintomáticas por curtos períodos\nde tempo.","D":"Entre os pacientes, 30% apresentam poliúria, polidipsia leve e emagrecimento discreto. Algumas\npacientes podem revelar história de monilíase vaginal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161317","number":"161317","sourceNumber":"161317","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ocorre também importante necessidade de se conhecerem os diagnósticos diferencias\nde doenças renais dos diabéticos, devido ao fato\nde que o aumento da Excreção Urinária de\nAlbumina (EUA) ou a redução da Taxa de Filtração Glomerular (TFG), em pacientes com DM,\ntambém pode ser causado por outra doença renal não relacionada ao DM. O paciente deve ser\nsubmetido à avaliação adicional nas seguintes situações, com EXCEÇÃO de uma. Assinale-a.","options":{"A":"Quando há início da proteinúria em pacientes com duração do DM inferior a 5 anos, em especial\nno DM1.","B":"Devido ao início da proteinúria abrupto e rapidamente progressivo, não compatível com o curso\nclínico da Doença Renal do Diabetes (DRD).","C":"Achados alterações no sedimento urinário, como cilindros hemáticos, leucocitários e acantócitos;\nmanifestações clínicas de outra doença sistêmica e ausência de retinopatia e neuropatia em\npacientes com DM1, visto que nestes a retinopatia diabética precede o surgimento de Doença\nRenal do Diabetes (DRD).","D":"Nos pacientes com DM2, a ausência de retinopatia e neuropatia excluem Doença Renal do\nDiabetes (DRD), pois apenas 5% dos pacientes com DM2 proteinúricos, com diagnóstico de ND\nconfirmado por biópsia, apresentam retinopatia diabética."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161207","number":"161207","sourceNumber":"161207","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro dos critérios diagnósticos de diabetes na população pediátrica, marque a\nalternativa considerada INCORRETA.","options":{"A":"Um terço dos jovens com DM2 utilizava insulina, e somente 22% dos com DM1 não\napresentavam insulina endógena, sugerindo que uma\ngrande fração desses jovens parece ter\ndiabetes de etiologia mista.","B":"O diagnóstico de DM2 na infância deverá ser feito levando-se em consideração critérios clínicos,\ncomo idade e sexo do paciente, obesidade e história familiar positiva para DM2.","C":"Devido à alta miscigenação brasileira, não existem dados, até o momento, para considerar a cor\ncomo fator de risco.","D":"Os níveis para a glicemia de jejum, com base nos critérios atualmente adotados para o\ndiagnóstico do DM2, não são os mesmos para adultos ou crianças."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161308","number":"161308","sourceNumber":"161308","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro dos conceitos de doença renal do diabetes (DRD), a base nos valores\ncrescentes de excreção urinária de albumina\n(EUA), a DRD tem sido historicamente classificada em\nfases. Entretanto, a progressão destes estágios não é inexorável, podendo ocorrer regressão da\nmicroalbuminúria em cerca de 30% dos pacientes, em geral associada a intervenções terapêuticas.\nAponte a alternativa que NÃO faz parte dessas fases.","options":{"A":"Normoalbuminúria.","B":"Hipoalbuminúria.","C":"Microalbuminúria.","D":"Macroalbuminúria."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161196","number":"161196","sourceNumber":"161196","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nos quadros de Cetoacidose Diabética (CAD), a maioria dos casos fatais está\nrelacionada ao desenvolvimento de edema\ncerebral, que ainda é uma complicação observada em\n0,5% a 2% dos pacientes com CAD, com mortalidade de 40 a 90%, e capaz de produzir sequelas\nentre 10 a 25% dos sobreviventes. Outras causas de mortalidade e morbidade frequentes são,\nEXCETO.","options":{"A":"Hipermagnesemia.","B":"Hipocalemia.","C":"Alterações do sistema nervoso central.","D":"Infecções."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161200","number":"161200","sourceNumber":"161200","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Entre os critérios laboratoriais para diagnóstico da Cetoacidose Diabética, aponte o\núnico INCORRETO.","options":{"A":"O pH (venoso ou arterial) inferior a 7,3 e/ou bicarbonato de sódio inferior a 15 mEq/L.","B":"Glicemia superior a 200 mg/dL.","C":"Presença de cetonemia e/ou cetonúria.","D":"Potássio sérico menor que 3 mEq/L."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-161119","number":"161119","sourceNumber":"161119","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação à cetoacidose diabética, assinale a alternativa CORRETA.","options":{"A":"A cetoacidose diabética é considerada grave quando o bicarbonato sérico estiver entre 12 e 18\nmEq/L.","B":"A infusão contínua de insulina reduz a glicemia e também o potássio sérico.","C":"A infusão contínua de insulina reduz a glicemia e promove a entrada do sódio sérico.","D":"A infusão contínua de insulina reduz a glicemia e promove o aumento no ânion-gap."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-134086","number":"134086","sourceNumber":"134086","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente deu entrada no hospital agitado, com mal-estar, respondendo pouco durante a\nentrevista, mas referindo ser diabético em uso de glimepirida. Foram, então, solicitados exames,\ncomo glicose, hemograma e exame de urina. Assim, foi diagnosticado Infecção Urinária e achado\num valor de glicose sanguínea de 58 mg/dl. Realizada infusão de glicose EV. Sobre esse caso,\npodemos afirmar que","options":{"A":"somente valores de dextro abaixo de 40 confirmam o diagnóstico de hipoglicemia.","B":"caso ocorra reversão do quadro, está confirmado o diagnóstico de hipoglicemia.","C":"provavelmente a agitação se deve somente a ITU.","D":"o quadro clínico não é compatível com hipoglicemia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-134845","number":"134845","sourceNumber":"134845","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente diabético tipo 2, em uso de sulfanilureias, evolui com quadro de hipoglicemia\nque é tratado prontamente com infusão de\nglucagon. A seguir o paciente é liberado, porém\nretornando algumas horas depois com quadro de coma e achado de uma glicemia capilar de 45\nmg/dl. Podemos assim AFIRMAR que isso","options":{"A":"Ocorreu por ineficiência do glucagon.","B":"Ocorreu porque os efeitos do hipoglicemiante da família das sulfanilureias estende-se por várias\nhoras.","C":"Ocorreu devido à ingesta errática de medicação oral.","D":"É secundário ao quadro infeccioso subclínico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-134288","number":"134288","sourceNumber":"134288","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Podemos correlacionar a ocorrência da Cetoacidose Diabética com diversas situações\nclínicas, com EXCEÇÃO de uma das alternativas. Aponte-a.","options":{"A":"Primeira manifestação da doença.","B":"Uso de cocaína.","C":"Maus hábitos alimentares.","D":"Infarto do miocárdio."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-109739","number":"109739","sourceNumber":"109739","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, dá entrada no pronto-socorro com rebaixamento\ndo nível de consciência. É realizada uma\nglicemia capilar com resultado de 25 mg/dl. É colhida\namostra de sangue no mesmo momento, enviada para dosagem de glicose, insulina, peptídeo C e\nsulfonilureia. Glicemia = 23 mg/dl, insulina plasmática = 17 mU/l (normal: 2-19 mU/l), peptídeo C =\nindetectável (normal: 1,2-4,5 ng/ml), dosagem de sulfonilureia negativa. Exame físico sem\nalterações. Exames laboratoriais revelam função renal, tireoidiana e hepática normais. Assinale\nabaixo o diagnóstico MAIS provável:","options":{"A":"Insulinoma.","B":"Intoxicação por metformina.","C":"Hipoglicemia factícia.","D":"Glucagonoma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-86829","number":"86829","sourceNumber":"86829","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"As afirmativas abaixo referem-se a condutas em pacientes com cetoacidose diabética.\n\nI. A reposição de insulina é a prioridade máxima; II. A hidratação com Cloreto de sódio a 0,9%\ndiminui a glicemia do indivíduo em torno de 25% da glicemia independente de administração de\ninsulina; III. Cloreto de sódio a 0,9% é o coloide de primeira escolha.","options":{"A":"Somente afirmativa II está correta;","B":"Somente afirmativas II, III estão corretas;","C":"Somente afirmativa III está correta;","D":"Somente afirmativas I, III estão corretas;","E":"Somente afirmativa I está correta."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-86646","number":"86646","sourceNumber":"86646","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A colecistectomia profilática, nos pacientes com colelitíase assintomática, está indicada\nnas seguintes situações:","options":{"A":"Vesícula em porcelana.","B":"Doentes imunossuprimidos.","C":"Gastrectomia para neoplasia ou obesidade mórbida.","D":"Nenhuma das situações acima.","E":"Todas as situações clínicas mencionadas acima."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-86660","number":"86660","sourceNumber":"86660","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente em pós-operatório tardio de cirurgia bariátrica apresenta, após alimentação\nhipercalórica, quadro de mal-estar, sudorese, hipotensão arterial, sensação de desmaio. Qual\ndiagnóstico clínico mais aproximado?","options":{"A":"Síndrome da alça aferente.","B":"Síndrome da alça eferente.","C":"Síndrome do Y de Roux.","D":"Síndrome de ?dumping?.","E":"Síndrome do desfiladeiro."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108589","number":"108589","sourceNumber":"108589","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre a nefropatia diabética, é INCORRETO afirmar que:","options":{"A":"Microalbuminúria é marcador de lesão endotelial.","B":"Proteinúria instalada pode ser combatida com os IECA e BRA.","C":"Pacientes com nefropatia avançada também costumam ter lesões ao exame de fundo de olho.","D":"Proteinúria de Bence Jones deve ser solicitada rotineiramente para avaliação de lesão renal\ndeclarada.","E":"Todas as anteriores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-362423","number":"362423","sourceNumber":"362423","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Na cetoacidose diabética, qual é a principal alteração de eletrólitos que pode ocorrer\ndurante o tratamento?","options":{"A":"Hiponatremia","B":"Hipernatremia","C":"Hipocalemia","D":"Hipercalemia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298199","number":"298199","sourceNumber":"298199","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre as medicações utilizadas no tratamento do DM2, assinale a alternativa\nCORRETA:","options":{"A":"A metformina reduz a absorção de cianocobalamina no íleo distal, podendo levar a deficiência\nde vitamina B12; por isso, é recomendado que\nseus níveis sejam dosados anualmente após 4 anos\nde início de seu uso.","B":"A pioglitazona promove redução da glicemia por meio da inibição do receptor SGLT-2, com\nconsequente inibição da reabsorção renal de glicose no túbulo contorcido proximal, levando à\nglicosúria.","C":"As gliflozinas podem, entre outros eventos adversos, levar a retenção hídrica; dessa forma,\npodem agravar ou desencadear insuficiência\ncardíaca (IC), estando contra- indicadas em pacientes\ncom IC classe III e IV da New York Heart Association (NYHA).","D":"Os análogos do receptor do GLP-1 agem no controle glicêmico ao reduzir a secreção de insulina\ndependente de glicose, ao mesmo tempo que aumentam a secreção de glucagon."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298278","number":"298278","sourceNumber":"298278","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um dos principais motivos de consultas de condições crônicas em APS diz respeito ao\nacompanhamento de pacientes com Diabetes Mellitus, sendo necessário avaliação constante do\nrisco cardiovascular, da adesão ao tratamento, das metas glicêmicas e de lesões de órgãos-alvo.\nSobre a sistematização desse seguimento podemos afirmar CORRETAMENTE que:","options":{"A":"O exame de microalbuminúria deve ser solicitado somente em diabéticos com Hipertensão\nArterial Sistêmica associada, uma vez que sua\npresença isoladamente não possui bom valor\npreditivo positivo para nefropatia diabética.","B":"É necessário orientar sobre sinais de hipoglicemia, mais comuns em pacientes que usam\nmetformina quando comparados aos que utilizam insulina.","C":"O exame dos pés é essencial para avaliação do pé diabético e a presença de alterações\narticulares de qualquer grau é indicação de\nencaminhamento à cirurgia vascular para amputação.","D":"A investigação de retinopatia diabética deve se iniciar no momento do diagnóstico em pacientes\ncom DM2."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-286699","number":"286699","sourceNumber":"286699","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nQual hipótese mais provável do quadro?","options":{"A":"Hipernatremia sintomática.","B":"Cetoacidose diabética.","C":"Acidente vascular cerebral.","D":"Estado hiperosmolar não cetótico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-286700","number":"286700","sourceNumber":"286700","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nO tratamento do quadro acima inclui várias condutas; em relação a insulina, qual seria sua\nprescrição?","options":{"A":"Insulina regular SC conforme esquema: 0-180mg/dl: 4U; 181-240: 6U; 241-300: 8U","B":"Insulina NPH SC 0,3u/kg de peso, dividido em 2/3 pela manhã e 1/3 a noite","C":"Insulina regular intravenosa em bomba infusora após bolus de 0,1u/kg","D":"Insulina lantus 0,3u por kilo de peso, 1x ao dia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-286701","number":"286701","sourceNumber":"286701","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nEm relação ao potássio, qual seria sua conduta?","options":{"A":"Não há necessidade de reposição, já que o tratamento do quadro irá normalizar essa alteração\nhidroeletrolítica.","B":"Repor 20-30meq de potássio nas primeiras 24 horas do tratamento.","C":"Repor 20-30meq de potássio a cada litro de solução usada na hidratação.","D":"Iniciar reposição de potássio, 20- 30meq/hora, antes da aplicação de insulina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-256574","number":"256574","sourceNumber":"256574","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"De acordo com as Diretrizes da Sociedade Brasileira de Diabetes (SBD), os fatores de\nrisco adicionais para Diabetes Mellitus 2 vão desde a história materna de diabetes gestacional,\nhistória familiar em parentes de primeiro ou segundo grau; raça/etnia e presença ou não de sinais\nde resistência à insulina. Dos critérios abaixo qual NÃO corresponde ao diagnóstico do\n\nPré-Diabetes?","options":{"A":"Glicemia de jejum de 112 mg/dl;","B":"Glicemia de jejum de 124 mg/dl;","C":"\"Glicemia pós 2 h após sobrecarga com 75 g de glicose: >160 mg/dL;\"","D":"Hb A1C maior que 6,5%."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-252211","number":"252211","sourceNumber":"252211","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação à insulinoterapia no Diabetes Mellitus tipo 1 (DM1), assinale a alternativa\nINCORRETA:","options":{"A":"Na fase de ?lua de mel? do DM 1, ou seja, fase de remissão inicial, período compreendido até 2\nanos após o diagnóstico da doença, a dose de\ninsulina diária deve variar entre 0,8 a 1 U/kg/dia.","B":"Na prescrição de insulina para o DM 1, a dose depende da idade, do peso, tempo de doença,\nhorário das refeições, monitoramento glicêmico, HbA1c pretendida, nível de atividade física e\nintercorrências.","C":"A dose basal diária de insulina deve ser em torno de 40% a 60% da dose total de insulina\ncalculada, sendo o restante da dose administrada em forma de bolus antes das refeições.","D":"O esquema de insulinoterapia deve incluir insulina de ação intermediária ou lenta e a insulina de\nliberação rápida ou ultrarrápida, com doses fracionadas em três a quatro aplicações diárias,\nrespeitando a farmacocinética da insulina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-252273","number":"252273","sourceNumber":"252273","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"F.T.S., 4 anos, 16 kg, masculino, teve diagnóstico de diabetes há 9 meses, chegou ao\npronto-socorro com quadro de desidratação, dor abdominal, hálito cetônico e os seguintes exames:\nglicose = 760 mg/dl; Na = 130 mEq/L; K = 4,4 mEq/L. Recebeu 1.500 ml de Soro Fisiológico (SF\n0,9%) e insulina regular contínua por 6 horas. Os exames após esse período são: pH = 7,1; pCO2 =\n20; Bic = 12; Na = 138; Cl = 117; K = 3,5; glicose = 180. A provável etiologia da acidose ao final\ndas\n6 horas do tratamento inicial é:","options":{"A":"Acidose por acúmulo de ácidos não mensuráveis, pois ânion-gap é normal.","B":"Acidose hiperclorêmica, pois ânion-gap é aumentado.","C":"Acidose hiperclorêmica, pois ânion-gap é normal.","D":"Acidose por acúmulo de ácidos não mensuráveis, pois ânion-gap é aumentado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-252277","number":"252277","sourceNumber":"252277","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Menina de 5 anos comparece ao pronto-socorro com queixa de náusea, vômitos e dor\nabdominal há 1 dia, com piora agora após ingerir doce em uma festa infantil. Nega diarreia. Refere\nurina em grande quantidade, e voltou a ter enurese noturna há 1 semana. Nega alteração da cor ou\nodor da urina. Ao exame: criança desidratada de 2° grau, hipoativa, porém pedindo para beber\nágua, taquicárdica, porém sem alterações na ausculta cardíaca, taquipneica, porém sem alterações\nna ausculta pulmonar, abdome doloroso a palpação profunda difusamente, sem outras alterações.\nQual sua principal hipótese diagnóstica e conduta nesse caso?","options":{"A":"Diabetes Mellitus, solicitar para colher glicemia amanhã após jejum de 8 horas.","B":"Gastroenterocolite Aguda (GECA), soro de rehidratação via oral.","C":"Diabetes Mellitus, realizar glicemia agora.","D":"Gastroenterocolite Aguda (GECA), soro de rehidratação endovenoso."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-252307","number":"252307","sourceNumber":"252307","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um dos problemas mais frequentes que ocorrem nas UBS é o Diabetes Mellitus.\nAssinale a alternativa CORRETA com relação\naos métodos empregados como parâmetros de\ncontrole do diabetes:","options":{"A":"A HbA1c é um método consolidado que reflete a glicemia média nos últimos quatro meses, e\nseus níveis possuem um grande valor preditivo com o desenvolvimento de complicações.","B":"A glicemia plasmática em jejum é atualmente o mais preciso método para avaliar o controle do\ndiabetes a médio e longo prazos.","C":"A monitorização de glicemia capilar é um método amplamente disponível, que possui a melhor\nrelação custo-efetividade para pacientes que não utilizam insulina.","D":"Estudos comprovam que o uso, de maneira isolada, da monitorização de glicemia capilar como\nforma de avaliar o controle metabólico consiste na melhor maneira de reduzir os níveis glicêmicos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-208450","number":"208450","sourceNumber":"208450","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Jovem de 22 anos, portador de Diabetes Mellitus tipo 1 desde os 11 anos de idade,\nsem complicações crônicas, em terapia insulínica\nbasal/bolus desde o início do quadro. Atualmente,\ncom insulina degludeca como insulina basal, e lispro como insulina para o bolus corretivo e\nalimentar antes das três principais refeições. Hoje, a glicemia capilar de jejum foi de 132 mg/dl,\nantes do almoço 142 mg/dl e antes do jantar 151 mg/dl, não precisando de bolus corretivo em\nnenhuma das refeições, somente bolus alimentar, ao qual fazia por contagem de carboidratos (CH).\nAjude o paciente efetuando o cálculo de quanto ele irá aplicar de insulina lispro ao ingerir 60 g de\nCH no café, 75 g no almoço e 45 g no jantar, utilizando a razão insulina/carboidrato de 1:15 no café\ne almoço, e 1:20 no jantar.","options":{"A":"06 U; 08 U e 10 U.","B":"04 U; 05 U e 02 U.","C":"18 U; 19 U e 14 U.","D":"08 U; 10 U e 06 U."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-151931","number":"151931","sourceNumber":"151931","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma senhora negra, de 58 anos, obesa (IMC: 39 kg/m²) deu entrada no pronto-socorro\nda cidade por apresentar, nas últimas semanas,\nquadro álgico de membros inferiores,\nacompanhado de sensação de \"agulhadas\" nas pernas e pés, principalmente ao se deitar. Ainda\ncitou poliúria, polidipsia e disúria, que acentuaram na última semana. Notou, também, perda de\npeso (em torno de 12 kg) no último mês, mesmo sem fazer modificações na dieta. Ao contrário, no\ninquérito alimentar, declarou ingerir maior quantidade de massas e frituras. Não costumava fazer\nexercícios regulares. Exames do PS: glicemia aleatória = 360 mg/dl. No dia seguinte, colheu\nexames em jejum, com os seguintes resultados: hemograma e ionograma normais; glicemia = 228\nmg/dl; HbA1c = 10,8%; ureia = 44; Cr = 0,98; TGP = 46; TGO = 38; GGT = 58 e EAS com\n\nincontáveis piócitos. Baseado no caso acima descrito, assinale a resposta CERTA. No caso\nespecífico, de acordo com as diretrizes da\nSociedade Brasileira de Diabetes (SBD), o diagnóstico\nde DM 2 foi dado a partir de qual critério abaixo?","options":{"A":"Pelos níveis de HbA1c > 6,5%.","B":"Pela glicemia \"maior ou igual a\" 200 mg/dl, colhida 2h pós-sobrecarga de 75 g de glicose.","C":"Devido aos sintomas de poliúria, polidipsia e perda ponderal, associado à glicemia casual \"maior\nou igual a\" 200 mg/d.","D":"Glicemia de jejum \"maior ou igual a\" 126 mg/d, sendo o diagnóstico confirmado pela repetição\nda glicemia no dia seguinte."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-129730","number":"129730","sourceNumber":"129730","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual substância é produzida e liberada em quantidades equimolares à insulina pela\ncélula beta do pâncreas?","options":{"A":"Glucagon.","B":"Polipeptídeo pancreático.","C":"Peptídeo C.","D":"Somatostatina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-107757","number":"107757","sourceNumber":"107757","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"No diabetes tipo 1, como na maioria das vezes, ocorre a destruição autoimune das\ncélulas beta, o tratamento consiste na\nreposição com insulina de acordo com as características da\nsecreção fisiológica. Assinale abaixo a resposta INCORRETA:","options":{"A":"Os análogos de insulina de ação ultrarrápida podem ser aplicados logo após o término da\nrefeição, dessa maneira são mais seguras em crianças pequenas e idosos.","B":"A hipoglicemia é o fator mais limitante do alcance do controle glicêmico ideal em DM1.","C":"A insulina Glulisina ou NPH são ideias para cobertura basal associada à insulina lispro ou\nregular no uso pré-prandial, nas principais refeições.","D":"A insulina NPH apresenta em sua composição a protamina, que permite aumentar seu tempo de\nação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-107780","number":"107780","sourceNumber":"107780","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação aos nódulos de tireoide, marque a afirmativa CORRETA:","options":{"A":"Os nódulos de tireoide incidem em maior frequência em homens, jovens, pessoas expostas à\nradiação ionizante ou oriundos de áreas endêmicas de excesso de iodo.","B":"Sintomas compressivos, hemorragias ou extensão intratorácica só acontecem nos nódulos\nmalignos.","C":"A maioria é assintomático, porém podem apresentar disfunções associadas como\nhipertireoidismo e hipotireoidismo.","D":"Presença de múltiplos nódulos é considerado fator preditivo de benignidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-107963","number":"107963","sourceNumber":"107963","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"No curso de diabetes mellitus tipo I, a nefropatia incipiente pode ser diagnosticada na\npresença de:","options":{"A":"Proteinúria > 500 mg nas 24 horas.","B":"Clearence de creatinina < 80 ml/min.","C":"Microalbuminúria.","D":"Hipertensão arterial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-80927","number":"80927","sourceNumber":"80927","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A hiperglicemia crônica, comum ao Diabetes Mellitus tipos 1 e 2, responsável pelas\ncomplicações micro e macrovasculares e os consequentes desfechos desfavoráveis, pode ser\nmenos deletéria quando o controle é baseado em metas. Assinale abaixo a meta para controle de\nadultos diabéticos da Hemoglobina A1C, (método HPLC = \"High Performance Liquid\nChromatography\" ou CLAE = Cromatografia Líquida de Alta Eficiência) preconizada nas Diretrizes\nBrasileiras de Diabetes Mellitus (2012-1013).","options":{"A":"< 6%","B":"< 7%","C":"< 5%","D":"< 8%","E":"< 9%"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-80932","number":"80932","sourceNumber":"80932","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Das classes de drogas usadas no tratamento do diabetes mellitus do tipo 2, as que\ninduzem a secreção de insulina somente na presença de glicose (glicose-dependente) são:","options":{"A":"Glitazona e Biguanidas.","B":"Análogos do GLP-1 e inibidores da DPP-4.","C":"Inibidor da Alfaglicosidase e Sulfonilureias.","D":"Sulfonilureias e Gliptinas.","E":"Biguanidas e Análogos do GLP-1."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-81979","number":"81979","sourceNumber":"81979","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação ao diabetes tipo 2 no jovem, marque a alternativa CORRETA.","options":{"A":"Está frequentemente associado à obesidade.","B":"A incidência vem diminuindo nos últimos anos.","C":"O tratamento requer insulina, na maioria dos casos.","D":"Os anticorpos anti-GAD são frequentemente positivos.","E":"O componente genético, parentes em primeiro e segundo grau com DM, não é frequente."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-81985","number":"81985","sourceNumber":"81985","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Criança apresenta história de vômitos, poliúria e desidratação. Ao exame físico nota-se\nrespiração de Kussmaul e odor de \"acetona\" no hálito. Queixa ainda dor abdominal e evoluiu com\nembotamento cerebral. A hipótese mais provável para o quadro clínico descrito é:","options":{"A":"Cetoacidose diabética","B":"Intoxicação por salicilato","C":"Encefalite","D":"Septicemia","E":"Uremia"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-61579","number":"61579","sourceNumber":"61579","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Das drogas utilizadas no tratamento do Diabetes Mellitus tipo 2, assinale abaixo o\nmecanismo de ação dos incretinomiméticos:","options":{"A":"Retarda a absorção intestinal de glicose. Eficácia associada ao uso pré-prandial para prevenção\nda hiperglicemia pós-prandial.","B":"Estimulam as células beta a aumentar a síntese de insulina e atuam nas células alfa do\npâncreas reduzindo a produção de glucagon.","C":"Estimulam a produção endógena de insulina pelas células beta do pâncreas, com duração\nrápida de ação (1-3 horas). Úteis para o controle da hiperglicemia pós-prandial.","D":"Combate primariamente a resistência à insulina e reduz a produção hepática da glicose.\n\nAumentando a sensibilidade do músculo, tecido gorduroso e fígado à insulina.","E":"Estimulam a produção endógena de insulina pelas células beta do pâncreas, com duração de\nação de média a prolongada (8-24 horas).\nÚteis para o controle da glicemia de jejum e da glicemia\nde 24 horas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-61508","number":"61508","sourceNumber":"61508","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quanto à cirurgia bariátrica podemos afirmar que:","options":{"A":"Gastrectomia vertical não está indicada na polipose gástrica.","B":"Está contraindicada em pacientes com doenças psiquiátricas graves, sem controle.","C":"As técnicas mistas, como a de Scopinaro, são as mais utilizadas.","D":"Não ocorre controle pós-operatório das comorbidades, com diabetes, hipertensão arterial, sendo\numa cirurgia essencialmente estética.","E":"O acompanhamento multidisciplinar somente é necessário durante o pré-operátorio."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-60851","number":"60851","sourceNumber":"60851","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre o Diabetes Mellitus, podemos afirmar, EXCETO:","options":{"A":"Outro critério diagnóstico é a glicemia de jejum maior ou igual a 126 mg/dL.","B":"Seus sintomas clássicos são poliúria, polidipsia, polifagia e perda voluntária de peso.","C":"É classificado em tipos I e II, sendo o tipo II acompanhado, preferencialmente, na Atenção\nBásica.","D":"Um de seus critérios diagnósticos é a presença de glicemia casual maior ou igual a 200 mg/dL.","E":"Entre os fatores de risco associados estão: idade maior a 45 anos, sobrepeso, obesidade\ncentral, história familiar de diabetes,\nhipertrigliceridemia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-46653","number":"46653","sourceNumber":"46653","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A gliconeogênese processada no fígado e no rim é ativada utilizando-se a\n( ) derivada do músculo.","options":{"A":"Treonina","B":"Glutamina","C":"Albumina","D":"Triptofano","E":"Arginina"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-46640","number":"46640","sourceNumber":"46640","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Menina de 12 anos de idade, com diabetes tipo 1, deu entrada em um serviço de\nemergência com Cetoacidose Diabética (CAD).\nApós insulinoterapia (em infusão contínua) e\ncorreção da desidratação, houve redução importante da glicemia e normalização do pH sanguíneo,\nmas a cetonúria, medida por fita reagente, acentuou-se. Com relação a este caso, qual a conduta\nmais apropriada?","options":{"A":"Aumentar a velocidade da infusão endovenosa de insulina.","B":"Pesquisar uma fonte não identificada de infecção.","C":"Manter o esquema terapêutico utilizado, já que o comportamento observado da cetonúria é\nnormal.","D":"Mudar o tipo de insulina que vinha sendo utilizado.","E":"Nenhuma das alternativas anteriores."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-46649","number":"46649","sourceNumber":"46649","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual a principal medida preventiva contra o pé diabético?","options":{"A":"Realização períodica de arteriografias digitais.","B":"Realizar exames clínicos sistemáticos dos pés e pernas.","C":"Utilização de sapatos especiais.","D":"Manter a Hb glicosilada menor que 10%.","E":"Realizar periodicamente ultrassonografias de fluxo dos membros inferiores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-34161","number":"34161","sourceNumber":"34161","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São fatores predisponentes para cetoacidose diabética, EXCETO:","options":{"A":"Acromegalia.","B":"Infarto agudo do miocárdio.","C":"Terapia com glicocorticoides.","D":"Insuficiência renal crônica.","E":"Infecção das vias urinárias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-34162","number":"34162","sourceNumber":"34162","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São manifestações da neuropatia autonômica diabética, EXCETO:","options":{"A":"Diminuição da libido.","B":"Anidrose.","C":"Hipotensão ortostática.","D":"Bexigoma.","E":"Disfunção erétil."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-34301","number":"34301","sourceNumber":"34301","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Maira, 38 anos, está em acompanhamento em sua Unidade Saúde da Família há 3\nanos. Apresenta Diabetes há 2 anos e está em\nuso de Metformina 850 mg por dia. Refere perda de\npeso recente e prurido vulvar. Hoje, ela está com 86 kg, tem 1,69. Pressão arterial de 126 X 72\nmmHg. No acompanhamento desta paciente, devemos, EXCETO:","options":{"A":"Solicitar glicemias mensais e dosagem da hemoglobina glicada trimestral até controle glicêmico.","B":"O quadro clínico de Maira é sugestivo de hiperglicemia e sua glicemia capilar deve ser dosada\npara confirmação.","C":"Podemos aumentar a dose da Metformina até 2550 mg por dia divida em até 3 tomadas.","D":"Maira deve ser vacinada anualmente contra influenza e receber uma dose de vacina\nantipneumocócica.","E":"A metformina é a medicação de escolha para Maira pelo sobrepeso, mas devemos ter cuidado\ncom o risco de hipoglicemia que acarreta."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-26444","number":"26444","sourceNumber":"26444","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quanto ao diabetes Mellitus tipo 1, assinale a afirmativa INCORRETA:","options":{"A":"na maioria das vezes resulta da destruição autoimune das células beta pancreáticas","B":"os anticorpos anti-ilhotas, anti-insulina e anti-GAD podem estar presentes antes das\nmanifestações clínica","C":"é sempre dependente do tratamento com insulina","D":"a concordância para diabetes em gêmeos idênticos é de quase 100%, sugerindo portanto,\ncomponente genético importante","E":"pode surgir em qualquer idade, porém é mais frequente antes 30 anos"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-26598","number":"26598","sourceNumber":"26598","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual das seguintes situações não aumenta as necessidades de insulina do paciente?","options":{"A":"Necessidade de cortioterapia","B":"Presença de infecção urinária","C":"Insuficiência Renal","D":"Ganho de peso","E":"Problemas emocionais"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-26474","number":"26474","sourceNumber":"26474","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Escolar de 10 anos, diabético tipo 1, insulinodependente , é levado ao ambulatório\ndevido dificuldade controle glicêmico pela manhã ao\nacordar. Segundo sua mãe a criança acorda\nno início da madrugada com cefaleia e sudorese fria, mas pela manha a glicemia capilar\nencontra-se sempre elevada e a glicosúria é positiva. Em uso de insulina intermediária e rápida\n(3U/kg/dia) em esquema de 12/12h. Qual a provável causa da instabilidade glicêmica desta\ncriança?","options":{"A":"Infecção recorrente;","B":"Hipersensibilidade a insulina;","C":"Período de lua de mel;","D":"dose baixa de insulina;","E":"Fenômeno de Somogyi."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-26627","number":"26627","sourceNumber":"26627","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Isabel tem 42 anos é tabagista, hipertensa e apresenta índice de massa Corporal de 32\nkg/m². Veio a sua primeira consulta na Unidade Saúde da Família e refere ser dislipidêmica. Ao\nfinal da consulta, solicita ao médico uma prescrição de medicação para perder peso. A melhor\nconduta no caso é:","options":{"A":"indicar cirurgia bariátrica pois o IMC está elevado , associado a co-morbidades.","B":"prescrever anfetaminas para auxiliar a redução de peso e servir de estímulo a paciente","C":"estimular a reeducação alimentar e atividade física regular","D":"prescrever sibutramina por ser mais seguro e pelo aumento da saciedade","E":"desestimular o abandono do cigarro visto que aumentará o peso"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-7474","number":"7474","sourceNumber":"7474","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Embolia Pulmonar tem uma frequência que varia de 20 a 25 por 100.000 pacientes\nhospitalizados nos E.U.A. São causas de tromboembolia pulmonar, exceto:","options":{"A":"Cirrose hepática.","B":"Policitemia.","C":"Uso de anovulatório.","D":"Câncer disseminado.","E":"Fibrilação atrial."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-7522","number":"7522","sourceNumber":"7522","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre o diagnóstico da asma, assinale a alternativa INCORRETA:","options":{"A":"A espirometria confirma a obstrução do fluxo de ar, com VEF1 e peak flow diminuídos.","B":"A radiografia de tórax é geralmente normal.","C":"O exame físico costuma ser normal entre as crises de asma.","D":"Os níveis de IgE costumam estar elevados.","E":"Assim como na doença pulmonar obstrutiva crônica (DPOC) a obstrução das vias aéreas é\nirreversível na asma."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-10019","number":"10019","sourceNumber":"10019","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Marque a alternativa INCORRETA com relação às complicações crônicas do Diabete\nMellitus.","options":{"A":"A isquemia miocárdica silenciosa é mais comum em diabéticos do que na população geral.","B":"A sintomatologia da polineuropatia simétrica crônica distal é mais intensa à noite.","C":"A mononeuropatia mais frequente é a do terceiro par craniano.","D":"A Eritromicina mostra-se útil no tratamento da disfunção autonômica gastro-intestinal\n(gastroparesia diabeticorum).","E":"A retinopatia pode já estar presente na ocasião do diagnóstico de pacientes com DM 1."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-294482","number":"294482","sourceNumber":"294482","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Adolescente, 16 anos de idade, chega à UBS com quadro de poliúria há,\naproximadamente, 40 dias. Refere fadiga\nfrequente, o que atribui ao aumento de peso, durante a\npandemia. Nega febre, disúria e outros sintomas. Ao exame, IMC: 29kg/m²; acima do 95º percentil;\nbom estado geral, eupneica, hidratada, afebril, corada. Apresenta eritema macular hiperemiado sob\nambas as mamas, pruriginoso. O exame de urina I mostra: pH: 7,2; Densidade: de 1,01; Ausência\nde cetonas, bilirrubina, urobilinogênio, sangue e nitrito; presença de glicose ++; raros leucócitos\ne\nraras células epiteliais. Glicemia em jejum foi de 100mg/dL Indique o exame que permite melhor\navaliar o diagnóstico associado dessa paciente.","options":{"A":"Cortisol matinal.","B":"Hemoglobina glicada.","C":"Glicemia aleatória.","D":"Triglicérides."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-294492","number":"294492","sourceNumber":"294492","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O Brasil apresenta um perfil epidemiológico complexo, com uma sobreposição de\nproblemas de saúde, muitas vezes, no mesmo território: persistência de alguns agravos\ntransmissíveis e ocorrência de ciclos epidêmicos de outros; peso importante, e crescente, na\nmorbidade e na mortalidade das doenças crônicas não transmissíveis; e alta ocorrência de\nacidentes e violência. Essa múltipla carga se concentra, principalmente, nos grupos mais\nvulneráveis do ponto de vista social e econômico, como resultado das profundas desigualdades\nque ainda persistem. Esse quadro, também condicionado pelos rápidos processos de urbanização\ne de envelhecimento da população, exige que o SUS realize análises e planejamentos capazes de\nencontrar as melhores estratégias para garantir o efetivo acesso da população, ao mesmo tempo\nque lidere agendas multissetoriais que incidam nos determinantes sociais e econômicos. No grupo\ndas doenças crônico degenerativas, as doenças cardiovasculares ocupam importante papel como\ncausa de morbimortalidade no Brasil. A melhor forma de atenuar essa causa, em termos de\n\ncusto-eficácia, é","options":{"A":"promover o controle da hipertensão arterial.","B":"reduzir o sedentarismo da população.","C":"modificar hábitos alimentares.","D":"reduzir o tabagismo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284576","number":"284576","sourceNumber":"284576","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher, 20 anos de idade, estava acompanhada da mãe no metrô quando apresentou\nperda da consciência, seguida de rigidez\nmuscular, abalos musculares difusos e perda\nesfincteriana. A equipe do metrô iniciou rapidamente os primeiros-socorros, colocando algo macio\nsob a cabeça da paciente até cessarem os abalos, que duraram cerca de um minuto. A mãe ficou\nbastante assustada e relatou que a paciente era portadora de diabetes mellitus tipo 1. Nega outras\ncomorbidades. Nunca havia apresentado quadro semelhante. Neste momento, a paciente\nencontra-se ainda inconsciente, com ventilação espontânea. Indique o exame complementar e a\nmedicação mais adequada nesse momento.","options":{"A":"Eletroencefalograma e diazepam intravenoso.","B":"Tomografia de crânio e diazepam intravenoso.","C":"Glicemia capilar e insulina subcutânea.","D":"Glicemia capilar e glucagon subcutâneo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-62874","number":"62874","sourceNumber":"62874","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Pacientes submetidos à cirurgia bariátrica apresentam maior risco de complicação\nquando:","options":{"A":"Tiverem idade < 40 anos.","B":"IMC > 60 kg/m².","C":"Cursarem com dislipidemia.","D":"Forem portadores de refluxo gastroesofágico.","E":"O teste ergométrico for negativo para isquemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-62847","number":"62847","sourceNumber":"62847","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo masculino, 26 anos de idade, sem outras comorbidades, no\n\npós-operatório tardio de cirurgia bariátrica, evolui com dor em mesogástrio tipo cólica, sem\nvômitos,\ncom parada na eliminação de flatos e fezes. A\nconduta mais indicada deve ser:","options":{"A":"Iniciar hidratação, realizar RX de abdome, iniciar analgesia e realizar videolaparoscopia\ndiagnóstica.","B":"Realizar USG abdominal e indicar colecistectomia laparoscópica.","C":"Solicitar endoscopia digestiva e tratar impactação alimentar.","D":"Solicitar TC abdominal com pesquisa de ureterolitíase e encaminhar para avaliação com\nurologista.","E":"Iniciar hidratação e analgesia, administrar antiemético e dar alta hospitalar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-62875","number":"62875","sourceNumber":"62875","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, sexo feminino, 23 anos de idade, cursa com dor em fossa ilíaca esquerda e\npélvica, há 10 dias, associada a corrimento vaginal amarelado e fétido. Relata menstruação regular\ne vida sexual ativa. Ao exame, a paciente encontra-se afebril e sem sinais de SRIS. O abdome é\ndoloroso à palpação da região hipogástrica e na fossa ilíaca esquerda, com leve dor à\ndescompressão brusca. Solicitadas ultrassonografia abdominal, pélvica e transvaginal,\nevidenciaram pequena quantidade de líquido livre no fundo de saco posterior. É contraindicação\npara cirurgia bariátrica:","options":{"A":"risco cirúrgico ASA III.","B":"idade inferior a 18 anos.","C":"ausência de dependência química.","D":"IMC (índice de massa corpórea) maior que 35 kg/m² associado a linfedema e a diabetes de\ndifícil controle.","E":"hipertensão portal com varizes esofágicas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-62878","number":"62878","sourceNumber":"62878","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É o fator de risco mais temido na atualidade. Sua prevalência está mundialmente em\npatamares de epidemia e, no Brasil, constitui problema de saúde em todos os grupos etários, da\ncriança ao adulto maduro, e, em menor proporção nos idosos. Difere entre homens e mulheres e\nentre regiões, sendo mais elevada nas regiões de maior pobreza Norte e Nordeste. Com base em\ninformações autorrelatadas, a sua prevalência nas capitais brasileiras está nitidamente associada à\nbaixa escolaridade em 13 de 16 capitais, incluindo-se entre elas todas as do Sul, do Sudeste e o\nDistrito Federal. Apenas em Belém, Natal e João Pessoa, o problema predominou em pessoas de\nescolaridade elevada. Ainda do ponto de vista social, é mais frequente em homens de classe social\nmais elevada e em mulheres de classes sociais mais baixas (Almeida Filho & Barreto,\nEpidemiologia e Saúde: fundamentos, métodos, aplicações, P 495 2012). O texto refere-se ao fator\nde risco cardiovascular, que é:","options":{"A":"a hipertensão.","B":"a obesidade.","C":"o diabetes.","D":"o colesterol sérico elevado.","E":"o tabagismo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-49462","number":"49462","sourceNumber":"49462","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente de 50 anos de idade, sexo feminino, diabética, em uso de hipoglicemiante\noral, portadora de apneia do sono grave, vinha em\nacompanhamento endocrinológico por dois\nanos, com perda ponderal de 10 kg no primeiro ano e recuperação do peso, apesar de medidas\ndietéticas e farmacológicas. Ao exame físico, paciente com peso de 84 kg e altura de 1,50 m.\n\nCintura de 112 cm, quadril de 106 cm. Em relação a esse caso, é CORRETO afirmar:","options":{"A":"A paciente não tem indicação cirúrgica, segundo os critérios da Sociedade Brasileira de Cirurgia\nBariátrica, para o tratamento da obesidade mórbida.","B":"Está indicado posicionamento de balão intragástrico e acompanhamento nutricional,\nconsiderando-se o melhor custo-benefício.","C":"A paciente deve ser encaminhada para tratamento cirúrgico, seguindo-se os critérios da\nSociedade Brasileira de Cirurgia Bariátrica.","D":"A relação cintura/quadril indica formalmente a necessidade de uma cirurgia tipo banda gástrica.","E":"A presença de apneia do sono é contraindicação absoluta ao tratamento cirúrgico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-35009","number":"35009","sourceNumber":"35009","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, 18 anos de idade, sexo feminino, dá entrada no hospital inconsciente, com\nantecedentes de ser diabética desde a infância. Exibia sinais de desidratação, pele fria, respiração\nruidosa. Os dados vitais mostravam PA: 90 x 50 mmHg, FC: 108 fino, mas regular. Palpa-se pulso\ncarotídeo e radial. FR: 34 inc/min, regulares, superficial. Temperatura axilar: 37,4°C. Realizada\nglicemia capilar e o valor encontrado foi de 900 mg%. Durante o tratamento inicial, a paciente\napresentou vários episódios de taquicardia ventricular não sustentada, evoluindo posteriormente\ncom anisocoria e hemiplegia direita. Esse quadro clínico sugere que:","options":{"A":"essa paciente tem cetoacidose diabética e deve ter recebido imediatamente hidratação com\n1000 ml a 2000 ml de solução salina 0,9% (100\nml/kg a 200 ml/kg nas 12 horas iniciais do\ntratamento), o que levou a edema cerebral e coma. As arritmias ventriculares ocorreram,\nprovavelmente, por hipoxia, desidratação e acidose.","B":"essa paciente tem coma hiperosmolar não cetótico, devendo ter recebido solução de Ringer\nlactato (100 ml/kg/12h a 200 ml/kg/12h). As\narritmias estão relacionadas, provavelmente, a infarto\nagudo do miocárdio e a hipóxia tecidual, uma vez que ela deve ter broncoaspirado, desenvolvendo,\nem seguida, isquemia cerebral.","C":"essa paciente tem coma hiperosmolar não cetótico. As complicações cardiovasculares e\nneurológicas, provavelmente, estão relacionadas ao uso de solução salina 0,45% em grande\nvolume e edema cerebral, seguido de broncoaspiração de conteúdo gástrico.","D":"complicações tromboembólicas em vasos de grande calibre podem ocorrer em pacientes com\nsíndrome hiperglicêmica hiperosmolar, levando a situações clínicas, como AVC isquêmico. Esses\nfenômenos tromboembólicos constituem uma causa importante de morte nessas síndromes.\nArritmias potencialmente fatais podem estar relacionadas tanto à hipercalemia quanto à\nhipocalemia, dependendo do estado volêmico da paciente e da fase de tratamento.","E":"essa paciente tem cetoacidose diabética e deve ter entrado em coma pela hipernatremia que\ndesenvolveu associada à desidratação. As arritmias estão relacionadas à hipóxia, à acidose e à\nhipofosfatemia não corrigidas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-34992","number":"34992","sourceNumber":"34992","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, sexo masculino, 53 anos de idade, pesando 65 quilos, residente em Salvador,\nengenheiro, etilista social, diabético há 12 anos, é atendido em unidade básica de saúde. Relata\ndificuldade em manter ereções penianas, perda de peso, insônia e que faz uso regular de\nhipoglicemiante oral. Última glicemia de jejum: 180 mg/dl. De acordo com esses dados, a primeira\nconduta a ser assumida, visando ao controle da glicemia, é:","options":{"A":"repetir a glicemia de jejum e solicitar hemoglobina glicosilada.","B":"solicitar hemoglobina glicosilada e avaliar a dose do hipoglicemiante oral em uso, a necessidade\nde adequar dieta e introduzir o uso de insulina.","C":"encaminhar o paciente à nutricionista e ao urologista para tratar a perda de peso e a possível\ndisfunção erétil.","D":"verificar os sinais vitais, avaliar e ajustar a dieta e a dose do hipoglicemiante oral, e\ninvestigar a\ncausa da insônia.","E":"orientar a necessidade de mudanças no estilo de vida e a importância de realizar atividades\nfísicas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27460","number":"27460","sourceNumber":"27460","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, 24 anos de idade, peso: 88 kg, altura: 1,76 m, circunferência abdominal: 101\ncm, TA: 135 X 85 mmHg, vem apresentando\nfadiga acentuada e náuseas matinais. Antecedentes:\nhistória familiar de Diabetes mellitus. Realizou exames que revelaram glicemia de jejum: 112 mg/dl,\nglicemia pós-prandial de 2 horas 220 mg/dl, hemoglobina glicada (HbA 1C): 8%. Peptídeo C em\njejum: 5 mg/ml (VN > 1,5 mg/ml). O cálculo do índice de HOMA-IR (modelo de avaliação da\nhomestase da glicose -\"homeostatic model of assessment\") foi de 5,6 (VN para o IMC do paciente:\n0,4 a 4,3). Esse paciente pode ser classificado como portador de:","options":{"A":"Diabetes Mellitus tipo II com insulinopenia.","B":"tolerância diminuída à glicose, sem diabetes.","C":"Diabetes Mellitus tipo I de início tardio.","D":"Diabetes Mellitus tipo II do jovem.","E":"Diabetes Mellitus tipo I, em fase inicial."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27463","number":"27463","sourceNumber":"27463","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, 24 anos de idade, peso: 88 kg, altura: 1,76 m, circunferência abdominal: 101\ncm, PA: 135 X 85 mmHg, vem apresentando\nfadiga acentuada e náuseas matinais. Antecedentes:\nhistória familiar de Diabetes mellitus. Realizou exames que revelaram glicemia de jejum: 112 mg/dl,\nglicemia pós-prandial de 2 horas 220 mg/dl, hemoglobina glicada (HbA1c): 8%. Peptídeo C em\njejum: 5 mg/ml (VN > 1,5 mg/ml). O cálculo do índice de HOMA-IR (modelo de avaliação da\nhomeostase da glicose - \"homeostatic model of assessment\") foi de 5,6 (VN para o IMC do\npaciente: 0,4 a 4,3). Para avaliação de autoimunidade como determinante do quadro desse\npaciente, o melhor exame é:","options":{"A":"dosagem de FAN.","B":"cálculo do HOMA-IR.","C":"dosagem de anticorpo anti-GAD.","D":"dosagem do peptídeo C.","E":"dosagem de anticorpo antigliadina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27466","number":"27466","sourceNumber":"27466","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, 24 anos de idade, peso: 88 kg, altura: 1,76 m, circunferência abdominal: 101\ncm, TA: 135 X 85 mmHg, vem apresentando\nfadiga acentuada e náuseas matinais. Antecedentes:\nhistória familiar de Diabetes mellitus. Realizou exames, que revelaram glicemia de jejum: 112 mg/dl,\nglicemia pós-prandial de 2 horas 220 mg/dl, hemoglobina glicada (HbA 1C): 8%. Peptídeo C em\njejum: 5 mg/ml (VN > 1,5 mg/ml). O cálculo do índice de HOMA-IR (modelo de avaliação da\nhomeostase da glicose - \"homeostatic model of assessment\") foi de 5,6 (VN para o IMC do\npaciente: 0,4 a 4,3). No tratamento farmacológico desse paciente, a medida mais eficaz e com\nmelhor custo-benefício é o uso de:","options":{"A":"insulina.","B":"metformina.","C":"glibenclamída.","D":"acarbose.","E":"rosiglitazona."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27470","number":"27470","sourceNumber":"27470","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, 24 anos de idade, peso: 88 kg, altura: 1,76 m, circunferência abdominal: 101\ncm, TA: 135 X 85 mmHg, vem apresentando\nfadiga acentuada e náuseas matinais. Antecedentes:\nhistória familiar de Diabetes mellitus. Realizou exames, que revelaram glicemia de jejum: 112 mg/dl,\nglicemia pós-prandial de 2 horas 220 mg/dl, hemoglobina glicada (HbA 1C): 8%. Peptídeo C em\njejum: 5 mg/ml (VN > 1,5 mg/ml). O cálculo do índice de HOMA-IR (modelo de avaliação da\nhomeostase da glicose - \"homeostatic model of assessment\") foi de 5,6 (VN para o IMC do\npaciente: 0,4 a 4,3). Entre os riscos tardios determinados pela condição desse paciente, não se\nincluirá:","options":{"A":"osteoartrose.","B":"demência senil.","C":"gota.","D":"osteoporose.","E":"doença apneica do sono."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27505","number":"27505","sourceNumber":"27505","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Na profilaxia específica do pé diabético, o parâmetro mais efetivo a ser monitorizado é:","options":{"A":"troficidade de unhas e fâneros.","B":"presença de edema em MMII.","C":"temperatura das extremidades.","D":"fluxo arterial de MMII com Doppler.","E":"sensibilidade proprioceptiva."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-11137","number":"11137","sourceNumber":"11137","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"À medida que não tem respaldo científico para evitar o desenvolvimento de diabetes\ntipo II em paciente com síndrome metabólica é:","options":{"A":"suspensão do tabagismo.","B":"prática moderada de atividade física.","C":"perda de peso.","D":"redução do consumo de cafeína.","E":"uso de metformina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-11207","number":"11207","sourceNumber":"11207","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O índice de massa corpórea, em Kg/m², de um adulto não atleta, considerado\nadequado pelos critérios da OMS, varia entre:","options":{"A":"20,0 e 27,0.","B":"18,5 e 24,9.","C":"15,5 e 26,9.","D":"15,0 e 26,0.","E":"14,0 e 27,0."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-11201","number":"11201","sourceNumber":"11201","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Criança, 4 anos de idade, é internada com quadro de náusea, vômito e dor abdominal.\nApresenta-se torporosa, emagrecida, febril, TAX: 38°C, com sinais de desidratação, apesar da\ndiurese abundante, enchimento capilar: 6 seg, F.R.: 40 irpm, PA: 80x40 mmHg, F.C.: 120/bpm. Os\nexames laboratoriais iniciais revelaram glicemia: 500 mg/dl, K: 4,7, Na: 126, PCO2: 16 mmHg, PO2:\n75 mmHg, SatO3: 95%, gasometria arterial Ph: 7,15, HCO3: 6 mEq/l. Nesse caso, pode-se afirmar\nque se trata, provavelmente, de","options":{"A":"cetoacidose diabética","B":"diarreia aguda, por rotavírus","C":"choque hipovolêmico","D":"septicemia","E":"intoxicação alimentar"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-281900","number":"281900","sourceNumber":"281900","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Pesquisa Nacional de Saúde realizada pelo Instituto Brasileiro de Geografia e\nEstatística (IBGE) mostrou prevalência de\ndiabetes melito de 19,9% nos indivíduos na faixa etária\nde 65 a 74 anos de idade. Está correto o item:","options":{"A":"No idoso diabético há redução da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","B":"No idoso diabético há aumento da mortalidade e aumento da capacidade funcional com\nconsequente aumento do risco de institucionalização.","C":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","D":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente menor risco de institucionalização."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-281904","number":"281904","sourceNumber":"281904","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É fundamental, além do rastreamento para complicações, uma avaliação\nmultidimensional do indivíduo idoso diabético. Sendo correto o item:","options":{"A":"Pelo benefício do diagnóstico e do tratamento precoce na prevenção de complicações.","B":"Pelo benefício do diagnóstico e do tratamento tardio na prevenção de complicações.","C":"Pelo benefício do diagnóstico e não do tratamento precoce na prevenção de complicações.","D":"Pelo benefício do diagnóstico e do tratamento precoce na manutenção de complicações."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249975","number":"249975","sourceNumber":"249975","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considerando a avaliação da neuropatia autonômica cardiovascular NAC por diabetes,\npodemos concordar que:","options":{"A":"Apresentam achados que estão relacionados com baixa frequência de hipertrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC.","B":"Apresentam achados que estão relacionados com alta frequência de hipotrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC.","C":"Apresentam achados que estão relacionados com alta frequência de hipertrofia ventricular direita\napenas, e eventos cardiovasculares sérios, fatais e não fatais, em pacientes diabéticos com NAC.","D":"Apresentam achados que estão relacionados com alta frequência de hipertrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249978","number":"249978","sourceNumber":"249978","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Podemos considerar a complicação da retinopatia como comum no paciente com\ndiabetes de longa evolução e mais grave\nnaqueles com mau controle da doença. Podemos assim\naceitar que:","options":{"A":"O rastreio sistemático e precoce dessa complicação não pode evitar a evolução para a cegueira\ndiabética, que é irreversível, devendo para isso haver disponibilidade, na rede pública e privada de\nsaúde, do acesso ao endocrinologista, ao oftalmologista bem como aos procedimentos mais\ncomplexos.","B":"O rastreio sistemático e precoce dessa complicação pode evitar a evolução para a cegueira\ndiabética, que é reversível, devendo para\nisso haver disponibilidade, na rede pública e privada de\nsaúde, do acesso ao endocrinologista, ao oftalmologista bem como aos procedimentos mais\ncomplexos.","C":"O rastreio sistemático e precoce dessa complicação pode evitar a evolução para a cegueira\ndiabética, que é irreversível, devendo para\nisso haver disponibilidade, na rede privada de saúde, do\nacesso ao endocrinologista, em como aos procedimentos mais simples.","D":"O rastreio sistemático e precoce dessa complicação pode evitar a evolução para a cegueira\ndiabética, que é irreversível, devendo para\nisso haver disponibilidade, na rede pública e privada de\nsaúde, do acesso ao endocrinologista, ao oftalmologista bem como aos procedimentos mais\ncomplexos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-250000","number":"250000","sourceNumber":"250000","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Deve-se evitar a gastrectomia vertical no segmento de cirurgia da obesidade nos\nseguintes casos:","options":{"A":"Doença de refluxo gastro-esofágico e esofagite erosiva.","B":"Pacientes com índice de massa corpórea > 40.","C":"Pacientes hipertensos em uso de bloqueador de canal de cálcio.","D":"Não há contraindicações para gastrectomia vertical."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-249735","number":"249735","sourceNumber":"249735","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A nefropatia diabética pode ser diagnosticada através da obtenção de exames\nalterados em duas de três avaliações realizadas em intervalos de três a seis meses.\n\npode ser considerado um valor alterado. A alternativa que preenche,\nCORRETAMENTE, a lacuna do trecho acima é:","options":{"A":"Ureia sérica de 60 mg/dl.","B":"Creatinina sérica de 1,7 mg/dl.","C":"Microalbuminúria de 24h ? 14 mg/24h.","D":"Concentração de albumina de 10 mg/dl em amostra isolada de urina.","E":"Índice albumina-creatinina ? 30 mg/g obtido em amostra isolada de urina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215601","number":"215601","sourceNumber":"215601","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A monitorização de glicose em sistema flash (Flash Glucose Monitoring ? FGM):\n\ntrata-se de um sensor de glicose que pretende substituir as medidas de glicemia capilar, com uma\ntecnologia que utiliza glicose oxidase e complexos de ósmio para evitar interferência de oxigênio;\npor isso, não requer calibração por glicemia capilar. Somente se mostra INCORRETO que:","options":{"A":"Nele, o usuário sabe o valor e a tendência de glicose apenas passando o leitor sobre o sensor, o\nque pode ser feito múltiplas vezes ao dia,\ncom atualizações a cada minuto.","B":"Suas principais limitações são o lag time, em torno de 5 minutos, e as discrepâncias que podem\nocorrer entre os valores de glicose\nintersticial nos momentos de hipoglicemia e de queda ou\naumento abrupto da glicose intersticial, de acordo com as setas de tendência.","C":"Nessas situações específicas, não se recomenda medir a glicemia capilar, caso se trate de um\nmomento de tomada de decisão pelo paciente.","D":"Alguns usuários relatam falta de acurácia do sensor nas primeiras horas de uso, o que não\ncostuma persistir nos dias subsequentes."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215610","number":"215610","sourceNumber":"215610","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Marque, apenas, a CORRETA sobre as indicações para o uso de monitorização\ncontínua de glicose Diabetes mellitus tipo 1.","options":{"A":"Recomenda-se CGM para todos os pacientes adultos com DM2, especialmente nos casos de\nhistória de hipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção\ndas hiperglicemias.","B":"Recomenda-se CGM para pacientes adultos com DM1, especialmente nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção das\nhiperglicemias.","C":"Recomenda-se CGM para pacientes adultos com DM1, exceto nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção das\nhiperglicemias.","D":"Recomenda-se CGM para pacientes adultos com DM1, especialmente nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, mas não para auxiliar na correção das\nhiperglicemias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-215616","number":"215616","sourceNumber":"215616","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A monitorização contínua de glicose (Continuous Glucose Monitoring ? CGM) possibilita\nmedir a concentração de glicose no líquido\nintersticial, seu sensor é implantado de maneira quase\nsempre indolor, por meio de um aplicador específico. O filamento do sensor tem espessura capilar\ne contém glicose oxidase. A glicose difunde-se por uma membrana para alcançar a camada com a\nenzima, que converte a concentração de glicose em um sinal eletrônico diretamente proporcional a\nela. Marque a opção INCORRETA.","options":{"A":"Além do valor absoluto de glicose intersticial, o indivíduo que realiza CGM observa setas de\ntendência, que indicam se a glicose está subindo, apenas.","B":"A seta de estabilidade denota alteração da glicose intersticial em velocidade inferior a 1\nmg/dl/min.","C":"As setas de subida ou descida lenta indicam alteração da glicose em velocidade entre 1 e 2\nmg/dl/min.","D":"As setas de subida ou descida rápida, finalmente, indicam alteração da glicose em velocidade\nsuperior a 2 mg/dl/min."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-218115","number":"218115","sourceNumber":"218115","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"João, 48 anos, vai à consulta, levando exames laboratoriais (glicemia de jejum 150\nmg/dl) realizados, porque \"sua mãe tem\ndiabetes\". Nega comorbidades, é sedentário, nega\ntabagismo, tem alimentação rica em carboidratos de alto índice glicêmico, diz não gostar muito de\nfrutas e verduras. Ao exame, IMC de 27, circunferência abdominal 93 cm. Considerando a\nabordagem inicial mais adequada nesse caso clínico, é CORRETO afirmar que:","options":{"A":"Como João é classificado como baixo risco, deve-se repetir o rastreamento em 3 a 5 anos\ndepois.","B":"Por João ser classificado como alto risco, está indicado o encaminhamento para\nendocrinologista.","C":"Se deve ofertar rastreamento para diabetes já que ele tem alto risco para o desenvolvimento\ndeste agravo.","D":"Um antidiabético oral, sulfonílureia, metformina, 850 mg deve ser prescrito, para tratamento da\npré-diabetes.","E":"João deve ser orientado para que sejam feitas intervenções para mudanças do estilo de vida,\nnão sendo necessários testes laboratoriais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-218125","number":"218125","sourceNumber":"218125","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"João, 48 anos, vai à consulta, levando exames laboratoriais (glicemia de jejum 150\nmg/dl) realizados, porque \"sua mãe tem diabetes\".\nNega comorbidades, é sedentário, nega\ntabagismo, tem alimentação rica em carboidratos de alto índice glicêmico, diz não gostar muito de\nfrutas e verduras. Ao exame, IMC de 27, circunferência abdominal 93 cm. João retorna à consulta\nna Unidade de Saúde da Família para acompanhamento do seu tratamento para diabetes. Hoje,\ncom 52 anos, está em uso de 14 unidades de insulina NPH à noite, além de metformina 3 vezes ao\ndia. Algumas das complicações às quais este paciente com diabetes pode desenvolver estão\ndescritas nas alternativas abaixo, assinale a CORRETA.","options":{"A":"O rastreamento da retinopatia e microalbuminúria devem ser realizados após 10 anos de\ndiagnóstico de DM.","B":"A avaliação da sensibilidade tátil dos pés é realizada com monofilamento de 50 g em um ponto\nde cada pé.","C":"As complicações agudas, que podem ocorrer com João, são: hipoglicemia, cetoacidose e\nretinopatia.","D":"Um orientação aconselhada na consulta com João deve ser o reconhecimento dos sintomas de\nhipoglicemia.","E":"Caso João chegasse à unidade com tontura, sudorese e tremor, dever-se-ia suspeitar de\nhiperglicemia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-181194","number":"181194","sourceNumber":"181194","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O termo MODY, são formas associadas a defeitos genéticos na função das células,\nesse termo sendo acrônimo de maturity-onset\ndiabetes of the Young, apresenta diversas\ncaracterísticas, somente sendo completamente adequada a alternativa:","options":{"A":"Herança autossômica não dominante.","B":"Idade precoce de aparecimento (em geral antes dos 15 anos de idade).","C":"Ocorrem graus variáveis de disfunção da célula beta.","D":"Estima-se que represente 10% de todos os casos de diabetes mellitus."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-181197","number":"181197","sourceNumber":"181197","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro do acometimento de faixa etárias jovens pelo Diabetes e Obesidade, bem como\npor doenças metabólicas, somente não podemos\nconsiderar verdadeiro que:","options":{"A":"Crianças e os adolescentes não estão sendo vítimas da epidemia de obesidade observada\natualmente.","B":"Ocorre aumento do risco de síndrome metabólica persistente na idade adulta.","C":"As complicações futuras dessa situação podem ser catastróficas caso não sejam instituídas\nmedidas de intervenção preventiva.","D":"É importante e necessário identificar aqueles indivíduos com maior risco de desenvolver\ncomplicações decorrentes do excesso de peso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-162513","number":"162513","sourceNumber":"162513","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dona Maria chega a Unidade de Saúde da Família para sua consulta do HIPERDIA, um\npouco sudoreica e quando a técnica de\nenfermagem faz a triagem sua glicemia capilar é de\n60mg/dL. Sobre o quadro da paciente, é correto afirmar que","options":{"A":"o paciente diabético não deve ser incentivado a ter consigo fonte de carboidrato da absorção\nrápida para consumo imediato, como mel, a fim\nde não agravar o quadro.","B":"a queda da glicemia, geralmente, leva à sintomas como tontura, fraqueza, dor de cabeça,\nconfusão, sudorese, taquicardia, apreensão e tremor.","C":"a hipoglicemia é a diminuição dos níveis glicêmicos - com ou sem sintomas - para valores\nabaixo de 80 mg/dL.","D":"os casos mais graves de hipoglicemia, geralmente, ocorrem à tarde, devido à deficiência de\ninsulina.","E":"a maioria dos casos, como de Dona Maria, são graves e requerem tratamento hospitalar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157605","number":"157605","sourceNumber":"157605","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Você foi questionado por seu paciente se ele estava adequadamente controlado em\ntermos de glicemia porque, apesar de a\nglicemia dele estar adequada, outro exame que você havia\nsolicitado indicava mal controle. Isso é ADEQUADAMENTE explicado por uma das seguintes\nalternativas. Assinale-a.","options":{"A":"Os testes de HbA1c revelam a glicemia mais elevada pregressa dos últimos 4 meses.","B":"Os testes de glicemia refletem o nível glicêmico no momento exato em que se alimentou por\núltimo.","C":"Os testes de HbA1c apontam o ?saldo médio? de glicose.","D":"Os valores de correspondência entre os níveis de HbA1c e os respectivos níveis médios de\nglicemia nos últimos 2 meses."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157585","number":"157585","sourceNumber":"157585","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Durante sua última tarde de atendimento na UBS, onde você faz estágio, foram\natendidos diversos pacientes diabéticos do tipo\n2, que, por este motivo, foi escolhido como tema\npara o fechamento do dia de trabalho, estando presentes estudantes e residentes do segundo ano.\nDentro dos conceitos discutidos no dia, você discordou de um dos tópicos por considerá-lo\nERRADO, estando este contido em uma das opções a seguir. Assinale-o.","options":{"A":"Define-se resistência à insulina (RI) como uma perturbação das vias de sinalização mediadas\npela insulina em que as concentrações normais\ndo hormônio produzem uma resposta biológica\nsubnormal.","B":"A resistência às ações hormonais é um fenômeno relativamente comum em endocrinologia.","C":"Um aumento da função beta celular pode compensar a RI, resultando em tolerância normal à\nglicose.","D":"Em resposta à elevação da glicemia, a secreção de insulina aumenta estimulando a captação de\nglicose, a síntese de glicogênio e o aumento da glicogenólise e da gliconeogênese."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157741","number":"157741","sourceNumber":"157741","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Diversos fatores podem contribuir para que o Diabetes Mellitus (DM) seja um fator de\nrisco para o desenvolvimento de infecções. Dentre esses, podemos destacar o seguinte.\n\nAssinale-o.","options":{"A":"Resposta imune celular eficiente e acelerada aos agentes nocivos.","B":"Alteração dos sistemas antioxidantes e maior produção de interleucinas (IL-2).","C":"Aumento da resposta vascular a mediadores inflamatórios, como histamina e bradicinina.","D":"Redução da degranulação dos mastócitos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157746","number":"157746","sourceNumber":"157746","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentre os diversos fatores microbiológicos que podem contribuir para que o Diabetes\nMellitus (DM) seja um fator de risco para o desenvolvimento de infecções, sobre a hiperglicemia\ncrônica, podemos considerar que:","options":{"A":"Muitas vezes, apresenta maior gravidade e mortalidade.","B":"As infecções que acometem pacientes com DM têm apresentação clínica completamente\ndiferenciada à da população geral.","C":"Alguns quadros infecciosos pouco usuais são muito mais raros ainda em pacientes com DM do\nque na população geral, como a otite\nexterna maligna.","D":"A manutenção de um controle glicêmico adequado não costuma reduzir o risco, sem efeito em\ntermos de profilaxia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157637","number":"157637","sourceNumber":"157637","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentro das complicações infecciosas relacionadas ao Diabetes Mellitus (DM), as\ninfecções urinárias e as bacteriúrias\nassintomáticas apresentam grande importância epidemiológica\ne clínica. Desse modo, assinale a opção considerada INADEQUADA sobre esse caso.","options":{"A":"O risco de desenvolver infecção urinária é aproximadamente cinco vezes maior em pacientes\ncom DM que na população geral.","B":"Dentre os motivos para que isso ocorra, a disfunção vesical associada à neuropatia autonômica,\nmais frequente em pacientes com longa duração do\nDM, pode contribuir para tal condição.","C":"Desenvolvimento de estase urinária.","D":"A presença de glicosúria possivelmente contribui para essa associação."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157639","number":"157639","sourceNumber":"157639","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O diagnóstico e a avaliação de risco e o tratamento de quadros infecciosos de vias\nrespiratórias em DM deverão seguir diretrizes publicadas para a população geral. Assim,\natualmente, para tratamento de pneumonia especificamente em pacientes com DM, podemos\nconsiderar apenas uma das alternativas a seguir. Assinale-a.","options":{"A":"Influenza e pneumonia são doenças infecciosas comuns, que apresentam moderadas taxas de\nmortalidade e de morbidade em pacientes com doenças crônicas, como o DM.","B":"Pacientes com DM necessitam mais raramente de hospitalização por influenza em comparação\ncom a população geral.","C":"Pacientes com DM apresentam tipos mais graves de pneumonia pneumocócica.","D":"Influenza e pneumonia são doenças infecciosas comuns que não podem ser minimizadas por\nvacinação adequada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157648","number":"157648","sourceNumber":"157648","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dentre as relações dos diabéticos com a Hepatite Viral, pacientes com hepatite C\napresentam a seguinte característica. Indique-a.","options":{"A":"Ocorre menor prevalência de DM tipo 2.","B":"Por outro lado, pacientes com DM têm pequena prevalência de sorologia positiva para hepatite\nC.","C":"Pacientes com DM apresentam risco de contrair o vírus da hepatite B duas vezes maior que na\npopulação geral.","D":"Por isso, atualmente, recomenda-se vacinação para essa doença viral em casos selecionados\nde pacientes com DM."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157679","number":"157679","sourceNumber":"157679","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A incidência concomitante de Tuberculose e Diabetes, coexistindo simultaneamente no\nmesmo indivíduo, ocorre frequentemente em nosso\nmeio, dentro da nossa realidade de país em\ndesenvolvimento. Das características clínicas e epidemiológicas descritas a seguir, aponte aquela\nque é considerada INADEQUADA.","options":{"A":"O risco de um paciente com DM desenvolver tuberculose é 2,44 a 8,33 vezes maior que da\npopulação geral.","B":"A frequência de tuberculose multirresistente não apresenta diferença nesse grupo.","C":"A radiografia de tórax pode apresentar alterações consideradas típicas (predominância nos\nlobos superiores) e também atípicas, acometendo predominantemente os lobos inferiores,\ngeralmente associadas a cavidades.","D":"A mortalidade e o risco de recidiva são superiores aos da população geral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157638","number":"157638","sourceNumber":"157638","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Apesar de conceitualmente mutável, a necessidade de controle glicêmico no diabético\nmellitus, em vigência de infecção sistêmica, apresenta diversos achados estatísticos muito\nimportantes de serem considerados, com EXCEÇÃO de um deles. Aponte-o.","options":{"A":"A hiperglicemia pode ser um sinal de desenvolvimento de infecção, o que é particularmente útil\nem pacientes idosos com DM.","B":"O aparecimento de hiperglicemia sem outras manifestações clínicas pode ser um sinal de alerta\npara o aparecimento de alguma infecção incipiente.","C":"Em pacientes com DM 1, recomenda-se checar cetonúria ou cetonemia no sangue capilar\nnaqueles com infecções que apresentem glicemia acima de 200 mg/dl.","D":"As infecções podem desencadear complicações agudas do diabetes, como a cetoacidose\ndiabética e o estado hiperosmolar, devido ao aumento da secreção de hormônios\ncontrarreguladores em resposta ao estresse."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157646","number":"157646","sourceNumber":"157646","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Foi solicitado que apresentasse sua opinião a respeito do seguinte quadro clínico.\nAnalise-o. Paciente masculino, 50 anos de idade,\ncom quadro de hérnia inguinal não complicada.\nFoi agendada cirurgia eletiva a fim de corrigir essa hérnia. Como o paciente é diabético, você foi\nacionado para o parecer clínico, no qual foi solicitado posicionamento sobre a diferenciação desse\nseu caso em relação aos de pacientes não diabéticos. Seu parecer foi muito elogiado, com\nEXCEÇÃO de um dos pareceres a seguir, que se mostrava INADEQUADO. Assinale-o.","options":{"A":"O DM está associado a um aumento do risco de infecções em feridas operatórias.","B":"Infecções perioperatórias no DM tem seu risco alterado, possivelmente por um efeito deletério da\nhiperglicemia na quimiotaxia, fagocitose e aderência de granulócitos.","C":"Infecções aumentam o risco de hiperglicemia em pacientes com DM.","D":"A melhora do controle glicêmico no período perioperatório não consegue reduzir o risco de\ninfecções em pacientes submetidos à cirurgia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-157658","number":"157658","sourceNumber":"157658","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em recente reunião administrativa do hospital, o chefe da farmácia solicitou que um\nmédico participasse da criação do sistema de vigilância e alerta da dispensa de medicações. A\nideia básica era a de criar tela de alerta quando ocorresse interação da medicação com o achado\nde diagnósticos mais frequentes como o do diabetes. Assim, foram criados diversos protocolos\nbaseados em dados epidemiológicos de interação, mas um deles foi posteriormente considerado\nINADEQUADO, conforme apresentado em uma das opções a seguir. Indique-o.","options":{"A":"Em pacientes com DM que apresentam infecções sistêmicas e que realizam tratamento com\nmedicações não insulínicas, pode ser necessária a insulinização temporária.","B":"Em pacientes com DM e tuberculose, o uso de rifampicina pode melhorar o controle glicêmico\nem pacientes que utilizam sulfonilureias.","C":"A metformina deve ser suspensa temporariamente em pacientes com infecções sistêmicas, pois\nsua manutenção nessas situações pode aumentar o risco de acidose láctica.","D":"As fluoroquinolonas, especialmente moxifloxacino, têm sido associadas tanto à hiper quanto à\nhipoglicemia, por vezes graves."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-134713","number":"134713","sourceNumber":"134713","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente com 18 anos de idade procurou o hospital com intenso mal-estar, desidratado,\ntorporoso. Seu dextro demonstra 560 mg/dl,\ncom a suspeita diagnóstica inicial de Cetoacidose\nDiabética. Solicitado, assim, Hemograma, bioquímica, gasometria e exame de urina. Então é\niniciada a hidratação, com início da insulina para após exames, justificado por:","options":{"A":"Risco de arritmias.","B":"Confirmação diagnóstica.","C":"Somente com glicemia se pode iniciar conduta.","D":"Não sabemos ainda a condição ácido básica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-139781","number":"139781","sourceNumber":"139781","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os últimos anos cresceram em importância clínica, o maior controle metabólico\ndo paciente acometido pelas mais variadas\nenfermidades, mas que complicam com distúrbios\nde controle glicêmico. Podendo essas ser secundárias ou não a situação grave atual. Independente\ndessas, ocorre risco também de o tratamento complicar com hipoglicemia, que podemos\ncaracterizar com os seguintes achados de maneira geral. Assinale-os.","options":{"A":"Agitação, valores abaixo de 40 e sudorese.","B":"Quadro neurológico compatível, achado de valores baixos de glicose e reversão do quadro com\ninfusão de glicose.","C":"Coma, valores abaixo de 70 e sudorese.","D":"Perda motora, valores abaixo de 70 e anisocoria."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-139784","number":"139784","sourceNumber":"139784","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Jovem, 14 anos de idade, dá entrada no hospital bastante dispneica e desidratada.\nSeus exames mostram glicemia de 520 mg/dl,\nacidose grave, K de 3,1 mEq, cetonúria e glicosúria.\nFrente a esse caso, indique a alternativa que NÃO está indicada.","options":{"A":"Bicarbonato de Sódio.","B":"Insulina.","C":"Hidratação.","D":"Uso de solução fisiológica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-111875","number":"111875","sourceNumber":"111875","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente de 10 anos, sexo feminino, chegou ao pronto-socorro com história de vômitos\ne prostração. A mãe referia que sua filha estava\nhá 2 dias apática, com dor abdominal, respirando\ncom dificuldade e fazendo xixi com frequência. Nega febre e qualquer outra sintomatologia; nega\npatologias pregressas. Ao exame, encontrava-se desidratada, com desconforto respiratório\nimportante (respiração de Kussmaul), com dor difusa à palpação de abdome, RHA +; ausculta\ncardíaca e pulmonar sem alterações; presença de leucorreia importante à inspeção da genitália. O\nprimeiro médico que atendeu a criança solicitou um hemograma que mostra leucocitose com desvio\nà esquerda. Qual é a PRINCIPAL hipótese diagnóstica do paciente do caso em questão?","options":{"A":"Pneumonia associada à insuficiência respiratória aguda.","B":"Choque séptico devido à infecção do trato urinário.","C":"Apendicite.","D":"Cetoacidose diabética."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-350853","number":"350853","sourceNumber":"350853","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 56 anos, tabagista, hipertenso há 5 anos, descobriu ter Diabetes Mellitus\ntipo 2 (DM2) há 1 ano, em exames de\nrotina. Recentemente, iniciou dor precordial em aperto, aos\ngrandes esforços, com irradiação para o pescoço, intensidade moderada, que alivia com o repouso.\nFaz uso de losartana 100 mg/dia, AAS 100 mg/dia e há 3 meses ajustou posologia da metformina\npara 850 mg 3 vezes ao dia. Ganhou 3 kg nos últimos 6 meses e reconhece exagerar nos\ncarboidratos. Ao exame físico: bom estado geral, eupneico, acantose nigricans e acrocórdons\ncervicais, pressão arterial 110/70 mmHg, frequência cardíaca 68 bpm, IMC 29 kg/m², circunferência\nabdominal 98 cm, ausculta cardiopulmonar fisiológica, sem edemas. Os exames laboratoriais\nevidenciaram hemoglobina 13,6 g/dL, creatinina 0,9 mg/dL, glicemia de jejum 166 mg/dL, HbA1c\n8,0%. Para tratamento do DM2 desse paciente, qual a conduta mais adequada?","options":{"A":"Manter metformina e iniciar liraglutida.","B":"Reduzir a dose da metformina e iniciar pioglitazona.","C":"Prescrever uma combinação de metformina com gliptina.","D":"Manter metformina e associar uma sulfoniureia em dose baixa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-350891","number":"350891","sourceNumber":"350891","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 18 anos é admitido na emergência com náuseas, vômitos e sonolência.\nExame físico não evidencia hipoperfusão\ntecidual. Glicemia capilar 258mg/dL. Coletada gasometria\narterial: pH 7,2 Bicarbonato 10mEq/L PaCO? 30mmHg Na 142mEq/L Cloro 98mEq/L Lactato\n0,8mmol/L. Qual a principal hipótese diagnóstica?","options":{"A":"Sepse.","B":"Cetoacidose diabética.","C":"Síndrome de Fanconi.","D":"Gastroenterite aguda."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-321300","number":"321300","sourceNumber":"321300","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 24 anos, portador de Diabetes Mellitus tipo 1, desde os 11 anos, deu\nentrada no Pronto-Socorro com quadro de dor\nabdominal, náuseas e vômitos, há 10 horas, tendo\nevoluído com rebaixamento do nível de consciência. História de poliúria e polidipsia, há 5 dias. Ao\nexame físico: sonolento, desidratado (++/4+), emagrecido; Ausculta Cardíaca: RCR em 2T, BNF,\nsem sopros, Pressão Arterial: 90 / 60 mmHg, Frequência Cardíaca: 104 bpm; Ausculta Pulmonar:\nMVU, presença de crepitações finas em base direita, taquipneico, saturação de oxigênio: 90%;\nabdome flácido, indolor à palpação, sem visceromegalias. Exames laboratoriais: gasometria com\npH 7,1; hemograma: leucócitos 16.000/mm³ com desvio à esquerda; glicemia 352 mg/dl (VR 70 a\n99); potássio 3,0 mEq/L (VR 3,5 a 5,0); cetonúria fortemente positiva. Considerando a principal\nhipótese diagnóstica, além da antibioticoterapia, qual a conduta inicial adequada?","options":{"A":"Hidratação endovenosa e insulinoterapia.","B":"Insulinoterapia e reposição de bicarbonato.","C":"Hidratação endovenosa e reposição de potássio.","D":"Insulinoterapia, reposição de potássio e bicarbonato."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-292817","number":"292817","sourceNumber":"292817","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 18 anos é admitido na emergência com quadro de redução do nível de\nconsciência, náuseas, vômitos e dor abdominal difusa. Apresenta glicemia capilar de 300 mg/dL e\ngasometria com acidose metabólica. Com o objetivo de confirmar o diagnóstico da emergência\nclínica em questão, qual exame deveria ser solicitado?","options":{"A":"Hemoglobina glicada.","B":"Sumário de urina.","C":"Lactato sérico.","D":"Hemograma."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-292826","number":"292826","sourceNumber":"292826","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher, 24 anos, diagnóstico de diabetes mellitus tipo 1 aos 10 anos, em uso de\ninsulina e losartana 50 mg/dia, e\ndiagnóstico de lúpus eritematoso sistêmico aos 20 anos, em uso\nde hidroxicloroquina 400 mg/dia, prednisona 5 mg/dia, e vitamina D3 1.000 UI/dia, relata há 4\nmeses apresentar turvação visual, fadiga, dispneia aos médios esforços e ganho de peso. Ao\nexame: anasarca e PA 150 x 80 mmHg. Exames complementares: hemograma, PCR, TGO, TGP,\nTP: normais; VHS 28 mm/h (VR 20 mm na 1ª hora); Cr 1.5 mg/dl (VR 1,2 mg/dl); Ur 60 mg/dl (VR\n15?45 mg/dl); albumina 3,0 mg/dl (VR 3,5?4 mg/dl); Hb glicada 6,6%; colesterol total 250 mg/dl (VR\n\n< 200 mg/dl), LDL 140 mg/dl (VR < 100 mg/dl); triglicerídeos 300 (VR < 150 mg/dl); SU: proteína 4+;\nproteinúria em 24h: 4 g/24h; fator antinúcleo reagente 1:160 padrão pontilhado fino denso.\n\nSorologias HIV, anti-HBsAg, anti-HCV e VDRL: negativas. Que alteração na investigação\ncomplementar confirmaria o diagnóstico mais provável?","options":{"A":"Dosagem sérica elevada de CH50, C3 e C4.","B":"Nódulos de Kimmelstiel-Wilson na biópsia renal.","C":"Depósitos imunes subendoteliais focais glomerulares na biópsia renal.","D":"Anticorpo anticitoplasma de neutrófilos reagente no padrão citoplasmático."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-292866","number":"292866","sourceNumber":"292866","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ainda na consulta de Edberto, foi verificada glicemia capilar em jejum de 158 mg/dl, e o\nmesmo questiona o significado clínico desse achado. Corretamente, você responde que a glicemia\ncapilar ainda não está validada para diagnóstico, mas a glicemia capilar alterada sugere alteração\nno exame de glicemia sérica plasmática. Vendo que não constam exames prévios no prontuário de\nEdberto, você, então, solicita exames laboratoriais para avaliação metabólica e agenda o retorno.\nApós um mês, Edberto retorna com os exames complementares, que trazem glicemia de jejum de\n160 mg/dl, HbA1c = 8,0%, Colesterol Total = 270 mg/dl, HDL = 30 mg/dl, Triglicerídeos séricos =\n300 mg/dl. Não havia alterações em eletrólitos, nem alterações sugestivas de nefropatia diabética\nou doença coronariana isquêmica. Assinale a alternativa que contempla a opção terapêutica\nadequada quanto à hiperglicemia.","options":{"A":"Orientar mudanças de estilo de vida (MEVs) e retorno em seis meses com os mesmos exames\nlaboratoriais para nova avaliação.","B":"Introduzir Metformina associada a MEVs. A associação de um segundo antidiabético pode ser\nconsiderada e pactuada individualmente.","C":"Iniciar a Insulinoterapia plena para o controle glicêmico precoce de imediato. Depois, descalonar\npara terapia oral associada a MEVs.","D":"Iniciar terapia farmacológica em esquema de Insulinoterapia Basal Plus: (Insulinoterapia Basal +\nInsulinoterapia Prandial + Hipoglicemiantes orais)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-259759","number":"259759","sourceNumber":"259759","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente, sexo masculino, 53 anos, hipertenso e diabético há 10 anos, comparece em\nconsulta de rotina para mostrar exames. Queixa-se de perda de peso. Ao exame apresenta BEG,\ncorado, hidratado, eupneico, PA=120x80, 70 kg, AP fisiológica AC RCR 3T B4, Extremidades: ppp,\nedema de mmii+/4+ sem cacifo. Exames complementares: GJ=180mg/dl; HbA1c=8%,\ncreatinina=1,8, TFG=42ml/min. Medicação em uso: gliclazida MR 120 mg/d, metformina 2,5 g/d,\nenalapril 40 mg/d, furosemida 40 mg/d. Qual a conduta CORRETA em relação ao tratamento\nfarmacológico da diabetes?","options":{"A":"Iniciar insulina ?bed time? e reduzir metformina.","B":"Associar terceiro antidiabético oral e reduzir a gliclazida.","C":"Iniciar insulina ?bed time?, mantendo as outras medicações.","D":"Associar terceiro antidiabético oral, mantendo as outras medicações."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-234073","number":"234073","sourceNumber":"234073","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 24 anos procura unidade básica de saúde preocupada com o risco de\ndesenvolver diabetes (DM), uma vez que a mãe\nfoi diagnosticada recentemente com pré-diabetes.\nTrouxe exames de glicemia de jejum, hemoglobina glicada e teste de tolerância oral à glicose com\n75g com valores de 94 mg/dL, 5,5% e 136 mg/dL, respectivamente. Antecedentes: DM gestacional\nhá 2 anos; acompanhamento psiquiátrico por motivo desconhecido. Ao exame: Normotensa, IMC\n22,7 kg/m². O médico orienta quanto ao estilo de vida e decide rastrear para DM a cada 3 anos.\n\nEntretanto, recebe informação durante a consulta que o psiquiatra está cogitando iniciar uma\nmedicação. Qual das medicações abaixo, caso prescrita, terá a maior probabilidade de fazer com\nque o médico necessite modificar o rastreamento inicialmente proposto?","options":{"A":"Setralina.","B":"Topiramato.","C":"Olanzapina.","D":"Bupropiona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-199713","number":"199713","sourceNumber":"199713","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma mulher de 43 anos foi submetida a by-pass gástrico há 8 meses para tratamento\nde obesidade mórbida. Desde a cirurgia, a\npaciente vem realizando atividades físicas noturnas,\ncomo musculação e corridas matinais 4 vezes por semana e já perdeu 32 kg (peso inicial 90 kg).\nNão está tomando medicações. Há cerca de 3 semanas, ela tem notado episódios de náuseas, dor\nabdominal em cólicas, diarreia, palpitações, tonturas e sudorese profusa pós-alimentares,\nmotivando a necessidade de antecipação de uma consulta de retorno ambulatorial. Qual o\ndiagnóstico provável?","options":{"A":"Deficiência de ferro.","B":"Síndrome de dumping.","C":"Deficiência de tiamina.","D":"Desnutrição calórico-proteica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-199770","number":"199770","sourceNumber":"199770","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem, 62 anos, obeso e hipertenso, procurou assistência médica na UPA com queixa\nde cansaço, perda de peso, poliúria e\npolidipsia. Ao exame, IMC = 31 kg/m², desidratado +/4+, sem\noutros achados clínicos relevantes. Exames laboratoriais: glicemia = 258 mg/dl, creatinina = 1,7\nmg/dl; taxa de filtração glomerular estimada (CKD-EPI) = 42,3 ml/min/1,73 m² e A1C = 9,8%.\n\nSumário de urina: glicose+++ /cetonas negativo. LEGENDA: IMC: Índice de Massa Corpórea;\nCKD-EPI: Chronic Kidney Disease Epidemiology\nCollaboration; AIC: hemoglobina glicada. Qual o\nesquema terapêutico mais apropriado para este paciente?","options":{"A":"Gliclazida e insulina.","B":"Metformina e insulina.","C":"Gliclazida e sitagliptina.","D":"Sitagliptina e metformina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-172985","number":"172985","sourceNumber":"172985","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente feminina, 24 anos, moradora de rua, admitida com quadro relatado de\nnáuseas, vômitos e dor abdominal há 3 dias, com\npiora progressiva e obnubilação mental nas\núltimas 24 horas. Sem uso de drogas ou álcool. Comorbidades e uso de medicações são\ndesconhecidas. Ao exame físico: PA = 90 x 60 mmHg; FC = 120 bpm; FR = 32 irpm; sonolenta,\ndesidratada 3+/4+, presença de hálito cetônico. Exames laboratoriais: hemograma com leucocitose\nsem desvio; urina com cetonúria 3+/4+ e glicosúria 4+/4+; glicemia = 500 mg/dl; Na = 135 mg/dl\n(VR: 135-145 mg/dl); K = 5,5 mEq/L; pH = 7,16 HCO? = 12 mEq/L (VR: 22-26 mEq/L); pCO? = 28\n\nmmHg (VR: 35-45 mmHg); lactato = 2,5 mEq/L (VR: até 2 mEq/L); radiografia de tórax normal;\neletrocardiograma com taquicardia sinusal. LEGENDA: PA: Pressão Arterial; FC: Frequência\nCardíaca; bpm: batimentos por minuto; FR: Frequência Respiratória; irpm: incursões respiratórias\npor minuto; Na: sódio; K: potássio; HCO?: bicarbonato; VR: Valor de Referência. Considerando o\ndiagnóstico mais provável e sua fisiopatologia, qual a afirmativa CORRETA?","options":{"A":"O quadro é de acidose metabólica com ânion-gap elevado, causada primariamente pela perda\nde bicarbonato.","B":"Com o tratamento adequado, a hiperglicemia deve apresentar resolução posterior à correção da\ncetose.","C":"Níveis elevados de glucagon e catecolaminas, isoladamente, são capazes de produzir o quadro\nclinicolaboratorial.","D":"A cetose que ocorre se relaciona à lipólise, liberação de ácidos graxos livres e formação\nhepática de corpos cetônicos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-172961","number":"172961","sourceNumber":"172961","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino de 59 anos, com diagnóstico de diabetes há 10 anos, comparece a\nUBS para consulta de rotina, apresentando\núlcera superficial em pododáctilo, com eritema e celulite\nao redor (atingindo 1,0 cm da sua borda). Estado geral bom, afebril, normotenso, orientado e\ncomunicativo, com frequência cardíaca de 72 bpm. Negava internações anteriores para tratamento\nde infecções ou feridas no corpo ou uso recente de glicocorticoide ou antibióticos. Qual deve ser a\nterapêutica medicamentosa de primeira escolha?","options":{"A":"Amoxicilina-Clavulanato por 7 dias.","B":"Penicilina benzatina em dose única.","C":"Ciprofloxacino por 21 dias.","D":"Cefalexina por 15 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-150854","number":"150854","sourceNumber":"150854","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 48 anos, hipertenso e diabético tipo 1, comparece a serviço de\nemergência com queixa de náuseas, vômitos e dor abdominal que se iniciaram há 2 dias. Uma\nsemana antes do início dos sintomas, relatou quadro de febre baixa e diarreia aguda, que\napresentou melhora sem terapêutica específica ao longo dos dias. Por não se alimentar devido\nhiporexia, diminuiu a dose de suas medicações orais e da insulina. Ao exame físico: PA 102 x 72\nmmHg, P 118 bpm, FR 28 rpm. Apresenta-se em estado regular, com respirações profundas,\nabdome dolorido difusamente, com ruídos levemente diminuídos. Paciente é submetido à\noxigenioterapia e expansão volêmica. Bioquímica sérica evidencia: Glicemia 500 mg/dL, sódio 127\nmEq/L, potássio 3,0 mEq/L, cloro 99 mEq/L, creatinina sérica 1,5 mg/dL, ureia 72 mg/dL.\nGasometria arterial (em Venturi 40%): pH 7,16, pCO2 31 mmHg, Bic 10 mEq/L, pO2 236 mmHg,\nSO2 99,6%, sumário de urina positivo para cetonas 2+. Qual terapêutica endovenosa deve ser\ntomada a seguir?","options":{"A":"Infusão de insulina.","B":"Reposição de sódio.","C":"Reposição de potássio.","D":"Reposição de bicarbonato."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-127016","number":"127016","sourceNumber":"127016","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 56 anos, hipertenso, obeso, sedentário, recebeu diagnóstico recente de\ndiabetes mellitus. Seus exames na consulta\ninicial revelaram uma glicemia de jejum de 126 mg/dl;\nhemoglobina glicada de 8,0%; triglicerídeos de 250 mg/dl e HDL-colesterol de 30 mg/dl. Retornou\npara consulta de reavaliação referindo intolerância gastrointestinal à metformina. Além das medidas\nnão farmacológicas, a conduta medicamentosa mais adequada nesse momento é prescrever:","options":{"A":"Gliptina.","B":"Metiglinida.","C":"Sulfonilureia.","D":"Insulina NPH subcutânea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-102126","number":"102126","sourceNumber":"102126","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo masculino, 1,8 m de altura, peso de 123 kg, hipertenso e diabético,\ntendo tido falha na terapêutica clínica,\nestável do ponto de vista psiquiátrico e sem dependência de\nálcool e droga ilícita, procura ambulatório de cirurgia em busca de tratamento cirúrgico. Na\navaliação pré-operatória, qual das opções abaixo deve ser considerada uma CONTRAINDICAÇÃO\nabsoluta para esta opção terapêutica?","options":{"A":"Idade superior a 65 anos.","B":"Portador do vírus C da hepatite.","C":"A presença da Síndrome de Prader-Willi.","D":"Índice de massa corpórea acima de 60 Kg/m²."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-102123","number":"102123","sourceNumber":"102123","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem, 55 anos, procurou assistência médica com queixas de dor e parestesias,\nfraqueza e glossite. Referiu ter realizado\ncirurgia bariátrica há nove anos. Trazia como exame\ncomplementar: glicemia em jejum de 115 mg/dl. A causa mais provável da neuropatia periférica em\nquestão é:","options":{"A":"Diabetes mellitus.","B":"Deficiência de retinol.","C":"Deficiência de calciferol.","D":"Deficiência de cobalamina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-102137","number":"102137","sourceNumber":"102137","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 52 anos portadora de diabetes tipo 2, em uso de insulina NPH e de insulina\nregular, comparece para reavaliação. Ela traz\nhemoglobina glicada de 11% e glicemia de jejum 128\nmg/dl. Seu esquema de insulina é NPH 20u pela manhã e 08u à noite e três doses de 04u de\ninsulina regular, antes das principais refeições. Sua dieta é baseada em carboidratos processados,\nfrituras e carne vermelha. Não consome frutas nem verduras, não usa adoçante, nem nenhum tipo\nde suplemento alimentar e é sedentária. Qual das medidas deve ser adotada inicialmente?","options":{"A":"Associar metformina.","B":"Aumentar insulina NPH.","C":"Aumentar insulina regular.","D":"Proceder orientação dietética."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-102166","number":"102166","sourceNumber":"102166","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 64 anos, com história de dispneia progressiva e fadiga aos\nesforços há cerca de 5 anos. Negava\nortopneia ou dispneia paroxística noturna. Referia roncos.\nProcurou atendimento médico por conta de uma síncope após tentar subir um lance de escada. O\nexame físico demonstrava IMC: 41 kg/cm² e veia jugular túrgida a 45° com onda v do pulso\nvenoso proeminente. Apresentava ainda ictus cordis palpável no epigástrio, sopro holossistólico na\nborda esternal esquerda e edema de membros inferiores (+2/+4). Ausculta respiratória normal. A\ngasometria arterial revelava pH: 7,32; PaCO2: 60 mmHg; PaO2: 68 mmHg; HCO3: 30 mEq/L;\nSaO2: 93%. Radiografia de Tórax com abaulamento do tronco pulmonar sem outras alterações.\n\nDiante desse contexto, o diagnóstico mais provável para essa sequência de eventos é:","options":{"A":"Insuficiência Cardíaca Esquerda.","B":"Doença Pulmonar Obstrutiva Crônica.","C":"Síndrome Obesidade-Hipoventilação.","D":"Hipertensão Arterial Pulmonar Idiopática."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-81278","number":"81278","sourceNumber":"81278","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 65 anos, com diagnóstico de tumor de calda de pâncreas, deverá\nser submetido a uma pancreatectomia corpo\ncaudal. Comparece para consulta no ambulatório de\npré-anestesia. É obeso, hipertenso controlado com losartana 50 mg/dia, dislipidêmico. Está em\njejum e um teste rápido pela fita revela glicemia de 140 mg/dl. Qual exame complementar deve ser\nsolicitado no pré-operatório para melhor avaliação do controle glicêmico desse paciente?","options":{"A":"Glicosúria.","B":"Hemoglobina glicada.","C":"Glicemia pós-prandial.","D":"Teste de tolerância à glicose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-81301","number":"81301","sourceNumber":"81301","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 60 anos comparece para avaliação de diabetes. Ele recebeu o diagnóstico\nhá cerca de oito anos, quando iniciou uso de\nmetformina, 2.000 mg/dia, mas desde então não tem\nseguimento médico. Seu índice de massa corporal é 38 kg/m². Seus exames mostram glicemia de\njejum 312 mg/dl; hemoglobina glicosilada (HbA1c) 12%; sumário de urina normal e\nmicroalbuminúria de 100 mg/24h (ref.: < 30 mg/24h). Qual seria a ação farmacológica mais\ndesejável ao acrescentar um medicamento adicional, nesse caso, dentre as opções atuais?","options":{"A":"Aumentar a concentração sérica basal de insulina por via exógena.","B":"Estimular a produção de insulina e reduzir a produção de glucagon.","C":"Diminuir a resistência à insulina e reduzir a produção de glicose.","D":"Estimular a produção de insulina pelas células beta do pâncreas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-65768","number":"65768","sourceNumber":"65768","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, relata história de acantose nigricans e\noligomenorreia. Ao exame, apresenta\nhirsutismo sobre os lábios, mento e linha alba do abdome.\nPA: 120/80 mmHg em uso de anti-hipertensivo, circunferência abdominal de 87 cm, estatura: 1,56\nm, peso: 61 kg. Exames: glicemia de jejum: 99 mg/dl e triglicerídeos de 160 mg/dl, índice de\nsensibilidade à insulina (HOMA IR): 3,7 (valor normal: < 2,75). Qual a melhor interpretação do\nperfil\nmetabólico e a respectiva conduta terapêutica?","options":{"A":"A paciente tem evidência laboratorial e clínica de resistência aumentada à insulina e síndrome\nmetabólica, segundo a Federação Internacional de Diabetes. Apresenta risco alto de desenvolver\ndiabetes. Não está indicada intervenção farmacológica.","B":"A paciente tem evidência laboratorial e clínica de resistência aumentada à insulina e síndrome\nmetabólica, segundo a Federação Internacional de Diabetes. Apresenta risco alto de desenvolver\ndiabetes. A metformima é uma alternativa terapêutica.","C":"A paciente tem evidência laboratorial e clínica de resistência aumentada à insulina e não tem\nsíndrome metabólica, segundo a Federação Internacional de Diabetes. Apresenta risco baixo de\ndesenvolver diabetes. A metformima é uma alternativa terapêutica.","D":"A paciente não tem evidência laboratorial e clínica de resistência aumentada à insulina nem\nsíndrome metabólica, segundo a Federação\nInternacional de Diabetes. Faltam dados para avaliar o\nrisco de desenvolver diabetes. Não está indicada intervenção farmacológica.","E":"A paciente tem evidência laboratorial e clínica de resistência aumentada à insulina e não tem\nsíndrome metabólica, segundo a Federação Internacional de Diabetes. Apresenta risco baixo de\ndesenvolver diabetes. Não está indicada intervenção farmacológica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-51160","number":"51160","sourceNumber":"51160","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 46 anos comparece em consulta para avaliação e tratamento de obesidade.\nSua estatura é 1,65 m e seu peso é 112 kg.\nAvaliação laboratorial mostra glicemia de jejum de 178\nmg/dl e hemoglobina glicosilada de 12%. Qual o método mais seguro e eficiente para este paciente\nperder peso?","options":{"A":"Redução da ingestão calórica.","B":"Exercícios físicos aeróbicos.","C":"Medicações antiobesidade.","D":"Cirurgia bariátrica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-51230","number":"51230","sourceNumber":"51230","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 42 anos procurou seu Médico de Família e Comunidade (MFC) queixando-se\nde fadiga e poliúria. Ela é hipertensa e\ndislipidêmica (LDL 160 mg/dl, HDL 25 mg/dl e triglicérides\n300 mg/dl). Faz uso de anticoncepcional hormonal (estrogênio e progesterona) para tratamento de\nsíndrome de ovários policísticos. Ela é mãe de dois filhos, sendo que um deles, hoje com 4 anos,\nnasceu pesando 4.300 gramas. Ao exame, apresentou PA 140 x 90 mmHg, peso 68 kg, estatura\n1,50 m e cintura de 100 cm medida na altura da crista ilíaca. Qual alternativa contém fatores de\nrisco que levantam a suspeita de diabetes nessa paciente ?","options":{"A":"LDL \"maior que\" 130 mg/dl, hipertensão arterial e obesidade.","B":"Idade, hipertensão arterial e síndrome dos ovários policísticos.","C":"Síndrome de ovários policísticos, triglicerídeos \"maior que\" 250 mg/dl e HDL \"menor que\" 35\nmg/dl.","D":"Uso de anticoncepcionais, mãe de recém-nascido com mais de 4 Kg e LDL \"maior que\" 130\nmg/dl."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-45358","number":"45358","sourceNumber":"45358","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A obesidade ou sobrepeso pode ser definida pelo índice de Quetelet que é obtido por:","options":{"A":"divisão da altura pelo peso ao quadrado.","B":"divisão do peso pelo quadrado da altura.","C":"diferenças entre os perímetros abdominal e torácico.","D":"medida da adiposidade abdominal.","E":"média do peso mais dois desvios padrões dos indivíduos da mesma faixa etária e sexo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-45386","number":"45386","sourceNumber":"45386","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual das drogas abaixo está associada à hipoglicemia e ganho de peso em pacientes\ndiabéticos tipo 2?","options":{"A":"Repaglinida.","B":"Rosiglitazona.","C":"Metformina.","D":"Acarbose.","E":"Sitagliptina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37600","number":"37600","sourceNumber":"37600","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os antidiabéticos orais têm diversos mecanismos de ação, contraindicações e efeitos\ncolaterais. Marque a opção incorreta.","options":{"A":"As sulfaniureias aumentam a secreção de insulina, são contraindicadas na insuficiência renal e\nocasionam hipoglicemia e ganho ponderal.","B":"As biguanidas aumentam a produção hepática de glicose com grande ação sensibilizadora da\nação insulínica, são contraindicadas na gestação,\nnas insuficiências renal, hepática, cardíaca,\npulmonar e acidose grave. Ocasionam desconforto abdominal e diarreia.","C":"Os inibidores da alfaglicosidase ocasionam retardo da absorção de carboidratos, são\ncontraindicados na gestação. Ocasionam meteorismo, flatulência e diarreia.","D":"As glitazonas aumentam a sensibilidade à insulina em músculo, adipócito e hepatócito, são\ncontraindicadas na insuficiência cardíaca classes III e IV, na insuficiência hepática e na gravidez.\nOcasionam edema, anemia e ganho ponderal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37601","number":"37601","sourceNumber":"37601","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Algumas situações clínicas podem alterar os resultados reais do teste de hemoglobina\nglicada. Marque a opção incorreta.","options":{"A":"Anemia hemolítica ou estados hemorrágicos\naumentam os níveis de hemoglobina glicada.","B":"Aumento de triglicérides, bilirrubinas e ureia\naumentam os níveis de hemoglobina glicada.","C":"Presença de grandes quantidades de vitaminas C e E no sangue reduzem os níveis de\nhemoglobina glicada.","D":"Anemia por carência de ferro, vitamina B12 ou ácido fólico aumentam os níveis de hemoglobina\nglicada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37380","number":"37380","sourceNumber":"37380","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É critério diagnóstico de Diabetes Mellitus tipo 2 (DM2):","options":{"A":"Glicemia de jejum acima de 110 mg/dl, independente de sintomas.","B":"Sintomas clássicos de diabetes mais uma concentração aleatória de glicose sanguínea maior ou\nigual a 140 mg/dl.","C":"Sintomas clássicos de diabetes mais uma\n\nconcentração aleatória de glicose sanguínea maior ou igual a 126 mg/dl.","D":"Glicose plasmática após 2h maior que 140 mg/dl durante um teste oral de tolerância a 75 g de\nglicose.","E":"Glicose plasmática após 2h maior que 200 mg/dl durante um teste oral de tolerância a 75 g de\nglicose."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37012","number":"37012","sourceNumber":"37012","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 30 anos procura atendimento para check-up. Não tem queixas específicas.\nO exame físico mostra índice de massa corpórea\n(IMC) = 26 kg/m². É filho de diabético (tipo 2). Os\nexames laboratoriais estão normais. Qual das condutas abaixo é a mais indicada para prevenir\nDiabetes Mellitus nesse paciente?","options":{"A":"Iniciar metformina.","B":"Atividade física com perda de peso.","C":"Iniciar acarbose.","D":"Iniciar sibutramina para perda de peso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37039","number":"37039","sourceNumber":"37039","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual comorbidade está associada à obesidade na adolescência?","options":{"A":"Diabetes tipo 1.","B":"Ovários policísticos.","C":"Esclerose hepatoportal.","D":"Hipertrofia de adenoides."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-37410","number":"37410","sourceNumber":"37410","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A obesidade, atualmente, pode ser considerada uma doença de grande importância de\nsaúde pública. Considerando que na sua atuação\nprofissional você deverá lidar com pessoas\nobesas com frequência, qual das condições abaixo é mais relevante na indicação de\nencaminhamento de um paciente para tratamento cirúrgico:","options":{"A":"Pacientes com alterações psicológicas importantes a ponto de dificultar o tratamento clínico.","B":"Índice de massa corporal maior que 40.","C":"Doença cardiovascular isquêmica importante.","D":"Diabetes mellitus tipo I associado à obesidade (IMC maior que 30).","E":"Paciente pouco motivado com os métodos clínicos de tratamento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-30935","number":"30935","sourceNumber":"30935","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Qual dos seguintes efeitos está comprovadamente associado ao uso de análogos de\ninsulina de ação prolongada em comparação com a insulina NPH?","options":{"A":"Menor frequência de hipoglicemia.","B":"Maior prevalência de controle metabólico.","C":"Menor prevalência de complicações microvasculares.","D":"Menor prevalência de complicações macrovasculares.","E":"Menor risco de desenvolvimento de câncer."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-29454","number":"29454","sourceNumber":"29454","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"São critérios para o diagnóstico de diabetes mellitus, EXCETO:","options":{"A":"Sintomas de poliúria, polidipsia e perda ponderal acrescidos de glicemia casual > ou igual a\n200mg/dl.","B":"Glicemia de jejum > ou igual a 126mg/dl com confirmação.","C":"Glicemia de 2 horas pós-sobrecarga de 75g de glicose > ou igual a 200mg/dl.","D":"Hemoglobina glicada (HbA1c) > ou igual a 7%."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-29461","number":"29461","sourceNumber":"29461","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação ao Diabetes Mellitus, marque a alternativa CORRETA:","options":{"A":"Glicemia de jejum alterada refere-se às concentrações de glicemia de jejum que são inferiores\nao critério diagnóstico para o DM, porém mais\nelevadas do que o valor de referência normal, ou\nseja, valores > ou igual a 100 mg/dl e < ou igual a 126 mg/dl.","B":"Tolerância à glicose diminuída representa uma anormalidade na regulação da glicose no estado\npós-sobrecarga, que é diagnosticada através do teste oral de tolerância à glicose (TOTG), que\ninclui a determinação da glicemia de jejum e de 2 horas após a sobrecarga com 75g de glicose,\ncom resultados > ou igual a 140 mg/dl e < ou igual a 200 mg/dl.","C":"As fitas com reagentes são tão precisas quanto às dosagens plasmáticas e devem ser usadas\npara o diagnóstico.","D":"Os testes de HbA1C devem ser realizados pelo menos duas vezes ao ano por todos os\ndiabéticos e quatro vezes por ano (a cada\ntrês meses) para pacientes que se submeterem a\nalterações do esquema terapêutico ou que não estejam atingindo os objetivos recomendados com\no tratamento vigente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-22938","number":"22938","sourceNumber":"22938","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino, 53 anos, em campanha de prevenção no posto de saúde\napresenta glicemia sérica de 240 mg/dl tendo\nalmoçado há três horas. Relata que tem sentido\nmuita sede e reporta fraqueza e tontura recorrentes. Neste momento, qual é a conduta adequada?","options":{"A":"Encaminhá-lo para tratamento de diabetes mellitus","B":"Realizar o teste em jejum, uma vez que o fato de ter almoçado impossibilita a avaliação do teste","C":"Realizar o teste de tolerância a glicose oral","D":"Repetir o teste em um ano uma vez que a glicemia pós-prandial está normal","E":"Encaminhá-lo ao pronto socorro para insulinoterapia"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-25323","number":"25323","sourceNumber":"25323","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação à prevenção e o manejo das complicações crônicas do diabetes é correto\nafirmar que:","options":{"A":"Os adultos com diabetes apresentam a mesma da taxa anual de mortalidade se comparado com\nos demais adultos, porém com expectativa de\nvida menor (cerca de 5 a 10 anos).","B":"A patogenia das complicações crônicas do diabetes não está totalmente esclarecida, mas o\ntempo de doença é o principal determinante do seu curso clínico.","C":"O rastreamento da retinopatia diabética no portador de diabetes melito tipo 2 deve ser realizado\napós 5 anos do diagnóstico.","D":"O método diagnóstico clínico frequentemente utilizado para a investigação laboratorial da\nnefropatia diabética é a determinação da microalbuminúria de 24 horas, embora, atualmente\ntambém se sugira para rastreamento a medida da proteína total em amostra isolada de urina.","E":"O infarto do miocárdio e a angina podem ocorrer de forma atípica no diabético, devido à\nneuropatia autonômica. Contudo, a evolução pós-infarto é semelhante aos demais pacientes."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-24310","number":"24310","sourceNumber":"24310","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação às complicações crônicas do diabetes melito (DM), é CORRETO afirmar:","options":{"A":"A retinopatia proliferativa é considerada uma complicação macrovascular.","B":"A maior tendência à doença cerebrovascular é considerada uma complicação microvascular.","C":"Catarata e glaucoma são complicações oftalmológicas descritas no DM.","D":"A neuropatia do DM é de caráter sensorial isolado, não havendo relatos do comprometimento\nmotor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27754","number":"27754","sourceNumber":"27754","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente de 63 anos, sexo feminino, em acompanhamento irregular por diabetes\nmellitus tipo 2, comparece ao ambulatório de\nClínica Médica com queixa de visão dupla e cefaleia\niniciadas há alguns dias. Ao exame físico, o olho direito está normal, mas o esquerdo apresenta\nperda de movimentos com desvio lateral e ptose palpebral; as pupilas estão simétricas e\nfotorreagentes. Não há outras alterações no exame neurológico. Qual o diagnóstico mais provável\npara esta paciente?","options":{"A":"Neuropatia facial central","B":"Neuropatia facial periférica","C":"Neuropatia trigeminal","D":"Neuropatia oculomotora","E":"Neuropatia óptica"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27755","number":"27755","sourceNumber":"27755","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A seleção pré-operatória de pacientes para a operação de redução de peso deve\nbasear-se estritamente nas orientações do NIH. São eles, EXCETO:","options":{"A":"IMC maior que 40 Kg/m2 sem comorbidades.","B":"Falha da terapia nutricional.","C":"Estabilidade psiquiátrica.","D":"IMC maior que 35 Kg/m2 com comorbidades.","E":"ASA maior que II."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27775","number":"27775","sourceNumber":"27775","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Durante uma visita de rotina ao pediatra, um garoto de 10 anos de idade apresenta\numa glicemia de 220 mg/dL. Após mais algumas\nperguntas, relata a mãe que ele sempre parece\nsedento e perdeu vários quilos ao longo dos últimos meses, os quais havia atribuído à intensa\nprática de futebol e à agitação de sua vida diária. Um exame-fita de urina no consultório mostra 4+\nde glicose e 2+ de cetonas. Seus exames iniciais de laboratório mostram Na+ 132, K+ 3,7, Cl- 110,\nHCO3- 15, glicose 220, ureia 18, creatinina 0,5. Glicemias de jejum em dois dias consecutivos\nconfirmaram os valores iniciais. Nenhuma outra alteração física ou laboratorial é descrita. Com\nbase nessas informações, a etapa inicial mais adequada no cuidado do paciente é:","options":{"A":"internar o paciente para iniciar fluidos IV e insulina subcutânea.","B":"iniciar o tratamento com injeções de insulina subcutânea.","C":"dosar hemoglobina glicada.","D":"medir os níveis de HbA1c para confirmar o diagnóstico.","E":"recomendar um regime alimentar para evitar a perda de mais peso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-25367","number":"25367","sourceNumber":"25367","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, obeso (IMC 36 kg/m²), hipertenso, portador de\ndiabetes mellitus tipo 2, diagnosticado há 5 anos. Qual das drogas abaixo demonstrou redução do\nrisco de AVC e infarto do miocárdio neste caso?","options":{"A":"Clofibrato e sinvastatina","B":"Metformina e ácido nicotínico","C":"Pioglitazona e metformina","D":"Rosuvastatina e atorvastatina","E":"Glimepirida e glipizida"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-7287","number":"7287","sourceNumber":"7287","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação às crises de asma, tem-se que:","options":{"A":"Na fase inicial de uma crise ocorre obstrução em todos os níveis de vias aéreas.","B":"O grau de dispneia na crise se correlaciona com a intensidade da obstrução das vias aéreas.","C":"O quadro clínico é variado, mas a dispneia está presente em todas as variantes.","D":"A taquipneia presente nas crises decorre das alterações nas concentrações arteriais de O2 e\nCO2.","E":"Numa crise de asma com sibilância seguida por silêncio respiratório é sinal de regressão do\nquadro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-7293","number":"7293","sourceNumber":"7293","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A doença pulmonar obstrutiva crônica (DPOC) acomete frequentemente tabagistas.\nSobre essa doença, marque o correto.","options":{"A":"A mortalidade está em declínio, sobretudo em homens.","B":"Pouco mais de 50% dos pacientes acometidos são fumantes, sendo os demais indivíduos\nexpostos a fumaça, produtos químicos tóxicos e às infecções.","C":"A patogênese do enfisema parece envolver a lise da elastina e outras proteínas por proteases\nliberadas por neutrófilos.","D":"Envolve um espectro de duas apresentações clínicas - enfisema e bronquite crônica - mas na\nmaioria dos casos é assintomática e indolente.","E":"Apesar de ser potencialmente grave, em qualquer estágio a doença pode ser reversível."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-8869","number":"8869","sourceNumber":"8869","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação ao cuidado com os pés do paciente diabético, está indicado:","options":{"A":"uso de compressas quentes regularmente.","B":"lavar os pés diariamente, de preferência com água quente.","C":"manter as unhas maiores que o limite dos pododáctilos.","D":"lubrificar a pele seca.","E":"não enxugar os pés."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-9070","number":"9070","sourceNumber":"9070","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Dos exames abaixo relacionados, qual o melhor para avaliação do controle metabólico\ndo paciente portador de diabetes mellitus?","options":{"A":"Glicemia de jejum.","B":"Glicemia pós-prandial.","C":"Curva glicêmica.","D":"Hemoglobina glicosilada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-6958","number":"6958","sourceNumber":"6958","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 58 anos, enfisematoso e dependente de oxigênio domiciliar,\napresenta-se com hemorragia digestiva alta.\nRealizando controle da hemorragia e estabilização\nhemodinâmica, evolui com agitação e estado confusional, sendo medicado com benzodiazepínico.\nQuinze minutos após, apresenta-se estuporoso. Gasometria arterial evidencia acidemia, PaO2 48\nmmHg, PaCO2 85 mmHg e bicarbonato 37 mEq/L. Nesse momento, a melhor conduta será:","options":{"A":"Ofertar oxigênio com máscara nasal de alto fluxo.","B":"Iniciar ventilação não invasiva com pressão positiva.","C":"Entubar o paciente e instituir ventilação mecânica.","D":"Corrigir a alcalose metabólica.","E":"Iniciar manitol, levando, em seguida, o paciente a estudo tomográfico de crânio."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-349760","number":"349760","sourceNumber":"349760","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Assinale a alternativa correta sobre Diabetes na infância.","options":{"A":"Diabetes na infância é uma condição muito rara abaixo dos 10 anos de idade.","B":"Diabetes tipo I é a mais frequente na infância.","C":"Diabetes do tipo gestacional é mais prevalente na pré-adolescência do que nas demais faixas\netárias das mulheres.","D":"Diabetes na infância acomete apenas meninos.","E":"A resistência insulínica nos lactentes é de grande importância para a manutenção da glicemia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-365643","number":"365643","sourceNumber":"365643","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A respeito do tratamento de um adolescente que apresenta cetoacidose diabética com\ndesidratação grave, assinale a alternativa correta.","options":{"A":"O soro de manutenção deve receber glicose apenas quando o paciente estiver normoglicêmico.","B":"A administração de insulina venosa deve ser iniciada apenas após correção da volemia.","C":"Deve-se administrar bicarbonato durante a fase de expansão volêmica, até que ocorra\nnormalização do pH sanguíneo.","D":"A infusão de potássio está contraindicada se os níveis séricos estiverem dentro da normalidade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-349694","number":"349694","sourceNumber":"349694","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma criança de sete anos, previamente saudável, é levada ao pronto-socorro com\nqueixas de poliúria, polidipsia, perda de\npeso e vômitos. Ao exame físico, apresenta desidratação,\ntaquipneia e hálito cetônico. Os exames laboratoriais revelam glicemia de 450 mg/dL, sódio e\npotássio de 140mEq/L e 5,5 mEq/L, respectiva; pH arterial de 7,2, bicarbonato de 18mEq/L. Qual\ndeve ser a conduta inicial nesse caso?","options":{"A":"Iniciar hidratação venosa com solução salina isotônica e, após hidratação, reavaliar a\nnecessidade de insulina regular em infusão contínua.","B":"Iniciar hidratação venosa com solução salina isotônica e bicarbonato em infusão contínua.","C":"Iniciar hidratação venosa com solução glicosada hipotônica e tiamina em bolus.","D":"Iniciar hidratação venosa com solução salina isotônica e glicose em infusão contínua.","E":"Iniciar hidratação venosa com solução salina hipertônica e insulina NPH em bolus."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-349706","number":"349706","sourceNumber":"349706","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Diabetes Mellitus (DM) é uma das doenças crônicas não transmissíveis mais\nimportantes do mundo, sendo o conhecimento a seu\nrespeito fundamental para o médico e para\noutros profissionais da saúde. Em relação à fisiopatologia da DM tipo 2, assinale a alternativa\ncorreta.","options":{"A":"A DM tipo 2 tem componente genético pouco significativo, sendo uma doença exclusivamente\nrelacionada ao estilo de vida.","B":"As alterações metabólicas da DM tipo 2 geram inflamação sistêmica de alto grau, com\nfrequentes alterações em marcadores laboratoriais de inflamação, como ferritina.","C":"A resistência à ação da insulina por tecidos sensíveis a esta leva a uma redução no consumo da\nglicose sérica e a um aumento na produção hepática de glicose.","D":"A perda gradual de produção de insulina secundária leva à destruição das células beta do\npâncreas por processo autoimune característico da DM tipo 2.","E":"Como resultado da resistência insulínica, há aumento da presença de ácidos graxos livres\nséricos levando à redução nos níveis de HDL, LDL e VLDL."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-322149","number":"322149","sourceNumber":"322149","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um homem de 24 anos procura atendimento médico com queixa de falta de ar e boca\nseca. Sua glicemia capilar é aferida, 467mg/dL. Nega doenças prévias ou uso de medicações.\n\nDiante desse caso, assinale a alternativa correta.","options":{"A":"A presença de acidose respiratória é comum nesses casos.","B":"O uso de insulina de ação rápida pode levar ao aumento do potássio sérico.","C":"A restrição hídrica está indicada nesse caso.","D":"A dosagem da hemoglobina glicosilada, é essencial para determinar a conduta correta.","E":"Os títulos de anticorpos antidescarboxilase do ácido glutâmico (GADA) são importantes para o\ndiagnóstico de LADA (latente autoimmune diabetes of the adult)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337529","number":"337529","sourceNumber":"337529","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Trata-se de estado de cetoacidose diabética, sendo necessária\nhidratação vigorosa com solução salina hipertônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337530","number":"337530","sourceNumber":"337530","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. A terapêutica com insulina regular deve ser realizada\npreferencialmente por via endovenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337531","number":"337531","sourceNumber":"337531","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Na presença de leucocitose e acidose, deve-se iniciar o\ntratamento com antibióticos de largo espectro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337532","number":"337532","sourceNumber":"337532","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Deve-se realizar reposição de potássio, entretanto não deve ser\nutilizada reposição de bicarbonato para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337533","number":"337533","sourceNumber":"337533","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Em geral, altas doses de insulina podem ajudar a aumentar a\nvelocidade do decréscimo da glicemia para valores habituais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337534","number":"337534","sourceNumber":"337534","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. O paciente apresenta uma osmolaridade efetiva plasmática, em\ntorno de 290 meq/l.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337590","number":"337590","sourceNumber":"337590","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. O alvo glicêmico desse paciente deve ser uma A1c\nabaixo de 6,5%, já que o controle intensivo da glicose diminui o risco de novo AVE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-305306","number":"305306","sourceNumber":"305306","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente, em idade escolar, apresenta queixa de dor abdominal intensa, náuseas,\nvômitos, anorexia e sonolência. Refere sentir muita sede e, ao exame físico, está desidratado.\n\nTambém foram percebidos hálito cetônico e hiperventilação (respiração de Kussmaul). Qual das\nseguintes opções é o resultado esperado na gasometria, de acordo com a principal suspeita\ndiagnóstica?","options":{"A":"Alcalose respiratória.","B":"Alcalose metabólica.","C":"Acidose metabólica com redução do ânion-gap.","D":"Acidose metabólica com elevação do ânion-gap.","E":"Acidose respiratória."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298892","number":"298892","sourceNumber":"298892","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 4 anos de idade foi levada pela mãe ao pronto atendimento e relatou\nque a filha refere intensa dor abdominal e\nestá há sete dias sem evacuar. A filha começou a\ndemonstrar dificuldades para evacuar logo que iniciou a introdução alimentar e, desde então,\napresenta fezes em \"bolinhas\". Em relação à dieta, disse que a menina come frutas, porém em\npouca variedade, gosta muito de banana e de maçã, não gosta de verduras e ingere pouca\nquantidade de água. Ao exame físico, verificaram-se FC = 100 bpm, FR = 22 irpm, SatO2 = 98%\nem AA, bem como abdome globoso com ruídos hidroaéreos positivos, dor difusa à palpação e, em\nquadrante inferior esquerdo, palpa-se massa (sugestivo de fezes). Considerando esse caso clínico\ne com base nos conhecimentos médicos correlatos, julgue o item a seguir. Diabetes mellitus é uma\ncausa incomum de constipação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298947","number":"298947","sourceNumber":"298947","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. É possível já estabelecer o\ndiagnóstico de diabetes mellitus nessa paciente, visto que apresenta glicose, ao acaso, maior ou\nigual a 200 mg/dL e possui sintomas inequivocos de hiperglicemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298948","number":"298948","sourceNumber":"298948","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. As lesões de pele\napresentadas pela paciente são compatíveis com Acantose nigricans, a qual é um indicativo de\nresistência insulínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-298949","number":"298949","sourceNumber":"298949","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O fumo é um fator de risco\ntotalmente evitável de doença e morte cardiovasculares, e seu enfrentamento precisa ser feito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284287","number":"284287","sourceNumber":"284287","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no mundo.\nConforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. Suponha-se que uma paciente de 46 anos de\nidade, com glicemia capilar de 218, tenha procurado o pronto-socorro por cefaleia do tipo\nenxaqueca. Nesse caso, é correto afirmar que a paciente é portadora de diabetes mellitus do tipo 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284288","number":"284288","sourceNumber":"284288","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. As anemias hemolíticas reduzem a dosagem\nde hemoglobina glicada sérica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284289","number":"284289","sourceNumber":"284289","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. No caso de preparo de duas insulinas na\nmesma seringa, é recomendada, primeiramente, a aspiração da insulina regular e, depois, a\naspiração da insulina NPH.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284290","number":"284290","sourceNumber":"284290","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. A avaliação oftalmológica está indicada cinco\nanos após o diagnóstico do diabetes mellitus do tipo 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-284291","number":"284291","sourceNumber":"284291","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. Os microaneurismas são manifestações\ncomuns da retinopatia diabética.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-261248","number":"261248","sourceNumber":"261248","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente apresenta provavelmente diabetes mellitus tipo II.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262124","number":"262124","sourceNumber":"262124","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 52 anos de idade, há cerca de 1 mês, queixa-se de perda de peso, de\naumento do número de vezes que urina ao longo do dia, inclusive tendo que levantar à noite para ir\nao banheiro, e também de aumento de sede e fome. Compareceu a consulta com outro médico que\nsolicitou alguns exames e agora os trouxe para verificação dos resultados. No momento, não faz\nuso de nenhuma medicação. Os exames revelaram os seguintes resultados: glicemia de jejum =\n182 mg/dL; hemoglobina glicada = 7,2 %; LDL-c = 198 mg/dL; e HDL-c = 48mg/dL. O paciente tem\n174 cm de altura e pesa 99 kg, com IMC = 32,7 kgm². Observaram-se PA = 160 mmHg x 93 mmHg;\nFC = 89 bpm; FR = 12 irpm; e SatO2 = 98%. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. O paciente tem um quadro de diabetes, associado a\ndislipidemia, hipertensão arterial e obesidade grau 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262127","number":"262127","sourceNumber":"262127","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 52 anos de idade, há cerca de 1 mês, queixa-se de perda de peso, de\naumento do número de vezes que urina ao longo do dia, inclusive tendo que levantar à noite para ir\nao banheiro, e também de aumento de sede e fome. Compareceu a consulta com outro médico que\nsolicitou alguns exames e agora os trouxe para verificação dos resultados. No momento, não faz\nuso de nenhuma medicação. Os exames revelaram os seguintes resultados: glicemia de jejum =\n182 mg/dL; hemoglobina glicada = 7,2 %; LDL-c = 198 mg/dL; e HDL-c = 48mg/dL. O paciente tem\n174 cm de altura e pesa 99 kg, com IMC = 32,7 kgm². Observaram-se PA = 160 mmHg x 93 mmHg;\nFC = 89 bpm; FR = 12 irpm; e SatO2 = 98%. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Histórico familiar de diabetes não tem relação com o\nsurgimento da doença no paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262128","number":"262128","sourceNumber":"262128","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 52 anos de idade, há cerca de 1 mês, queixa-se de perda de peso, de\naumento do número de vezes que urina ao longo do dia, inclusive tendo que levantar à noite para ir\nao banheiro, e também de aumento de sede e fome. Compareceu a consulta com outro médico que\nsolicitou alguns exames e agora os trouxe para verificação dos resultados. No momento, não faz\nuso de nenhuma medicação. Os exames revelaram os seguintes resultados: glicemia de jejum =\n182 mg/dL; hemoglobina glicada = 7,2 %; LDL-c = 198 mg/dL; e HDL-c = 48mg/dL. O paciente tem\n174 cm de altura e pesa 99 kg, com IMC = 32,7 kgm². Observaram-se PA = 160 mmHg x 93 mmHg;\nFC = 89 bpm; FR = 12 irpm; e SatO2 = 98%. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. É mandatória a dosagem de anti-GAD nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262148","number":"262148","sourceNumber":"262148","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. O quadro apresentado pelo paciente baseia-se em um estado de\nconcentração muito baixo de insulina e alto dos hormônios contrarregulatórios da insulina, que são\no glucagon, o hormônio do crescimento, o cortisol e catecolaminas, o que resulta na hiperglicemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262149","number":"262149","sourceNumber":"262149","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. Respiração de Kussmaul pode ser encontrada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262150","number":"262150","sourceNumber":"262150","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. Para esse paciente, deve-se iniciar hidratação venosa, insulina em bomba de\ninfusão contínua e reposição de potássio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262151","number":"262151","sourceNumber":"262151","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. Precisa ser iniciada a reposição também de bicarbonato.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262152","number":"262152","sourceNumber":"262152","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. Infecção deve ser investigada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262153","number":"262153","sourceNumber":"262153","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de diabetes tipo 1 desde os 13\nanos de idade. Na admissão, o paciente se\nencontra alerta, porém agitado, com FC = 118 bpm, FR\n\n= 22 irpm, SatO2 = 96%, vômitos e dor abdominal. Uma gasometria realizada na admissão revelou\npH = 7,21, bicarbonato = 7 mEq/L, glicemia\ncapilar = 327, e dosado potássio mostrou resultado =\n4,5 mEq/L. Considerando esse caso clínico e com base nos conhecimentos médicos correlatos,\njulgue o item a seguir. Considera-se resolvida a CAD quando pH > 7,3 e bicarbonato > 14 mEq/L.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-262405","number":"262405","sourceNumber":"262405","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considerando os alvos terapêuticos farmacológicos em cardiologia e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Os\ntrês principais genes em que são encontradas\nmutações na hipercolesterolemia familiar são o gene do receptor de LDL, o da APOB e o do\nPCSK9.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-261307","number":"261307","sourceNumber":"261307","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\nuso de metformina é contraindicado em pacientes com depuração de creatinina inferior a 30\nmL/min.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-255685","number":"255685","sourceNumber":"255685","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Determinado paciente de 35 anos de idade com diabetes tipo II incontrolável, com\nvários esquemas de terapia, IMC de 33 Kg/m²,\nproveniente do Japão, foi submetido a uma cirurgia\nbariátrica, pela técnica by-pass gástrico em Y de Roux. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. O by-pass em Y de Roux atua\ninicialmente como técnica restritiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-239285","number":"239285","sourceNumber":"239285","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Nesse caso, é correto\nsuspender a glibenclamida e associar dapaglifozina (um agonista do GLP-1 ? receptor 1\n\nglucagon-like peptídeo) ao tratamento com metformina.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-239286","number":"239286","sourceNumber":"239286","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Essa paciente tem acantose\nnigricans, que é comum em pacientes diabéticos e obesos. Essas lesões de pele nunca melhoram\ncom o tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-239287","number":"239287","sourceNumber":"239287","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Para essa paciente, a\npioglitazona não seria recomendada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-255784","number":"255784","sourceNumber":"255784","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"No que se refere aos conhecimentos relacionados a bioética, saúde mental,\nendocrinologia, dermatologia e cardiologia, julgue o\nitem a seguir. A insulina NPH é considerada de\nação intermediária, com início de ação entre 2 e 4 horas, e pico de ação entre 4 e 10 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-196680","number":"196680","sourceNumber":"196680","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher de 35 anos de idade, com diabetes melittus e hipertensão arterial sistêmica, em\ntratamento, apresenta peso corporal de 200 kg e altura de 1,50 m. O médico indicou cirurgia\nbariátrica, tendo como técnica a gastrectomia vertical (sleeve). Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Nessa técnica, há importante perda de\nvitamina B12 e ferro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-214387","number":"214387","sourceNumber":"214387","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, obesa (IMC 38 Kg/m²), diabética tipo II e em uso de\nhipoglicemiante oral, em tratamento de transtorno depressivo maior (bem controlado), comparece\nao consultório médico demonstrando interesse em realizar cirurgia bariátrica para emagrecer, pois\ngostaria de reduzir o peso por questões estéticas. A respeito desse caso clínico e da cirurgia\nbariátrica, e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A paciente\nmencionada não apresenta risco maior de infecção da ferida, formação de hematoma, hérnia\nincisional e complicações clínicas, em relação a outros pacientes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-214418","number":"214418","sourceNumber":"214418","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, obesa (IMC 38 Kg/m²), diabética tipo II e em uso de\nhipoglicemiante oral, em tratamento de transtorno depressivo maior (bem controlado), comparece\nao consultório médico demonstrando interesse em realizar cirurgia bariátrica para emagrecer, pois\ngostaria de reduzir o peso por questões estéticas. A respeito desse caso clínico e da cirurgia\nbariátrica, e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\nestabilização dos níveis de glicemia e a redução do apetite nessa paciente, se submetida a bypass\ngástrico com Y de Roux, decorrerão do aumento do glucagon-like peptide-1 (GLP-1).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-196626","number":"196626","sourceNumber":"196626","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente submetido a cirurgia bariátrica para tratamento de obesidade, com técnica de\nderivação gástrica em Y de Roux há seis anos, refere ter ficado sem convênio nos últimos três\nanos, não tendo mantido seguimento clínico ou nutrólógico nesse período. Manteve-se consumindo\nsuplemento alimentar (polivitamínico/mineral) por via oral, prescrito pela equipe médica na ocasião\nda cirurgia. Queixa-se de fraqueza, desequilíbrios e parestesia de extremidades. Apresenta\nhemograma com hemoglobina de 9mg/dL, com VCM e RDW aumentados. Com base nesse caso\nclínico e nos conhecimentos médicos a respeito de cirurgia bariátrica, julgue o item a seguir. A\ntécnica cirúrgica utilizada nesse paciente é classificada como puramente disabsortiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-196633","number":"196633","sourceNumber":"196633","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma menina de 10 anos de idade recebeu diagnóstico de pneumonia bacteriana\nadquirida na comunidade, em unidade básica\nde saúde. Foi então iniciado tratamento com\namoxicilina, na dose de 50 mg/kg/dia, mas, após três dias de tratamento, a paciente apresentou\npiora clínica de quadro. Evoluiu com piora da tosse, associada a taquipneia, persistência da febre e\ndor abdominal, principalmente em hipocôndrio e flanco à direita. Com relação a esse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Dor abdominal na infância\né um dos motivos mais frequentes das consultas com o pediatra. É fundamental realizar anamnese\ne exame físico completos, a fim de pesquisar possíveis diagnósticos diferenciais. Essa pode ser,\npor exemplo, a primeira manifestação de diabetes tipo 1 na infância e na adolescência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-196660","number":"196660","sourceNumber":"196660","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\ngliclazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A\nrespeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir.\n\nNessa paciente, a presença de acantose estaria certamente relacionada com a resistência\ninsulínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-179190","number":"179190","sourceNumber":"179190","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um médico residente da área de clínica médica deseja fazer campanha para controle\nde diabetes mellitus. Após determinar a\npopulação-alvo, dosou a glicemia casual (definida como\naquela realizada a qualquer hora do dia, sem se observar o intervalo desde a última refeição) em\ntodos os participantes com a finalidade de realizar triagem. Nesse caso hipotético deverão ser\ninvestigados os indivíduos que apresentarem valores de glicose plasmática, em mg/dL,\npreconizados para o diagnóstico de diabetes mellitus, acima de","options":{"A":"110.","B":"126.","C":"140.","D":"200.","E":"220."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177569","number":"177569","sourceNumber":"177569","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com Diabetes Mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de\nmedicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabetes\nmellitus e suas complicações, julgue o item a seguir. A baixa acuidade visual do paciente pode ter\norigem na retinopatia diabética, complicação que deve ter seu rastreamento iniciado um ano após o\ndiagnóstico da DM2.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177571","number":"177571","sourceNumber":"177571","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. A realização de índice tornozelo-braço é\nindicada para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177576","number":"177576","sourceNumber":"177576","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. O rastreamento da nefropatia diabética deve\nser realizado anualmente, por meio das dosagens séricas da ureia e da creatinina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177577","number":"177577","sourceNumber":"177577","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de\nmedicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. O rastreamento da neuropatia autonômica\nenvolve a aferição da frequência cardíaca de repouso, assim como da pressão arterial (em decúbito\ne ortostase).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177581","number":"177581","sourceNumber":"177581","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. No caso da disautonomia cardiovascular, o\nuso de mineralocorticoides pode ser vantajoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-177583","number":"177583","sourceNumber":"177583","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. A forma eruptiva dos xantomas usualmente\nocorre em pacientes com DM descompensado, mas a patogênese primária relaciona-se com a\nhiperlipidemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-131842","number":"131842","sourceNumber":"131842","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca do diabetes mellitus, assinale a alternativa correta.","options":{"A":"O diagnóstico pode ser estabelecido sem necessidade de confirmação e de sintomas clássicos,\nse o paciente apresentar glicemia casual\nigual a 150 mg por dL.","B":"O diabetes tipo 1 pode ser autoimune idiopático.","C":"O diagnóstico pode ser estabelecido sem necessidade de confirmação e de sintomas clássicos,\nse o paciente apresentar glicemia de jejum\nigual a 115 mg por dL.","D":"O diagnóstico pode ser estabelecido sem necessidade de confirmação e de sintomas clássicos,\nse o paciente apresentar hemoglobina glicada\nigual a 5,5%.","E":"Para a grande maioria dos diabéticos tipo 2, o tratamento exige a administração de insulina,\nprescrita em sistema intensivo com três a quatro doses de insulina diárias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-131826","number":"131826","sourceNumber":"131826","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere, hipoteticamente, menina de seis anos de idade, com história de vômitos, dor\nabdominal e cansaço há um dia. Mãe relata perda de peso da criança no último mês, associada a\npoliúria e polidipsia. Ao exame físico, observa-se criança desidratada, respiração de Kussmaul e\napresenta glicemia capilar de 400 mg/dl. A esse respeito, assinale a alternativa que melhor define o\nquadro de cetoacidose diabética:","options":{"A":"Glicemia plasmática > 200 mg/dl e pH de sangue arterial < 7,3.","B":"Glicemia plasmática > 200 mg/dl, pH de sangue arterial < 7,2, cetonúria = 1+ e HCO3 < 20\nmEq/L.","C":"Glicemia plasmática > 200 mg/dl, pH de sangue arterial < 7,3, cetonúria = 2+ e HCO3 < 15\nmEq/L.","D":"Glicemia plasmática > 200 mg/dl e sinais clínicos de diabetes (poliúria, polidipsia e perda de\npeso).","E":"Glicemia plasmática > 200 mg/dl, teste de tolerância oral à glicose com glicemia = 200 mg/dl na\ncoleta após 120 minutos do teste e glicosúria."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-134949","number":"134949","sourceNumber":"134949","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação ao Diabetes Mellitus (DM), julgue o item subsequente. Inúmeras evidências\nrelacionam o DM a fatores genéticos, logo, a grande maioria dos pacientes com DM tipo 1\napresenta antígenos de classe II HLA-DR3 ou DR4.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108200","number":"108200","sourceNumber":"108200","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de dezenove anos de idade foi encaminhada a um serviço de\nemergência por apresentar, havia duas\nhoras, quadro clínico constituído por náuseas, vômito e\nalteração do nível de consciência. O clínico foi informado de que há três dias a paciente queixou-se\nde febre associada a calafrios e dor localizada em flanco direito. O exame físico de admissão\nmostrou temperatura de 38 °C. frequência cardíaca de 120 bpm, pressão arterial de 90 mmHg x 40\nmmHg e frequência respiratória de 30 irpm. A paciente apresentava pele fria e ressecada,\nrespiração do tipo Kussmaul e dor a punho percussão do flanco direito. Os exames laboratoriais\nmostraram os seguintes resultados: leucócitos de 16.000/mm³ (sem desvio à esquerda);\nconcentração normal de hemoglobina e contagem de hemácias dentro da normalidade para o sexo\ne faixa etária da paciente; glicose de 800 mg/dL ; sódio de 124 mEq/L; potássio de 3,4 mEq/L; cloro\nde 98 mEq/L; ureia de 50 mg/dL; e creatinina de 1,5 mg/L. A gasometria arterial apresentou: PH =\n7,20; PaO? = 90 mmHg; PaCO? = 30 mmHg; bicarbonato = 6 mEq/L e BE = - 10. O Raio X de tórax\nnão revelou alterações e o EAS demonstrou presença de cilindros leucocitários e de hematúria\nmaciça. Considerando o caso clínico acima apresentado, julgue o item a seguir. Respiração de\nKussmaul associada aos achados apresentados na gasometria arterial indicam a presença de\nacidose respiratória.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108203","number":"108203","sourceNumber":"108203","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de dezenove anos de idade foi encaminhada a um serviço de\nemergência por apresentar, havia duas\nhoras, quadro clínico constituído por náuseas, vômito e\nalteração do nível de consciência. O clínico foi informado de que há três dias a paciente queixou-se\nde febre associada a calafrios e dor localizada em flanco direito. O exame físico de admissão\nmostrou temperatura de 38 °C. frequência cardíaca de 120 bpm, pressão arterial de 90 mmHg x 40\nmmHg e frequência respiratória de 30 irpm. A paciente apresentava pele fria e ressecada,\nrespiração do tipo Kussmaul e dor a punho percussão do flanco direito. Os exames laboratoriais\nmostram os seguintes resultados: leucócitos de 16.000/mm³ (sem desvio à esquerda);\nconcentração normal de hemoglobina e contagem de hemácias dentro da normalidade para o sexo\ne faixa etária da paciente; glicose de 800 mg/dL ; sódio de 124 mEq/L; potássio de 3,4 mEq/L; cloro\nde 98 mEq/L; ureia de 50 mg/dL; e creatinina de 1,5 mg/L. A gasometria arterial apresentou PH ?\n\n7,20; PaO? - 90 mmHg; PaCO? - 30 mmHg; bicarbonato ? 6 mEq/L e BE ? 10. O Raio X de tórax\nnão revelou alterações e o EAS demonstrou\npresença de cilindros leucocitários e de hematúria\nmaciça. Considerando o caso clínico acima apresentado. Julgue o item a seguir. Nesse caso,\ndeve-se buscar restaurar imediatamente a volemia por meio de soro fisiológico isotônico via\nintravenosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108204","number":"108204","sourceNumber":"108204","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de dezenove anos de idade foi encaminhada a um serviço de\nemergência por apresentar, havia duas\nhoras, quadro clínico constituído por náuseas, vômito e\nalteração do nível de consciência. O clínico foi informado de que há três dias a paciente queixou-se\nde febre associada a calafrios e dor localizada em flanco direito. O exame físico de admissão\nmostrou temperatura de 38 °C. frequência cardíaca de 120 bpm, pressão arterial de 90 mmHg x 40\nmmHg e frequência respiratória de 30 irpm. A paciente apresentava pele fria e ressecada,\nrespiração do tipo Kussmaul e dor a punho percussão do flanco direito. Os exames laboratoriais\nmostram os seguintes resultados: leucócitos de 16.000/mm³ (sem desvio à esquerda);\nconcentração normal de hemoglobina e contagem de hemácias dentro da normalidade para o sexo\ne faixa etária da paciente; glicose de 800 mg/dL ; sódio de 124 mEq/L; potássio de 3,4 mEq/L; cloro\nde 98 mEq/L; ureia de 50 mg/dL; e creatinina de 1,5 mg/L. A gasometria arterial apresentou PH ?\n\n7,20; PaO? - 90 mmHg; PaCO? - 30 mmHg; bicarbonato ? 6 mEq/L e BE ? 10. O Raio X de tórax\nnão revelou alterações e o EAS demonstrou\npresença de cilindros leucocitários e de hematúria\nmaciça. Considerando o caso clínico acima apresentado. Julgue o item a seguir. Os cilindros\nleucocitários encontrados no EAS são um forte indício de abscesso renal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108208","number":"108208","sourceNumber":"108208","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente de dezenove anos de idade foi encaminhada a um serviço de\nemergência por apresentar, havia duas\nhoras, quadro clínico constituído por náuseas, vômito e\nalteração do nível de consciência. O clínico foi informado de que há três dias a paciente queixou-se\nde febre associada a calafrios e dor localizada em flanco direito. O exame físico de admissão\nmostrou temperatura de 38 °C. frequência cardíaca de 120 bpm, pressão arterial de 90 mmHg x 40\nmmHg e frequência respiratória de 30 irpm. A paciente apresentava pele fria e ressecada,\nrespiração do tipo Kussmaul e dor a punho percussão do flanco direito. Os exames laboratoriais\nmostram os seguintes resultados: leucócitos de 16.000/mm³ (sem desvio à esquerda);\nconcentração normal de hemoglobina e contagem de hemácias dentro da normalidade para o sexo\ne faixa etária da paciente; glicose de 800 mg/dL ; sódio de 124 mEq/L; potássio de 3,4 mEq/L; cloro\nde 98 mEq/L; ureia de 50 mg/dL; e creatinina de 1,5 mg/L. A gasometria arterial apresentou PH ?\n\n7,20; PaO? - 90 mmHg; PaCO? - 30 mmHg; bicarbonato = 6 mEq/L e BE ? 10. O Raio X de tórax\nnão revelou alterações e o EAS demonstrou\npresença de cilindros leucocitários e de hematúria\nmaciça. Considerando o caso clínico acima apresentado. Julgue o item a seguir. Pielonefrite é um\nprovável fator desencadeante da alteração metabólica encontrada nessa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-105568","number":"105568","sourceNumber":"105568","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A obesidade é cada vez mais prevalente na infância, na adolescência e na idade\nadulta, sendo um importante problema de saúde\npública. Acerca desse tema, assinale a alternativa\nCORRETA.","options":{"A":"A obesidade infantil exógena, ao contrário da do adulto, deve ser considerada de fácil manejo,\npois envolve praticamente a interação de\ninfluências metabólicas com alimentares.","B":"Na obesidade exógena, os fatores ambientais são a dieta hipercalórica e o baixo nível de\natividade física, bem como a produção elevada de\nleptina e diminuída de adiponectinas, proteínas\nproduzidas pelo tecido adiposo visceral, cuja função é regular processos fisiológicos ligados ao\nmetabolismo de carboidratos e gorduras.","C":"O papel de atividade física regular no manejo da obesidade é importante para melhorar a\naptidão física e a massa muscular, enquanto a\nrestrição calórica alimentar aumenta o metabolismo\nbasal e de repouso, ambos importantes para o controle de peso.","D":"Na infância, a obesidade de origem endógena, como na hipertensão arterial secundária,\nabrange a grande maioria dos casos, como Cushing\ne síndromes de Prader-Willi e de Alstrom\ndevem ser realizadas.","E":"Assim como na obesidade do adulto, na obesidade infantil exógena, a prescrição de\nmedicamentos tem frequente indicação, pois é\ndifícil, para crianças, aderir a dietas com restrição\ncalórica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108224","number":"108224","sourceNumber":"108224","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma criança de quatro anos de idade foi levada à consulta ambulatorial devido à\npreocupação dos pais com a ingestão\nexcessiva de água e alimento pela criança, que apresentava\nintensa diurese e baixo ganho de peso. O médico solicitou um exame de glicemia de jejum, cujo\nresultado foi de 110 mg/dl. Em seguida, o médico solicitou um teste oral de tolerância à glicose,\ncujo resultado mostrou, duas horas após a sobrecarga de glicose, glicemia igual a 170 mg/dl.\n\nConsiderando esse caso clínico, julgue o item seguinte: Na situação em apreço, o diagnóstico de\ndiabetes melito tipo I está confirmado, e o médico deve recomendar o uso de insulina exógena.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-108163","number":"108163","sourceNumber":"108163","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca da diabetes, julgue o próximo item. Em indivíduos com diabetes melito tipo 2,\ndeve-se iniciar o rastreamento da retinopatia diabética no momento do diagnóstico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-82029","number":"82029","sourceNumber":"82029","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca dos sistemas cardiovascular, gastrointestinal e endócrino, julgue o item que se\nsegue. A pré-pró-insulina, produzida nas células beta das ilhotas pancreáticas, é clivada em\n\npró-insulina, e posteriormente convertida em insulina e peptídeo C.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-82034","number":"82034","sourceNumber":"82034","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca dos sistemas cardiovascular, gastrointestinal e endócrino, julgue o item que se\nsegue. A medida da circunferência da cintura abdominal maior que 85 cm em homens e que 70 cm\nem mulheres configura obesidade e leva ao diagnóstico de síndrome metabólica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-79652","number":"79652","sourceNumber":"79652","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Criança de 7 anos com poliúria, polifagia, polidipsia e perda de peso. O diagnóstico\nclínico mais provável é:","options":{"A":"Coma hiperosmolar não cetótico.","B":"Infecção urinária.","C":"Diabetes insipidus.","D":"Hiperaldosteronismo.","E":"Diabetes mellitus."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-82039","number":"82039","sourceNumber":"82039","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade procura uma Unidade de Pronto\nAtendimento (UPA) com relato de diarreia,\niniciada há um dia, com frequência de dez evacuações\nao dia, associadas à dor e urgência para evacuar, com eliminação de fezes em pequenas\nquantidades e com sangue. Ele negou uso de bebidas alcoólicas e de drogas. O exame físico\nmostrou pressão arterial de 90 mmHg x 50 mmHg, frequência respiratória de 25 irpm, pulso de 100\nbpm e temperatura axilar de 37,5°C. Observou-se que as mucosas estavam secas. Os exames de\nlaboratório revelaram glicemia de 300 mg/dl, com sódio e potássio em níveis séricos normais. Foi\nrealizada punção da artéria radial para coleta de gasometria arterial (paciente respirando ar\nambiente). Com base nesse caso clínico, julgue o item a seguir. O aumento da glicemia se deve ao\nestresse metabólico, o que descarta o diagnóstico de diabetes melito para esse paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-88733","number":"88733","sourceNumber":"88733","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Julgue o item subsequente, a respeito das crises hiperglicêmicas agudas. A causa mais\ncomum de todas as crises hiperglicêmicas agudas - cetoacidose diabética e estado hiperglicêmico\nhiperosmolar - é o diabetes recém-diagnosticado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-88738","number":"88738","sourceNumber":"88738","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Julgue o item subsequente, a respeito das crises hiperglicêmicas agudas. Na\ncetoacidose diabética, a combinação da\ndeficiência de insulina com o aumento de hormônios\ncontrarreguladores provoca a liberação excessiva de ácidos graxos livres do tecido adiposo, que no\nfígado serão oxidados em corpos cetônicos, resultando em cetonemia e acidose metabólica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-88697","number":"88697","sourceNumber":"88697","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente de cinquenta e um anos de idade, portador de hipertensão arterial\nsistêmica e diabetes melito, foi ao\nambulatório com queixa de sonolência diurna excessiva e roncos\nnoturnos, relatando ainda uso diário de clortalidona 50 mg. No exame físico, foram observados IMC\n\n= 31 kg/m², pressão arterial de 144 mmHg x 92 mmHg (média de três medidas), frequência\ncardíaca de 78 bpm e circunferência\nabdominal de 105 cm. Os resultados dos exames laboratoriais\napresentaram triglicerídeos de 296 mg/dL, colesterol total de 264 mg/dL, HDL colesterol de 34\nmg/dL, LDL colesterol de 160 mg/dL, hemoglobina glicada (A1C) de 7,4% e glicemia de jejum de\n138 mg/dL. A dosagem de microalbuminúria em amostra isolada de urina revelou 108 µg/mg de\ncreatinina. O eletrocardiograma e os demais exames laboratoriais solicitados foram normais.\n\nConsiderando esse caso clínico, julgue o item a seguir. Recomenda-se o uso de metformina com\nobjetivo de melhorar o perfil lipídico e glicídico do paciente, além de proporcionar-lhe redução do\npeso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-88700","number":"88700","sourceNumber":"88700","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação aos tipos de diabetes melito, julgue o item a seguir. O diabetes melito tipo 2\npode se manifestar na faixa etária\npediátrica, em decorrência da obesidade infantil.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-88718","number":"88718","sourceNumber":"88718","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação aos tipos de diabetes melito, julgue o item a seguir. O diabetes melito tipo\n1, o tipo mais comum de diabetes, decorre da destruição imunomediada das células\nbetapancreáticas e manifesta-se quando a síntese de insulina se reduz a, no mínimo, 50% das\nnecessidades fisiológicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-82065","number":"82065","sourceNumber":"82065","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação a doenças crônicas degenerativas, problemas de saúde mental, violência\ne obesidade, julgue o item que se segue. A\ntransição nutricional está fracamente relacionada às\nmudanças nos padrões de consumo de alimentos, sendo a maioria dos casos de obesidade\natribuída a fatores genéticos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-32185","number":"32185","sourceNumber":"32185","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A prevalência da diabete melito (DM), tanto do tipo 1 quanto do 2, está aumentando no\nmundo todo. Estima-se que, em 2030, haverá\nmais de 360 milhões de diabéticos, contra 177\nmilhões detectados em 2000. Acerca desse assunto, assinale a alternativa que apresenta o nível\nde glicose que confirma a diagnóstico de DM.","options":{"A":"Concentração aleatória em jejum de 100 mg/dL.","B":"Concentração aleatória em jejum de 126 mg/dL.","C":"Glicemia de 120 mg/dL, após 2 horas no teste de tolerância à glicose.","D":"Glicemia de 100 mg/dL, em jejum, por três vezes consecutivas.","E":"Glicemia de 100 mg/dL, após 4 horas no teste de tolerância à glicose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-27575","number":"27575","sourceNumber":"27575","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A prevalência mundial da Diabetes Melito (DM) aumentou drasticamente nas últimas\ndécadas. Estíma-se um crescimento ainda maior em um futuro próximo. A partir desses achados,\nem bases epidemiológicas nacionais, poderíamos afirmar quanto a esta complexa condição de\nsaúde:","options":{"A":"diversas endocrinopatias podem levar ao DM devido a secreção de hormônios antagonistas a\nação da insulina. Neste grupo, destacam-se a\nsíndrome de cushing, o feocromocitoma e a\nacromegalia.","B":"Os possíveis fatores desencadeantes do DM tipo 1 incluem os vírus (coxsackie, herpes e o vírus\nda rubéola ), a exposição precoce a proteínas\nde leite de vaca e os compostos nitrosilureias.","C":"A cetoacidose diabética é observada principalmente em indivíduos com DM tipo 1, sendo\nfundamental o diagnóstico precoce e o\ntratamento imediato, que consiste na reposição de líquidos,\navaliação eletrolítica, estado ácido-básico e de função renal, além da reposição de bicarbonato\nsérico.","D":"A medicação da hemoglobina glicada é o método padrão para avaliar o controle glicêmico a\nlongo prazo. A alteração na glicação não enzimática da hemoglobina reflete a história glicêmica\ndurante os dois ou três meses anteriores, pois os eritrócitos têm uma vida média de 120 dias.","E":"a metmorfina reduz os níveis de glicemia e os níveis de insulina em jejum. Seu uso deve ser\nconsiderado particularmente em portadores de disfunção renal grave e insuficiência cardíaca\ncongestiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-29745","number":"29745","sourceNumber":"29745","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere que um paciente de 45 anos de idade, com diagnóstico de diabetes melito\ndo tipo 2, seja levado ao pronto-socorro com\nquadro clínico e laboratorial compatível com\ncetoacidose diabética. Acerca desse caso clínico emergencial, julgue o item seguinte. Um resultado\nde gasometria arterial (de amostra colhida em ar ambiente) com achados mostrados na tabela\nabaixo será compatível com a condição emergencial em tela. (VER IMAGEM)","options":{"A":"Certo","B":"Errado"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-04/29745.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-29748","number":"29748","sourceNumber":"29748","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere que um paciente de 45 anos de idade, com diagnóstico de diabetes melito\ndo tipo 2, seja levado ao pronto-socorro com\nquadro clínico e laboratorial compatível com\ncetoacidose diabética. Acerca desse caso clínico emergencial, julgue o item seguinte. Nessa\ncondição clínica, ainda que os níveis plasmáticos de potássio estejam normais ou mesmo\naumentados na abordagem inicial do paciente, verifica-se significativo déficit corporal desse\neletrólito. (VER IMAGEM).","options":{"A":"Certo","B":"Errado"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-04/29748.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-7532","number":"7532","sourceNumber":"7532","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação à doença pulmonar obstrutiva crônica (DPOC), julgue os itens que se\nseguem. I - É uma doença crônica e\nlentamente progressiva. II - Está fortemente associada ao\ntabagismo. III - É uma doença obstrutiva que, geralmente, apresenta reversibilidade significativa ao\nuso de broncodilatadores. IV - O ato de parar de fumar cessa completamente a progressão da\ndoença. V - É uma causa de hipertensão arterial pulmonar. A quantidade de itens certos é igual a:","options":{"A":"1.","B":"2.","C":"3.","D":"4.","E":"5."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-8592","number":"8592","sourceNumber":"8592","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem veio ao consultório angustiado com exames laboratoriais de rotina realizados\nem outro serviço. Vê-se duas amostras distintas\nde glicemia de jejum: primeira = 121 mg/dL e a\nsegunda = 112 mg/dL. Qual é a conduta a ser tomada?","options":{"A":"Iniciar tratamento para Diabetes mellitus e solicitar os exames de rastreamento de lesão de\nórgão-alvo.","B":"Iniciar atividade física e dieta para diabético, além de solicitar, após 6 meses, nova glicemia\nde\njejum.","C":"Acalmar o paciente dizendo que não se trata de um caso de diabetes e mantê-lo em observação\ncom nova glicemia de jejum após 1 ano.","D":"Solicitar teste de tolerância oral à glicose.","E":"Solicitar hemoglobina glicada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-343404","number":"343404","sourceNumber":"343404","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"CPB, sexo feminino, 25 anos, foi levada ao pronto-socorro pelo pai com dor abdominal\nhá dois dias e hoje iniciou quadro de\nrebaixamento do nível de consciência, associado à respiração\nrápida e profunda. Ao exame físico: REG, desidratada (3+/4+), taquidispneica (ritmo de Kusmaul),\nGlasgow 14. Exames laboratoriais: hemograma com leucocitose, dextro: 460 mg/dL, pH sérico:\n7,18, HCO3: 8 mEq/L, Na: 142 mEq/L K: 3,2 mEq/L. Após iniciar hidratação endovenosa, o próximo\npasso será:","options":{"A":"Iniciar reposição endovenosa de potássio antes da insulinoterapia, por risco de arritmias.","B":"Corrigir importante acidose metabólica do paciente com infusão de bicarbonato de sódio.","C":"Iniciar insulinoterapia endovenosa com NPH.","D":"Prescrever solução salina hipotônica de NaCl 0,45%, 10 a 14 mL/kg/h."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-301295","number":"301295","sourceNumber":"301295","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. Trata-se de Cetoacidose diabética (CAD). São\nconsiderados diagnósticos diferenciais para CAD: a acidose láctica por erro inato do metabolismo,\nintoxicação por salicilato ou teofilina, coma hiperosmolar e acidose tubular renal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-301296","number":"301296","sourceNumber":"301296","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. Quanto à CAD, é correto afirmar que se trata de um\nconjunto de alterações clínico-laboratoriais decorrentes da insuficiente ação insulínica e da\nconcomitante diminuição dos hormônios contrarreguladores da insulina em resposta a alguma\nsituação de estresse. Laboratorialmente, caracteriza-se por hiperglicemia (glicemia superior a 200\nmg/dL) e acidose metabólica (pH inferior a 7,3 e/ou bicarbonato inferior a 15 mEq/L) com\ndiminuição do ânion gap.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-301297","number":"301297","sourceNumber":"301297","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. O edema cerebral é a complicação da CAD mais\ntemida em crianças e adolescentes. O edema cerebral ocorre em aproximadamente 1% dos casos\nde CAD e está associado à elevada morbidade e mortalidade. O edema cerebral, embora seja, em\ngeral, considerado uma complicação do tratamento da CAD, pode estar presente já na admissão do\npaciente ao serviço de urgência. A acidose hiperclorêmica por perda urinária de ânions cetoácidos\ne a administração por perda excessiva de fluídos ricos em cloreto, assim como a hipoglicemia e a\nhipercalemia, são complicações comuns associadas ao tratamento da CAD. A reposição de\nbicarbonato também pode causar hipernatremia e hipercalemia, sendo entendida como uma das\ncondições facilitadoras da ocorrência de edema cerebral em crianças e adolescentes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-301298","number":"301298","sourceNumber":"301298","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. As principais causas da CAD são infecções, pouca\naderência ao tratamento e estresse emocional. Em cerca de 25% a 40% das crianças e dos\nadolescentes diabéticos, a CAD é responsável pela primodescompensação diabética. Em\naproximadamente 25% dos casos de CAD, não é possível identificar um fator causal para a\ndescompensação. A CAD representa a descompensação aguda mais grave em crianças e\nadolescentes diabéticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-266502","number":"266502","sourceNumber":"266502","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. Nesse caso, eventual presença dos sinais ou sintomas clássicos da diabetes\nmelito e(ou) descompensação metabólica aguda detectada com a medida de glicemia capilar\nbastam para o diagnóstico da diabetes melito, dispensando-se outros testes diagnósticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230542","number":"230542","sourceNumber":"230542","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O análogo de insulina glulisina demonstra resultados semelhantes na redução dos\neventos hipoglicêmicos e na eficácia em comparação com lispro e asparte. São indicados a\npacientes que apresentam tendência a ter hipoglicemia nos períodos pós- prandiais tardios e\nnoturnos. Podemos ACEITAR a seu respeito que:","options":{"A":"A glulisina é outro análogo de insulina de ação lenta obtido pela troca de asparaginase por\nlisina\nna posição 3 da cadeia ? e de lisina por ácido glutâmico na posição 29 da mesma cadeia.","B":"A glulisina é outro análogo de insulina de ação ultrarrápida obtido pela troca de asparaginase\npor\nlisina na posição 3 da cadeia ? e de lisina por ácido glutâmico na posição 29 da mesma cadeia.","C":"A glulisina é outro análogo de insulina de ação ultrarrápida obtido pela troca de asparaginase\npor lisina na posição 3 da cadeia ? e de lisina\npor ácido glutâmico na posição 29 de outra cadeia.","D":"A glulisina não é outro análogo de insulina, sua ação é ultrarrápida obtido pela troca de\nasparaginase por lisina na posição 3 da\ncadeia ? e de lisina por ácido glutâmico na posição 29 da\nmesma cadeia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230544","number":"230544","sourceNumber":"230544","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Para iniciar o tratamento do DM1 recém-diagnosticado é fundamental uma estrutura\nque proporcione um programa de educação, com equipe\ncomposta preferencialmente por\nenfermeiros, nutricionista e médicos. Somente sendo CORRETO o item:","options":{"A":"O diagnóstico de DM1 não causa um forte impacto sobre o paciente e seus familiares.","B":"É necessária uma boa orientação inicial para que entendam os objetivos do tratamento.","C":"Os esquemas propostos sem uma forma de monitorização dos resultados.","D":"Orientação não deve capacitá-los a administrar a insulina adequadamente, no início."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230545","number":"230545","sourceNumber":"230545","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ainda existe uma lacuna entre a evidência clínica e a prática diária de tratamento\nintensivo do diabetes, visto que, na maioria\ndos casos, a meta terapêutica é difícil de ser alcançada\ne mantida durante os anos de evolução da doença, pelas inúmeras barreiras que o diabetes impõe.\nSomente podemos ACEITAR que:","options":{"A":"Os efeitos benéficos e protetores do tratamento intensivo não foram nítidos nos estudos, apesar\ndo aumento dos valores de HbA1c ao longo dos\nanos de seguimento.","B":"Os efeitos benéficos e protetores do tratamento intensivo foram nítidos nos estudos, apesar do\naumento dos valores de HbA1c ao longo dos dias de seguimento.","C":"Os efeitos benéficos e protetores do tratamento intensivo foram nítidos nos estudos, apesar do\naumento dos valores de HbA1c ao longo dos anos de seguimento.","D":"Os efeitos benéficos e protetores do tratamento intensivo foram inexistentes nos estudos, apesar\ndo aumento dos valores de HbA1c ao longo dos\nanos de seguimento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230546","number":"230546","sourceNumber":"230546","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O análogo de insulina degludeca, de ação prolongada, está disponível no mercado\nbrasileiro para a prática clínica e, associado aos análogos de ação ultrarrápida, pode ser uma\nalternativa terapêutica no tratamento de indivíduos com diabetes. Somente NÃO podemos\nconcordar que:","options":{"A":"O análogo não é uma nova alternativa para o tratamento de pacientes, demonstrando benefícios\nprincipalmente naqueles casos que exigem doses maiores de insulina basal.","B":"Apresenta resultados semelhantes de controle glicêmico e redução de hipoglicemias.","C":"Esse análogo está aprovado para utilização em pacientes com mais de 1 ano de idade.","D":"Estudos que avaliaram o uso desse análogo na faixa etária pediátrica verificaram os mesmos\nefeitos alcançados na população adulta."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230552","number":"230552","sourceNumber":"230552","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"É importante, de qualquer modo, dar suporte aos pacientes com DM1, orientando-os a\nrealizar o tratamento de forma adequada para reduzir o risco de complicações, agudas e crônicas,\ne para propiciar a melhora da qualidade de vida. Sendo ADEQUADO o item:","options":{"A":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento e,\nparticularmente, a necessidade de monitoramento e de ajustes raros as doses de insulina.","B":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento e,\nparticularmente, a necessidade de monitoramento e de ajustes frequentes das doses de insulina.","C":"Inexiste o medo de eventos hipoglicêmicos, no dia a dia do tratamento e, particularmente, a\nnecessidade de monitoramento e de ajustes frequentes das doses de insulina.","D":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento,\nsendo desnecessário o monitoramento e de ajustes\nfrequentes das doses de insulina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230557","number":"230557","sourceNumber":"230557","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Existem diferentes estratégias, esquemas e tipos de insulinas disponíveis, podemos\nAPENAS aceitar que:","options":{"A":"Apesar de não existirem recomendações de metas glicêmicas para o controle do DM, é\nimportante a necessidade de individualização dos objetivos glicêmicos.","B":"Apesar de existirem recomendações de metas glicêmicas para o controle do DM, é importante\nenfatizar a necessidade de não causar a individualização dos objetivos.","C":"Apesar de existirem recomendações de metas glicêmicas para o controle do DM, é importante\nenfatizar a necessidade de individualização\ndos objetivos glicêmicos, evitando-se tanto sequelas de\nhipoglicemias quanto alterações no sistema nervoso central decorrentes de hiperglicemias\nalternadas com hipoglicemias.","D":"Apesar de não existirem recomendações de metas glicêmicas para o controle do DM, é\nimportante enfatizar a necessidade de\nindividualização dos objetivos no sistema nervoso central."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-230559","number":"230559","sourceNumber":"230559","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O tratamento intensivo do DM1, com a obtenção de níveis de HbA1c < 7%, diminui o\nrisco de evolução para complicações crônicas micro e macrovasculares. Somente sendo\nconsiderado ERRADO que:","options":{"A":"O uso de análogos de ação ultrarrápida é inferior no controle metabólico e na diminuição dos\nepisódios hipoglicêmicos.","B":"A hipoglicemia grave é mais frequente com o tratamento intensivo.","C":"A hipoglicemia assintomática é uma das limitações do controle glicêmico ideal.","D":"A hipoglicemia grave pode afetar a capacidade cognitiva de crianças."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-206179","number":"206179","sourceNumber":"206179","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A escolha da outra opção de agente antidiabético deve basear-se em eficácia, idade,\nmecanismo de ação, risco de hipoglicemia, presença de comorbidades, expectativa de vida, ganho\nou perda de peso, efeitos adversos e potenciais de proteção cardiovascular. Sendo INCORRETO\nque:","options":{"A":"Também não há diferença na redução da HbA1c quando diferentes classes de medicamentos\nsão usadas como terceira opção para o tratamento\ndo diabetes tipo 2.","B":"Recomenda-se que qualquer droga antidiabética possa ser uma opção como terceiro agente\npara o controle glicêmico, desde que o\nmecanismo de ação não seja semelhante ao dos agentes já\nem uso.","C":"Tiazolidinedionas, sulfonilureias e glinidas foram associadas ao aumento leve de peso.","D":"Sulfonilureias e glinidas foram associadas a menor risco de hipoglicemia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-203112","number":"203112","sourceNumber":"203112","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Na pediatria, o diagnóstico de cetoacidose diabética é feito com base nos seguintes\ncritérios laboratoriais:","options":{"A":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH venoso < 7,3 e (ou) bicarbonato <\n15 mEq/L); e presença de cetonemia (> 3 mg/dl).","B":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH arterial > 7,3 e bicarbonato > 15\nmEq/L); e presença de cetonemia (> 3 mg/dl).","C":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH venoso < 7,3 e (ou) bicarbonato >\n15 mEq/L); e ausência de cetonemia.","D":"Hiperglicemia (glicemia > 600 mg/dl; acidose metabólica (pH arterial > 7,3 e bicarbonato > 15\nmEq/L); e ausência de cetonemia.","E":"Hiperglicemia (glicemia > 600 mg/dl); acidose metabólica (pH arterial < 7,3 e (ou) bicarbonato >\n15 mEq/L); e presença de cetonemia (> 3\nmg/dl)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-206138","number":"206138","sourceNumber":"206138","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A presença de hipoglicemia aumenta a morbimortalidade em diabéticos e não\ndiabéticos, afetando também hospitalizados. NÃO é adequado que","options":{"A":"a hipoglicemia afeta de 5% a 20% dos pacientes hospitalizados, principalmente os tratados com\nantidiabéticos ou insulina, mas também, pode ocorrer entre os não diabéticos com antecedente de\ncirurgia digestiva, câncer ou patologias graves.","B":"a presença de hipoglicemia não aumenta a morbimortalidade em diabéticos e não diabéticos\nindependentemente do nível de gravidade.","C":"além da influência no prognóstico, a hipoglicemia causa ansiedade e estresse entre os pacientes\ne seus familiares, bem como na equipe\nassistencial; em consequência, pode retardar o início do\ntratamento da hiperglicemia.","D":"na maioria dos casos, a hipoglicemia é causada pelos desajustes entre as doses de insulina e a\nquantidade de carboidrato oferecida aos pacientes, constituindo uma das complicações\niatrogênicas mais frequentes no hospital."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-206155","number":"206155","sourceNumber":"206155","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A glicemia plasmática em sangue periférico deve ser usada para confirmar uma\nhiperglicemia inesperada antes do tratamento, pois apresenta menor risco de ocorrência de erros\npré-analíticos, assim como maior acurácia. As principais desvantagens da dosagem de glicemia\nplasmática ou capilar são a influência da alimentação e do estresse agudo, o risco de\ncontaminação da amostra obtida em cateter com infusão de glicose e a limitação relativa ao\ndiagnóstico diferencial de DM e de hiperglicemia por estresse. Sendo INCORRETO que","options":{"A":"na recomendação atual, a hiperglicemia é definida como glicemia acima de 140 mg/dL (jejum) ou\n180 mg/dL (coleta aleatória).","B":"a hipoglicemia é definida como glicemia abaixo de 70 mg/dL, considerada grave se for inferior a\n40 mg/dL.","C":"os valores de corte devem ser padronizados em cada hospital.","D":"nos pacientes hiperglicêmicos sem DM prévio, níveis de A1C superiores a 6,5% permitem\nestabelecer o diagnóstico de DM. Sendo que\nperdas e transfusões sanguíneas, hemoglobinopatias,\ninsuficiência renal e uso prolongado de corticoides não reduzem a sensibilidade da A1C."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-206106","number":"206106","sourceNumber":"206106","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O DM agrava a evolução das doenças coexistentes que causam internação e aumenta\no risco de morte. sendo que entre os\ndiabéticos, deve-se identificar o tipo, o tratamento, o nível de\ncontrole e a frequência da hipoglicemia. Os diabéticos devem passar por avaliação contínua do\nrisco de queda e da ocorrência de úlceras. Dentre as opções a seguir, marque a INCORRETA:","options":{"A":"De 15% a 35% dos internados têm DM.","B":"50% dos diabéticos desconhece o diagnóstico.","C":"40% dos não diabéticos apresentam hiperglicemia.","D":"O DM e a hiperglicemia influenciam o prognóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175091","number":"175091","sourceNumber":"175091","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A hiperglicemia prolongada promove o desenvolvimento de lesões orgânicas extensas\ne graves, sendo que os níveis de glicose\nsanguínea persistentemente elevados são tóxicos ao\norganismo por meio de mecanismos diferentes:","options":{"A":"Promoção da glicação de proteínas.","B":"Aumento dos níveis de sorbitol fora da célula.","C":"Hiperosmolaridade.","D":"Aumento dos níveis de sorbitol dentro da célula."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175098","number":"175098","sourceNumber":"175098","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Crises Hiperglicêmicas Agudas levam a diversas complicações devido à situação em si,\nbem como relacionadas ao tratamento instituído, tanto a CAD Ceto Acidose Diabética quanto a\nEHH Estado Hiperglicêmico Hiperosmolar são graves situações, que apenas não se relacionam\ncom o seguinte item:","options":{"A":"São as complicações mais comuns da CAD e do EHH são hipoglicemia secundária ao uso\ninapropriado de insulina.","B":"A hipopotassemia devida à administração de doses inadequadas de insulina e/ou de bicarbonato\nde sódio.","C":"A hiperglicemia secundária à interrupção de infusão de insulina sem cobertura correta de\ninsulina subcutânea.","D":"O edema cerebral é uma complicação bastante comum no adulto, mas não evolui com herniação\nde tronco cerebral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183869","number":"183869","sourceNumber":"183869","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca de pacientes diabéticos, julgue o próximo item. Esses pacientes são submetidos\ncom maior frequência a intervenções\ncirúrgicas do que pacientes não diabéticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175123","number":"175123","sourceNumber":"175123","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Entre as cirurgias para obesidade, assinale a alternativa em que é classificada como\npuramente restritiva:","options":{"A":"Derivação gástrica em Y de Roux.","B":"Derivação Biliopancreática.","C":"Banda Gástrica Ajustável.","D":"Duodenal Switch."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175124","number":"175124","sourceNumber":"175124","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação à derivação gástrica em Y de Roux, assinale a alternativa INCORRETA:","options":{"A":"As taxas de mortalidade variam entre 0,3 a 1%.","B":"A estenose gastrojejunal é tratada na maior parte das vezes com reoperação.","C":"Encefalopatia de Wernicke pode se desenvolver em pacientes com vômitos pós-operatório\npersistentes.","D":"Embolia pulmonar é a complicação mais temida, e sua incidência pode exceder 1% nas\noperações abertas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-183951","number":"183951","sourceNumber":"183951","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação ao metabolismo do sistema endócrino e às doenças associadas à\ndesregulação desse metabolismo, julgue o item subsecutivo. O estado de jejum prolongado\nprovoca declínio da glicemia e, consequentemente, a diminuição do cortisol e do hormônio de\ncrescimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175149","number":"175149","sourceNumber":"175149","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A presença de Capsulite Adesiva (CA) associa-se à idade e à duração da doença no\nDiabético, principalmente no DM1, o que explica a maioria das associações a outras complicações\ncrônicas do diabetes. Não há, no entanto, clara relação com o grau de controle glicêmico. Das\nalternativas a seguir, é inadequada a seguinte associação:","options":{"A":"Pacientes diabéticos com CA têm níveis de colesterol e triglicerídeos mais elevados, e alguns\nestudos mostram associação com o infarto agudo do miocárdio.","B":"A alteração patológica básica é um espessamento da cápsula articular, que adere à cabeça do\número, resultando em redução acentuada do volume da articulação glenoumeral.","C":"Ocorre perda da amplitude de movimento da articulação, levando à disfunção, à dificuldade de\nrotação externa e à abdução do ombro acometido.","D":"Pessoas com diabetes têm quadros, em geral, mais dolorosos, com maior duração e pior\nresposta ao tratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175158","number":"175158","sourceNumber":"175158","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Algumas pesquisas demonstram índices aumentados de cáries em diabéticos,\nentretanto outras encontraram incidências similares\nou até menores nesses pacientes quando\ncomparados a controles não diabéticos. Determine qual conceito se mostra inadequado:","options":{"A":"Em indivíduos com níveis de glicose sanguínea mal controlados, tanto a saliva como o fluido\ngengival não apresentam alterações das quantidades de açúcares.","B":"Em indivíduos com níveis de glicose sanguínea mal controlados ou não controlados, pode\nocorrer alteração da microbiota do biofilme\ndental, influenciando o desenvolvimento de cáries.","C":"Em indivíduos com níveis de glicose sanguínea mal controlados ou não controlados, é possível\nque as doenças periodontais fossem\ninfluenciadas.","D":"Por outro lado, a ingestão limitada de carboidratos, comum nesse grupo de pacientes,\nproporciona uma dieta menos cariogênica, o que\ndiminuiria o risco de surgimento dessas lesões."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175160","number":"175160","sourceNumber":"175160","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Quando analisamos a complexa fisiopatologia do DM tipo 1, determinamos que a\nmesma envolve fatores genéticos e ambientais. No atual conhecimento, apenas uma das\nalternativas se mostra completamente adequada, assinale-a:","options":{"A":"É uma condição raramente poligênica.","B":"Na minoria dos casos, os principais genes envolvidos estão no sistema do antígeno leucocitário\nhumano (HLA) classe II.","C":"Entre os fatores ambientais potenciais para o desencadeamento da autoimunidade em\nindivíduos geneticamente predispostos estão certas infecções virais.","D":"Entre os fatores ambientais potenciais para o desencadeamento da autoimunidade em\nindivíduos geneticamente resistentes estão fatores\nnutricionais (p. ex., introdução precoce de leite\nbovino), deficiência de vitamina D e outros."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175171","number":"175171","sourceNumber":"175171","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A Espôndilo-Hiperostose Difusa Idiopática (EHDI), também conhecida como\nhiperostose ancilosante ou doença de Forestier,\ncaracteriza-se por uma limitação progressiva da\ncoluna vertebral, com calcificação dos ligamentos intervertebrais, formando pontes ósseas entre as\nvértebras (sindesmófitos), que, diferentemente da osteo artrite primária, não provocam\ndegeneração significativa do disco intervertebral. Pode ocorrer também ossificação de ligamentos e\ntendões em outros locais, como crânio, pelve, calcanhares e cotovelos. Dados epidemiológicos a\ncorrelacionam com descontrole metabólico, assinale o item abaixo se mostra inadequado:","options":{"A":"O acometimento é sistêmico, é explicado apenas por reação a fatores mecânicos locais.","B":"Sua prevalência é três vezes maior em pacientes com DM.","C":"Quando se analisa a população de pacientes com hiperostose difusa, 12 a 80% têm DM ou\nintolerância à glicose.","D":"Postula-se que concentrações séricas de insulina e de fator de crescimento semelhante à\ninsulina (IGF-1) mantidas prolongadamente elevadas nos pacientes diabéticos estimulem a\nneoformação óssea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-175175","number":"175175","sourceNumber":"175175","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Ao avaliar um caso na Ortopedia nessa manhã, um colega solicitou sua opinião sobre a\npossibilidade de Infarto Muscular Diabético, fundamentado em dados epidemiológicos você,\nadequadamente, respondeu as dúvidas, exceto por um dos itens abaixo que está INCORRETO:","options":{"A":"Trata-se de uma condição rara que é geralmente observada em pacientes com Diabetes Mellitus\ntipo 1.","B":"Trata-se de uma condição em pacientes com Diabetes Mellitus principalmente naqueles com\ntempo longo de doença e mal controlados.","C":"Apresenta-se como massa endurecida, dolorosa, não traumática, especialmente na coxa (mais\nde 80% dos casos).","D":"Há sempre um mal prognóstico, evoluindo frequentemente com Rabdomiolise."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-154516","number":"154516","sourceNumber":"154516","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Assinale a única afirmação INCORRETA sobre a cetoacidose diabética:","options":{"A":"Pode se manifestar por náuseas, vômitos e intensa dor abdominal, simulando abdome agudo\ninflamatório.","B":"Pode ser precipitada pelo uso de corticoides e agentes simpatomiméticos.","C":"Pode apresentar leucocitose com desvio à esquerda, mesmo na ausência de processo\ninfeccioso subjacente.","D":"É uma das causas de acidose metabólica com ânion-gap normal.","E":"O tratamento deve incluir reposição volêmica e insulinoterapia, com concomitante vigilância e\ntratamento dos níveis séricos de potássio."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-158036","number":"158036","sourceNumber":"158036","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Determinado paciente de 55 anos de idade começou recentemente a consultar-se em\numa clínica por insistência da esposa. Ele\nestá na terceira consulta, após repetir os exames\nlaboratoriais e confirmar o diagnóstico DM2. O paciente é assintomático e com sobrepeso, iniciou\numa dieta adequada há pouco tempo e parou de fumar há cinco anos quando tinha uma carga\ntabágica de 80 anos/maço. Também por insistência da esposa está tentando, embora com\ndificuldade, realizar caminhadas. Acerca do caso clínico apresentado, assinale a alternativa\nCORRETA.","options":{"A":"A fundoscopia deve ser realizada cinco anos após o diagnóstico do DM2 e, então, anualmente.","B":"A pesquisa de albuminúria em amostra isolada de urina é dispensável, se a função renal estiver\nnormal.","C":"A realização do índice tornozelo-braço é indicada.","D":"A radiografia de tórax deve ser solicitada para rastreio da neoplasia de pulmão, em razão da\ncarga tabágica.","E":"O teste do monofilamento nessa consulta, somente indicará sensibilidade protetora alterada\nquando duas ou mais das áreas testadas estiverem\ninsensíveis, quando utilizada a recomendação\nde Boulton et al. que inclui quatro áreas de teste."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-159506","number":"159506","sourceNumber":"159506","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A respeito da Cetoacidose Diabética (CAD), complicação aguda do diabetes melito,\njulgue o item subsecutivo. Os objetos\nbásicos do tratamento da CAD incluem reposição das perdas\nde fluidos, correção lenta da hiperglicemia e da acidose metabólica bem como correção dos\ndistúrbios eletrolíticos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-159511","number":"159511","sourceNumber":"159511","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A respeito da Cetoacidose Diabética (CAD), complicação aguda do diabetes melito,\njulgue o item subsecutivo. Pneumonia, infecção do trato urinário, abuso de álcool, infarto do\nmiocárdio e uso de corticoides são exemplos de fatores precipitantes de CAD.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-158062","number":"158062","sourceNumber":"158062","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Certa paciente de 62 anos de idade é uma senhora com DM2 em uso de metformina e\nglibenclamida, com controle inadequado da doença. Buscando atingir as metas de controle de\nglicemia, o médico inicia insulina NPH e, posteriormente, adiciona também insulina regular.\n\nConsiderando as diversas orientações que devem ser feitas para a paciente, assinale a alternativa\nque apresenta uma orientação CORRETA.","options":{"A":"Os frascos de insulina que não estejam em uso devem ser matidos exclusivamente na geladeira,\nna porção posterior de alguma prateleira,\nidealmente na parte inferior, visando à temperatura entre\n2°C e 8°C.","B":"A insulina NPH, de aparência transparente, deve ser delicadamente homogeneizada antes de\nser aspirada e aplicada.","C":"A insulina regular e a insulina NPH podem ser misturadas na mesma seringa quando são\naplicadas no mesmo horário, entretanto, a insulina NPH deve ser sempre aspirada em primeiro\nlugar.","D":"As aplicações devem ser realizadas com espaços de aproximadamente 2 mm entre si, evitando\nrealizar a aplicação em uma área utilizada recentemente.","E":"Para a aplicação da insulina, deve-se realizar uma prega cutânea, garantindo assim que a\ninsulina seja injetada na musculatura. A prega deve ser desfeita alguns segundos após a retirada\nda agulha."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-168472","number":"168472","sourceNumber":"168472","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma mulher com 50 anos de idade é encaminhada ao ambulatório de Nefrologia pela\nEquipe de Saúde da Família apresentando quadro de síndrome nefrótica. A paciente relata que, há\n3 meses, iniciou-se edema nos tornozelos. O edema ascendeu progressivamente, estando,\natualmente, na altura dos joelhos. Refere ganho de 10 kg nesse período, além de astenia. Nega\nhematúria, febre, lesões cutâneas ou queixas respiratórias Relata ser diabética há 10 anos,\nfazendo uso irregular de metformina (850 mg, 1 a 2 vezes/dia) e glibenclamida (5 mg, 1 a 2\nvezes/dia) sem acompanhamento médico há, pelo menos, 5 anos. O exame físico revela palidez\ncutâneo-mucosa, hipertensão arterial (pressão arterial = 180 x 100 mmHg) e importante edema de\nmembros inferiores (++++/4+). Os resultados dos exames solicitados pelo médico da Equipe de\nSaúde da Família demonstram: hemoglobina = 10 g/dL (valor de referência: 12 a 14 g/dL),\nhematócrito = 31% (valor de referência: 36 a 42%), VCM = 95 fL (valor de referência 80 a 100 fL),\nHCM = 31 pg (valor de referência: 27 a 32 pg), RDW = 13,4% (valor de referência: 11,5 a 15%);\nsérie branca e plaquetas normais; creatinina = 4,8 mg/dL (valor de referência 0,6 a 1,2 mg/dL),\nureia = 190 mg/dL (valor de referência: 15 a 38 mg/dL); glicemia de jejum = 230 mg/dL (valor de\nreferência: < 126 mg/dL), hemoglobina glicada = 9,0% (valor de referência: < 6,5%); sódio = 143\nmEq/L (valor de referência: 136 a 145 mEq/L), potássio = 5,5 mEq/L (valor de referência: 3,5 a 5,1\nmEq/L); colesterol total = 305 mg/dL (valor de referência: < 200 mg/dL), HDL = 30 mg/dL (valor de\nreferência: > 45 mg/dL); triglicerídeos = 322 mg/dL (valor de referência: < 150 mg/dL); albumina\nsérica = 2 g/dL (valor de referência: 3,5 a 4,5 g/dL); urina EAS = proteína +++ (valor de\nreferência:\nausente) e glicose ++ (valor de referência: ausente); proteinúria de 24 h = 5 g (valor de\nreferência: <\n0,5 g). Após a avaliação inicial, é feita uma ultrassonografia, que mostra rins de tamanho normal e,\nentão, é realizada biópsia renal, cujo resultado indica esclerose nodular mesangial. O presente\nquadro clínico indica que o prognóstico é de","options":{"A":"estabilização do comprometimento parenquimatoso e da função renal, desde que seja obtido o\ncontrole da glicemia.","B":"estabilização do comprometimento parenquimatoso e da função renal, desde que seja obtido o\n\ncontrole da pressão arterial.","C":"evolução para insuficiência renal crônica terminal por alteração da função renal, presença de\nhipertensão arterial e proteinúria nefrótica.","D":"evolução para insuficiência renal crônica terminal por alteração da função renal, persistência da\nhiperglicemia e alterações do metabolismo de lipídios."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-168465","number":"168465","sourceNumber":"168465","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um adolescente com 15 anos de idade é encaminhado à Unidade de Pronto\nAtendimento após ter apresentado vômitos e\nmal-estar em uma festa em que havia bebidas\nalcoólicas disponíveis. Em consulta, o paciente nega ter tomado tais bebidas. Ele é previamente\nhígido e também nega uso de medicamentos ou drogas ilícitas. Segundo relato dos familiares que o\nacompanham, o paciente faz dieta para perder peso, sem acompanhamento médico, e fica muitas\nhoras sem se alimentar. À admissão na unidade, ele apresenta hálito cetônico e está sonolento,\norientado, desidratado, acianótico, hemodinamicamente estável, com frequência respiratória = 36\nirpm, murmúrio vesicular fisiológico, abdome difusamente doloroso à palpação profunda e com os\nruídos hidroaéreos diminuídos, saturação arterial de oxigênio em ar ambiente = 95%. Os exames\ncomplementares iniciais realizados na unidade revelaram: glicemia = 380 mg/dL (valor de\nreferência: 99 mg/dL); gasometria arterial com pH = 7,24 (valor de referência: 7,35 a 7,45); PaO2 =\n100 mmHg (valor de referência: 83 a 108 mmHg); PaCO2 = 40 mmHg (valor de referência: 35 a 45\nmmHg); HCO3- = 14 mmol/L (valor de referência: 22 a 29 mmol/L); BE = -4 mmol/L (valor de\nreferência: -2,0 a +2,0 mmol/L); SaO2 = 98% (valor de referência: 95 a 99%); pesquisa de\ncetonemia positiva (valor de referência: negativa); Na+ = 130 mE/L (valor de referência 135 a 145\nmEq/L); K+ = 2,9 mEq/L (valor de referência 3,5 a 5,5 mEq/L); Cl- = 95 mEq/L (valor de referência\n96 a 109 mEq/L); amilase sérica = 120 U/L (valor de referência < 90 U/L). Diante do quadro clínico\ndescrito, quais são o diagnóstico mais provável e o tratamento inicial adequado para esse\npaciente?","options":{"A":"Cetoacidose diabética; hidratação com solução fisiológica e cloreto de potássio por via\nintravenosa.","B":"Cetoacidose diabética; administração imediata de insulina por via endovenosa.","C":"Cetoacidose secundária a pancreatite aguda; hidratação com solução fisiológica e\nantibioticoterapia por via intravenosa.","D":"Cetoacidose alcoólica; hidratação com solução fisiológica e tiamina por via intravenosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-168473","number":"168473","sourceNumber":"168473","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um homem com 43 anos de idade, sem histórico de tabagismo, fez dosagem da sua\nglicemia de jejum em exame de rotina no serviço de medicina do trabalho, tendo sido encontrado\ncomo resultado o valor de 120 mg/dL (valor de referência: < 110 mg/dL). Devido ao quadro, foi\nencaminhado a uma Unidade Básica de Saúde (UBS) para avaliação médica. O médico que o\natendeu, não tendo detectado história familiar de diabetes melito, nem encontrado alterações em\nseu exame clínico, pediu novo exame para dosagem da glicemia em jejum, que apresentou o\nresultado de 120 mg/dL. Solicitou, então, dosagem de glicemia 2 horas pós-carga (pós-prandial) e\ndosagem de hemoglobina glicada, que apresentaram, respectivamente, os seguintes resultados:\n160 mg/dL (valor de referência: < 140 mg/dL) e 6,1% (valor de referência: < 5,7%). O paciente foi\norientado sobre alimentação saudável e mudanças de hábitos de vida. Nessa situação e de acordo\ncom o estabelecido pelo Ministério da Saúde, quais devem ser o intervalo de tempo recomendado\npara reavaliação do paciente e a conduta médica adequada no retorno?","options":{"A":"A cada 3 meses; exame clínico na UBS.","B":"A cada mês; dosagem da glicemia em jejum.","C":"A cada ano; dosagem da glicemia em jejum.","D":"A cada 6 meses; dosagem da hemoglobina glicada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-168495","number":"168495","sourceNumber":"168495","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um homem com 18 anos de idade procura a Unidade Básica de Saúde com queixas de\nindisposição, poliúria, polidipsia e perda ponderal de 5 kg nos últimos 4 meses. Realizou teste de\nglicemia de jejum no dia anterior, cujo resultado foi de 382 mg/dL. O paciente relata que não há\nhistória de diabetes melito na família. Ao exame físico, constata-se índice de massa corporal = 20,9\nkg/m², circunferência abdominal 90 cm, pressão arterial = 123 x 82 mmHg; não se observa\nacantose nigricans. O resultado do exame clínico dos aparelhos circulatório e respiratório do\npaciente é normal. Diante dese quadro, o médico introduziu insulinas NPH e regular de imediato e\nencaminhou o paciente ao endocrinologista para seguimento. Nessa situação, a orientação médica\nadequada a esse paciente e seus familiares é","options":{"A":"a introdução de dieta hipocalórica, para perda de 5 a 10% do peso e redução mais rápida da\nglicemia.","B":"a suspensão da dieta e da insulina em casos de síndromes febris ou diarreia, para diminuir\nriscos de hipoglicemia.","C":"a suspensão da insulina NPH quando a glicemia de jejum for menos que 100 mg/dL, devido ao\nrisco de hipoglicemia.","D":"o adiamento do início de atividade física, pois existe o risco do paciente desenvolver\ncetoacidose\nglicêmica nesse momento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-133962","number":"133962","sourceNumber":"133962","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere hipoteticamente que paciente feminina de 82 anos de idade, portadora de\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica bem controladas, comparece a consulta\nagendada portando panfleto explicativo a respeito do diabetes e solicita dados adicionais. De\nacordo com as Diretrizes da Sociedade Brasileira de Diabetes 2014-2015, a correta informação a\nser oferecida é a seguinte:","options":{"A":"Intervenções no estilo de vida, com ênfase em alimentação saudável e prática regular de\natividade física, reduzem a incidência de diabetes tipo 1.","B":"A frequência do diabetes mellitus está assumindo proporções epidêmicas na maioria dos países.","C":"Parcela importante de óbitos em indivíduos com diabetes é tardia, ocorrendo quando eles já não\ncontribuem economicamente para a sociedade.","D":"O bom controle metabólico do diabetes previne o surgimento ou retarda a progressão das\nrespectivas complicações crônicas, particularmente as macroangiopáticas.","E":"Intervenções no controle de obesidade, hipertensão arterial, dislipidemia e sedentarismo,\nembora não previnam o surgimento do diabetes,\nsão medidas de prevenção para doenças\ncardiovasculares."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-133968","number":"133968","sourceNumber":"133968","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente masculino de 42 anos de idade, etilista social, em tratamento para diabetes\nmellitus diagnosticado há oito anos, recém-divorciado e recém-inscrito em programa premium de\nacademia para musculação, comparece em consulta perguntando pelos \"exames do coração\".\n\nNesse caso hipotético, de acordo com as Diretrizes da Sociedade Brasileira de Diabetes\n2014-2015, seriam indicações de teste de esforço para o paciente:","options":{"A":"Idade maior que 35 anos.","B":"Idade maior que 25 anos e diabetes tipo 1 há mais de cinco anos.","C":"Idade maior que 25 anos e diabetes tipo 2 há mais de cinco anos.","D":"Neuropatia periférica.","E":"Etilismo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-129003","number":"129003","sourceNumber":"129003","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Assinale a alternativa que apresenta o melhor critério para o diagnóstico de diabetes\nmellitus segundo a Sociedade Brasileira de Diabetes.","options":{"A":"HbA1c > 6,5%","B":"Glicemia de jejum \"maior ou igual a\" 126 mg/dL","C":"Glicemia de duas horas pós-sobrecarga de 75 g de glicose > 180 mg/dL","D":"Sintomas de poliúria, polidipsia e perda ponderal acrescidos de glicemia casual > 250 mg/dL","E":"HOMA-IR > 4,65"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-104765","number":"104765","sourceNumber":"104765","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A obesidade é uma doença que compromete múltiplos sistemas e é considerada uma\npandemia atualmente. A hipertensão arterial secundária à obesidade tem como fator\ndesencadeante o (a):","options":{"A":"Vasoconstrição anormal.","B":"Volume circulante diminuído.","C":"Diminuição do débito cardíaco.","D":"Diminuição da resistência periférica.","E":"Hipoinsulinemia com hiperglicemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-111285","number":"111285","sourceNumber":"111285","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A figura abaixo (de Stratton, I.M. et al, BMJ 321:405-412, 2000) mostra a relação\nentre a porcentagem de hemoglobina glicada\n(hemoglobina A1c) e a incidência de complicações\nmacrovasculares, microvasculares e catarata em indivíduos portadores de diabetes tipo 2. (VER\nIMAGEM) Estes resultados mostram que:","options":{"A":"O melhor método para se fazer diagnóstico de diabetes mellitus é a curva glicêmica, com\ndosagem da glicemia de jejum, 1 hora e 2 horas\napós a sobrecarga com 75 g de glicose.","B":"Quanto maior o tempo de duração da doença, maior a incidência de complicações.","C":"Existe uma relação direta entre a incidência de complicações e a glicemia média, representada\npela porcentagem de hemoglobina A1c.","D":"O método de escolha para o diagnóstico de diabetes mellitus é a dosagem de hemoglobina A1c,\numa vez que é um método barato e não sofre interferência de outros componentes.","E":"Hemoglobina A1c é uma forma mutada de hemoglobina, que aparece em indivíduos diabéticos\npor período superior a 10 anos. Quanto mais\nalto o nível de hemoglobina A1c, maior o número de\nmutações que aconteceram no gene da hemoglobina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-04/111285.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-111347","number":"111347","sourceNumber":"111347","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma paciente submetida à cirurgia bariátrica, moradora de zona rural e sem\nacompanhamento ambulatorial nos últimos 12 meses\ne que nega uso de medicamentos dá entrada\nno pronto-socorro com história de cefaleia, irritabilidade e fadiga. Ao exame físico se observa\nnistagmo, marcha atáxica e oftalmoplegia. O que está ocorrendo com a paciente?","options":{"A":"Tumor cerebral.","B":"AVC isquêmico.","C":"Deficiência de vitamina B1.","D":"Meningoencefalite.","E":"Intoxicação por organofosforado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-104767","number":"104767","sourceNumber":"104767","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A obesidade associa-se, de forma direta, ao diabetes, à hipertensão arterial e ao\ncolesterol elevado, fatores de risco para a doença coronária. Considerando essas informações,\nassinale a alternativa que apresenta conduta correta para seu manejo clínico.","options":{"A":"A obesidade não deve ser considerada como uma doença para não causar estigma no indivíduo.","B":"O núcleo fundamental da abordagem é o combate ao sedentarismo, seguido da dieta\nhipocalórica.","C":"Deve-se tornar o balanço calórico negativo dentro do contexto de atividade do indivíduo, o que\nsignifica alterar a quantidade e a qualidade da dieta ingerida no dia a dia e aumentar a atividade\nfísica diária, que deve ser diferenciada do exercício físico intenso.","D":"Devido à complexidade do manejo, o indivíduo obeso deve ser incentivado a procurar\ntratamentos alternativos como acupuntura,\nauriculoterapia, cremes para celulite, mesoterapia, ioga\ne suplementos dietéticos.","E":"A orientação sobre a atividade física é que ?pouco exercício é igual nenhum?, pois há falsa\nimpressão de que existe gasto calórico suficiente nas atividades leves."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-97790","number":"97790","sourceNumber":"97790","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma mulher com 35 anos de idade procura atendimento na Unidade Básica de Saúde\npara tratamento de obesidade. Manifesta desejo\nde usar medicações para diminuir a sensação de\nfome, pois refere que uma vizinha está tendo bons resultados com o uso de medicamentos há\nvários meses. A paciente é casada, tem três filhos - o mais novo com dois anos - e atualmente não\nestá trabalhando. Relata que ganhou muito peso durante a última gestação e que não conseguiu\nretornar ao peso anterior. Nega hipertensão ou diabetes. Não consegue fazer atividade física\nregular, pois tem dores na coluna e nos joelhos e diz que tem dificuldade em seguir dietas. O\nexame físico revela: peso = 78 kg; altura = 1,62 m; Índice de massa corporal - IMC = 29,7 kg/m²;\npressão arterial = 130 x 80 mmHg; circunferência abdominal = 90 cm. O restante do exame físico\nnão apresenta alterações significativas. Com base nessas informações, é correto afirmar que:","options":{"A":"existe indicação para tratamento farmacológico e a droga de escolha é a sibutramina na dose\nde 15 mg ao dia.","B":"os valores de circunferência abdominal e IMC colocam a paciente em situação de aumento de\nrisco cardiovascular.","C":"pelo cálculo do IMC, a paciente é classificada como de peso adequado, não necessitando\nintervenção medicamentosa.","D":"existe indicação para uso de inibidor da enzima de conversão, pelo risco de progressão para\nhipertensão arterial sistêmica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-80717","number":"80717","sourceNumber":"80717","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"A nefropatia diabética é afecção crônica debilitante progressiva e deve ser foco de\natenção em todos os portadores de Diabete Melito (DM), desde o início da doença. Uma das\nmanifestações mais precoces do envolvimento renal na DM é a:","options":{"A":"Retinopatia diabética proliferativa concomitante.","B":"Hipertensão arterial severa.","C":"Hematúria macroscópica.","D":"Microalbuminúria.","E":"Fibrose tubulointerstical renal."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-97818","number":"97818","sourceNumber":"97818","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente com 56 anos de idade, com antecedentes de obesidade desde a\nadolescência e hipertensão arterial\nsistêmica há cerca de 15 anos, em uso de enalapril ? 10 mg\nduas vezes ao dia, procurou ambulatório de clínica médica com queixas de poliúria e polidipsia\niniciadas há cerca de três meses. Ele refere que perdeu cerca de 9 kg nesse período, sem\nalterações na dieta habitual. Nega também doenças cardíacas, renais ou hepáticas. O paciente é\nsedentário e trouxe exame da semana anterior que mostra glicemia de jejum de 346 mg/dl (valor de\nreferência = 75-99 mg/dl) e uma outra glicemia de jejum, do dia anterior à consulta, de 334 mg/dl. A\nglicemia capilar no momento da consulta foi de 441 mg/dl. Ao exame físico, paciente encontra-se\nem estado geral regular, eupneico, desidratado (+/4+) e corado. Observa-se acantose nigricans\ncervical, Índice de Massa Corporal (IMC) = 28,7 kg/m², circunferência abdominal = 105 cm, pressão\narterial 130 x 70 mmHg sentado e de pé. Auscultas cardíaca e pulmonar normais. Além da\norientação dietética e da prática de atividade física, a conduta a ser adotada, neste momento, com\nposterior reavaliação, deve ser:","options":{"A":"Tratamento sem medicamentos por enquanto.","B":"Metformina ? 500 mg 2 vezes ao dia.","C":"Glibenclamida ? 5 mg 2 vezes ao dia.","D":"Insulina NPH ? 10 U ao deitar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-97774","number":"97774","sourceNumber":"97774","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um homem com 34 anos de idade, sem antecedentes patológicos prévios, procurou\nontem uma unidade básica de saúde porque vem\nevoluindo nos últimos quatro meses com queixas\nde poliúria, polidipsia e perda ponderal de cerca de 7 kg nesse período. Há dois meses realizou\nexames complementares que evidenciaram glicemia de jejum 348 mg/dl (valor de referência =\n\n75-99 mg/dl). Nega história de diabetes na família. Desde então, faz uso de doses crescentes de\nmetformina e glibenclamida, atualmente com 1.700 mg/dia e 10 mg/dia, respectivamente. As\nauscultas cardíaca e pulmonar são normais. Refere persistência dos sintomas e os exames\ncomplementares colhidos hoje revelaram: glicemia de jejum = 296 mg/dl; glicemia 2h após o café\nda manhã = 412 mg/dl; hemoglobina glicada = 10,1% (valor de referência = 3,8%-6,4%). Ao exame\nfísico, paciente mostra-se desidratado, corado; pressão arterial = 110 x 75 mmHg; circunferência\nabdominal = 92 cm; Índice de Massa Corporal (IMC) = 23,3 kg/m²; peso = 60 kg. Além de\nreferenciar para o especialista, a conduta adequada para esse paciente é:","options":{"A":"Aumentar as doses de glibenclamida e de metformina, adicionar insulina NPH antes de dormir.","B":"Manter as doses de glibenclamida e metformina, adicionar insulina NPH antes do café da manhã\ne antes do jantar.","C":"Suspender glibenclamida e metformina, adicionar insulina NPH antes do café da manhã e antes\nde dormir, bem como insulina regular antes das\nrefeições.","D":"Suspender glibenclamida, manter metformina, adicionar insulina NPH antes do café da manhã e\nantes do jantar, bem como insulina regular antes do café da manhã."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-75519","number":"75519","sourceNumber":"75519","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Criança com 9 anos de idade, previamente hígida, desenvolveu quadro de astenia há\ndois dias. Há seis horas passou a apresentar alguns episódios de vômito, dor abdominal, poliúria e\npolidipsia. Foi levada pela mãe ao pronto-socorro, onde chegou com quadro de desidratação e\nconfusão mental. O plantonista solicitou gasometria arterial, que apresentou o seguinte resultado:\npH = 7,2; pO2 = 75 mmHg; pCO2 = 30 mmHg; HCO3-= 12 mEq/L e Excesso de base (BE) = -18\nmEq/L.\n\nCom base no quadro clínico e exames laboratoriais, o diagnóstico e a conduta imediata são,\nrespectivamente:","options":{"A":"cetoacidose diabética; corrigir desidratação pelo\ncálculo da depleção do espaço extracelular.","B":"intoxicação exógena aguda; administrar carvão ativado e tomar medidas para estabilização do\npaciente.","C":"obstrução intestinal; corrigir a desidratação, além de solicitar US abdominal para confirmar o\ndiagnóstico.","D":"pancreatite aguda; encaminhar para Unidade de\nTerapia Intensiva para monitorização e suporte.","E":"gastroenterocolite aguda; corrigir desidratação de\nacordo com o seu grau."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-75534","number":"75534","sourceNumber":"75534","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem com 18 anos de idade, apresenta diagnóstico recente de diabetes mellitus tipo\nI e encontra-se em acompanhamento na\nUnidade Básica de Saúde. Foram prescritas insulina NPH\n16 U + insulina regular 6 U antes do café e insulina NPH 8 U + insulina regular 4 U antes do jantar.\nO paciente foi orientado a verificar a glicemia capilar antes das refeições e ao deitar, fazendo\naplicação de insulina regular adicional conforme resultado da glicemia, devendo preencher registro\ncom resultado da glicemia e dose adicional de insulina regular utilizada. O paciente retorna à\nUnidade Básica de Saúde 30 dias depois. Com base nestas informações, e de posse do registro\ndas glicemias, a melhor recomendação em relação ao ajuste das doses de insulina NPH ou regular\nprescritas é:","options":{"A":"aumentar 2 U da insulina NPH antes do café caso a medida da glicemia antes de deitar tenha\nsido superior a 120 mg/dl na maioria dos dias.","B":"aumentar 4 U da insulina regular antes de jantar caso a medida da glicemia antes do almoço\ntenha sido superior a 120 mg/dl na maioria dos dias.","C":"acrescentar 8 U de insulina NPH antes do almoço caso a medida da glicemia antes do almoço\ntenha sido superior a 120 mg/dl na maioria dos dias.","D":"aumentar em 2 U a dose da insulina NPH noturna caso a medida da glicemia matinal em jejum\ntenha sido superior a 120 mg/dl na maioria dos dias.","E":"associar 4 U de insulina regular antes do almoço e ao deitar caso a medida da glicemia matinal\nem jejum tenha sido superior a 120 mg/dl na\nmaioria dos dias."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-137541","number":"137541","sourceNumber":"137541","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma mulher de 64 anos de idade, obesa, diabética do tipo II há 10 anos, faz uso de\nmetformina em dose alta (2 g/dia), sem obter controle glicêmico adequado. Em consulta\nambulatorial de controle, realizada há dez dias, apresentava: peso = 70 kg; glicemia de jejum =\n197 mg/dL (valor de referência: 99 mg/dL); hemoglobina glicada = 7,9% (valor de referência: 4 a\n6,4% Hb);\n\nmicroalbuminúria. Naquela ocasião, foi negociada com a paciente a suspensão da metformina e o\ninício de insulina NPH-14 UI antes do café da manhã e 7 UI antes do jantar. Retornando à consulta\nhoje, a paciente traz controles de glicemias capilares > 200 mg/dL em cada três de quatro\ndosagens diárias, realizadas durante uma semana. Qual a conduta mais adequada em relação às\ndoses de insulina?","options":{"A":"Trocar a insulina NPH por insulina lispro antes do café da manhã.","B":"Trocar a insulina NPH por insulina glargina antes do café da manhã.","C":"Acrescentar insulina regular antes das refeições e meia\ndose às 22h.","D":"Aumentar a dose da insulina NPH da manhã e acrescentar\ndose extra às 22h.","E":"Aumentar as doses da insulina NPH antes do café da manhã\ne antes do jantar."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-137607","number":"137607","sourceNumber":"137607","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma criança de 9 anos de idade é levada ao serviço médico de urgência com quadro\nde confusão mental e desidratação. Os pais\nrelatam perda de 2 kg nos últimos 15 dias, apesar do\naumento da ingestão alimentar e sede constante. Ao exame físico: paciente desidratado +++/4,\ncom hálito cetônico. Exames laboratoriais: glicemia = 560 mg/dL (valor de referência < 100 mg /dL),\ngasometria: pH = 7,2 e bicarbonato = 12 mEq/L, sódio = 140 mEq/L, potássio = 5,7 mEq/L; exame\nde urina: glicose = ++, proteínas = ausentes, corpos cetônicos = ++, leucócitos = 2 000/mL e\neritrócitos = 3 000/mL. Qual a conduta mais adequada no caso?","options":{"A":"Sistema de infusão contínua de insulina e hidratação parenteral com potássio e bicarbonato.","B":"Insulina de ação prolongada glargina) e hidratação por via oral com soro e bicarbonato de sódio.","C":"Insulina de ação rápida (regular) por via intravenosa e hidratação parenteral com soro\nfisiológico, sem bicarbonato.","D":"Insulina de ação intermediária (NPH) por via subcutânea e hidratação parenteral com soro\nfisiológico, sem potássio.","E":"Insulina de ação prolongada (NPH) e insulina de ação rápida (basal-bolo) e hidratação por via\noral com soro glicosado, sem potássio."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-138590","number":"138590","sourceNumber":"138590","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher, com 19 anos de idade, procura o pronto-socorro de um hospital secundário com\nqueixa de dor abdominal e vômitos há dois dias. Há cerca de quinze dias, apresenta tosse e coriza\namarelada e, há dez dias, poliúria e polidipsia. Comenta ter emagrecido 12 kg (18% do peso) nas\núltimas duas semanas. Informa não ter tido febre. Não relata antecedentes mórbidos pessoais ou\nfamiliares relevantes. Ao exame clínico, aparece vigil, consciente, orientada. Pontuação na escala\nde coma de Glasgow = 15. Corada, desidratada 2+/4+, taquipneica. Pressão arterial = 106 x 62\nmmHg, pulso = 104 bpm, frequência respiratória = 28 irpm. Abdome doloroso à palpação profunda\nde epigástrio, sem dor à descompressão brusca. Semiologia cardíaca, pulmonar, e de membros,\nnormais. Saturação de oxigênio em ar ambiente: 99 %. Glicemia capilar à entrada = 364 mg/dL.\nForam solicitadas dosagens séricas de eletrólitos, exame sumário de urina e gasometria venosa.\n\nAlém de se considerar o início de antibioticoterapia para o quadro respiratório alto, a conduta\nterapêutica imediata adequada é","options":{"A":"aguardar os exames, antes de outras etapas do tratamento.","B":"iniciar insulinoterapia, em bolus endovenoso, a ser\nmantida por infusão contínua.","C":"aguardar resultado da dosagem de eletrólitos (K+) e iniciar expansão com soro fisiológico","D":"preparar expansão com soro fisiológico e reposição de potássio","E":"introduzir expansão com soro fisiológico, reposição de potássio e insulinoterapia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-138605","number":"138605","sourceNumber":"138605","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Mulher, com 57 anos de idade, sem acompanhamento médico regular, é atendida em\nambulatório de clínica médica de hospital secundário por queixa de edema de membros inferiores e\nface e de urina espumosa há três meses. A paciente não refere doenças anteriores e desconhece\nseus antecedentes familiares. Ao exame clínico encontra-se orientada, normocorada, hidratada,\nafebril, com edema de face (++/4). Pressão arterial (posição deitada) = 176 x 102 mmHg com pulso\n\n= 76 bpm; pressão arterial (posição supina) = 154 x 78 mmHg com pulso = 72 bpm. Frequência\nrespiratória = 18 irpm. Exame cardíaco\nnormal. Ausculta pulmonar: murmúrio vesicular diminuído\nnas bases pulmonares, sem ruídos adventícios. Abdome com sinais de ascite moderada, membros\ninferiores com edema compressível (++/4). Fundoscopia: prejudicada por opacificação do cristalino.\nExames complementares: Glicemia de jejum = 283 mg/dL, Creatinina = 1,8 mg/ dL, Ureia = 60\nmg/dL. Colesterol total = 312 mg/dL, LDL = 230 mg/dL, HDL = 40 mg/dL, VLDL = 42 mg/dL,\ntriglicérides = 210 mg/dL. Albumina sérica = 1,8 g/dL. Exame sumário de urina: proteinúria (++++/4),\nglicosúria (++/4), sem outras alterações. Proteína na urina de 24h= 5,5g. Dosagem de eletrólitos e\nhemograma normais. Qual a principal etiologia para o quadro apresentado por essa paciente?","options":{"A":"Hipertensão arterial sistêmica.","B":"Diabetes mellitus.","C":"Dislipidemia.","D":"Glomerulopatia por lesões mínimas.","E":"Lupus eritematoso sistêmico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-138661","number":"138661","sourceNumber":"138661","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Uma criança de sexo feminino, com quatro anos de idade, é atendida no Pronto\nAtendimento com queixa de poliúria,\npolidipsia e emagrecimento nos últimos dois meses. Apesar de\nter havido um atendimento anterior por esta queixa, não houve uma definição diagnóstica. A mãe\ndecidiu retornar ao serviço porque nos últimos dois dias, a criança começou a apresentar\nsonolência, acompanhada de febre (dois picos de 38,6 °C), vômitos, fadiga, sinais de desidratação\ne taquipneia. Imediatamente, você decidiu encaminhar a paciente para um Serviço de Emergência,\ndevido à hipótese diagnóstica de cetoacidose diabética. A decisão de encaminhamento imediato foi\ndeterminada","options":{"A":"pela preocupação com a hipotensão, achado bastante comum nas crianças que desenvolvem\ncetoacidose diabética.","B":"para reposição volêmica e controle da glicemia. A\n\nhipotensão, na criança em cetoacidose diabética, é evento raro e tardio.","C":"pela alta mortalidade, característica da doença, cuja principal causa de morte está relacionada à\nhipotensão.","D":"pela hipertermia da criança, que requer imediata investigação diagnóstica.","E":"porque, em crianças lactentes e pré-escolares, além de adolescentes grávidas, a cetoacidose\nocorre com níveis de glicemia sempre muito\nelevados."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-31028","number":"31028","sourceNumber":"31028","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Acerca de alterações glicêmicas na infância, julgue o item a seguir. No tratamento de\npaciente em vigência de cetoacidose diabética, deve-se utilizar insulina de ação rápida (regular) ou\ninsulina de ação ultrarrápida.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-22195","number":"22195","sourceNumber":"22195","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nesta questão é apresentado um quadro clínico hipotético, seguido de uma assertiva a\nser julgada. Uma paciente de 5 anos de idade deu entrada no pronto-socorro. A mãe referiu que a\nfilha apresenta emagrecimento nos últimos dois meses, poliúria, polidipsia e polifagia. Hoje, teve\nqueda do estado geral, com sonolência excessiva. No exame físico, a paciente encontrava-se\nmagra, desidratada ++/4 e com respiração acidótica (Kussmaul). Os exames laboratoriais\napresentam glicemia de 512 mg/dL, acidose metabólica (pH 7,2 e bicarbonato - 12 mEq/L),\ncetonúria positiva (+++) e potássio de 4,5 mEq/L. A principal suspeita diagnóstica foi de diabetes\nmelito, e os quadros clínico e laboratorial foram compatíveis com cetoacidose diabética. Nessa\nsituação, a terapêutica mais indicada é hidratação rápida, insulinoterapia em doses baixas e oferta\nprecoce de potássio.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-22196","number":"22196","sourceNumber":"22196","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Nesta questão é apresentado um quadro clínico hipotético, seguido de uma assertiva a\nser julgada. Uma menina de 10 anos de idade, obesa, foi encaminhada para avaliação, a fim de\nreceber orientações acerca de emagrecimento. Seu inquérito alimentar revelou consumo excessivo\nde doces, massas, sucos e refrigerantes. Não faz atividade física regular, pois a família não tem\ntempo de levá-la para as aulas. Na escola, é uma criança introspectiva, sem muitos amigos e\nultimamente não quer frequentar as aulas. Seu exame físico revela acantose cervical e axilar e\naumento generalizado de tecido celular subcutâneo. Os exames laboratoriais apresentam glicemia\nde jejum de 113 mg/dL, colesterol total de 201 mg/dL, HDL de 32 mg/dL, LDL de 161 mg/dL e VLDL\nde 8 mg/dL e triglicérides de 80 mg/dL, teste oral de tolerância à glicose com glicemia de jejum de\n108 mg/dL, e após 120 minutos, de 141 mg/dL. Nessa situação, além da reorientação nutricional e\natividade física, devem ser prescritos metformina e fármacos hipolipidemiantes, com vistas a evitar\nsíndrome metabólica e reduzir o risco cardiovascular.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-8626","number":"8626","sourceNumber":"8626","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo masculino com 25 anos de idade e diabético deu entrada no serviço\nde pronto atendimento com queixas de dor\nabdominal, febre e vômitos há 48 horas. Ao exame\nfísico, o paciente estava desidratado. Considerando esse caso clínico, julgue o seguinte item:\nDevido à diabete, deve-se iniciar a hidratação venosa desse paciente com solução de frutose.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-368151","number":"368151","sourceNumber":"368151","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação à indicação de rastreamento de câncer de pâncreas para um paciente de\n60 anos de idade, obeso e com diagnóstico de\nDiabetes mellitus há um ano, assinale a alternativa\ncorreta.","options":{"A":"Há indicação formal de rastreamento, devido ao quadro de diabetes de início recente em\npaciente maior que 50 anos de idade.","B":"Não há indicação de rastreamento, pois só há fatores de baixo risco para câncer de pâncreas.","C":"Não há indicação de rastreamento, pois não há relação com o Diabetes mellitus, da forma\napresentada pelo paciente, com o câncer de pâncreas.","D":"Apesar de o Diabetes mellitus de início recente em pacientes com mais de 50 anos ser fator de\nalto risco para câncer de pâncreas, ainda não está bem estabelecida a indicação de rastreamento\nnesse grupo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-352189","number":"352189","sourceNumber":"352189","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O rastreamento de Diabetes Melitus (DM) na população é recomendado para todos os\nindivíduos com 45 anos ou mais, mesmo sem fatores de risco. Deve ser considerado estabelecer o\ndiagnóstico de DM na presença de glicemia de jejum ? 126 mg/dl e HbA1c ? 6,5% em uma mesma\namostra de sangue, sendo comum na rotina médica essa solicitação combinada em uma única\nrequisição laboratorial. Porém é imprescindível estar atendo as limitações metodológicas dos\nexames utilizados para evitar falsos diagnósticos. Marque a alternativa que esta combinação de\nexames pode ser utilizada para rastreio de DM sem grandes preocupações com a limitação\nmetodológica do teste HbA1c.","options":{"A":"Gestante assintomática com 26 semanas.","B":"Paciente HIV positivo em tratamento antirretroviral.","C":"Paciente com mielodisplasia em tratamento com transfusões quinzenais.","D":"Paciente com asma em uso de formoterol."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-368183","number":"368183","sourceNumber":"368183","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre a metformina, assinale a alternativa correta.","options":{"A":"Acidose lática é um efeito colateral comum da medicação.","B":"Metabólitos ativos são excretados por via renal, e, por isso, ela não deve ser administrada\nquando a TFG é < 50 mL/min/1,73 m².","C":"Reduz o débito de glicose produzido pelo fígado e melhora o perfil lipídico.","D":"Seu uso prolongado pode causar anemia megaloblástica devido à deficiência de ácido fólico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-351616","number":"351616","sourceNumber":"351616","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre os efeitos extraglicêmicos dos fármacos utilizados no tratamento do Diabetes\nMellitus 2, assinale a alternativa CORRETA:","options":{"A":"A pioglitazona pode aumentar o risco de fraturas ósseas.","B":"Os inibidores SGLT-2 reduzem os níveis de LDL-c.","C":"Os agonistas do GLP-1 reduzem a frequência cardíaca.","D":"A linagliptina diminui temporariamente a TFG devido ao seu efeito de vasoconstrição à arteríola\naferente renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-335064","number":"335064","sourceNumber":"335064","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Sobre os fatores de risco para doença cardiovascular, numere a coluna II de acordo\ncom a coluna I. COLUNA I 1. Resistência a\ninsulina 2. Obesidade 3. Dislipidemia 4. Hipertensão\narterial sistêmica. COLUNA II ( ) Há um aumento da atividade da enzima aromatase, com maior\nsíntese de estrogênio e consequente redução da testosterona no homem. ( ) Permanece como um\ndos mais importantes fatores de risco para mortalidade cardiovascular, ocorrendo essa associação\nindependentemente de outros fatores de risco. ( ) Está relacionada ao excesso de hormônio\nandrógeno em mulheres. ( ) É um fator de risco cardiovascular modificável muito relevante.\n\nAssinale sequência correta.","options":{"A":"3 1 2 4","B":"4 2 3 1","C":"2 4 1 3","D":"4 1 3 2"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-346835","number":"346835","sourceNumber":"346835","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 56 anos queixa-se de emagrecimento apesar de estar se alimentando muito\nbem. Relata polaciúria com micções de grande volume, porém nega disúria, algúria ou alteração do\njato urinário. É obeso (IMC: 38,9kg/m² ), tabagista, portador de HAS e insuficiência cardíaca\nisquêmica, em uso de enalapril 20mg ao dia, AAS 100mg ao dia e atorvastatina 40mg ao dia. O\nexame físico não apresenta anormalidades. Exames de laboratório: glicemia de jejum 276mg/dL;\nHgA1C 10,7%; creatinina 1,2mg/dL. Assinale a alternativa que apresenta a prescrição inicial MAIS\nadequada nesse caso.","options":{"A":"Metformina.","B":"Empagliflozina.","C":"Insulina NPH e metformina.","D":"Insulina regular pré-prandial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-334718","number":"334718","sourceNumber":"334718","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Homem de 32 anos deu entrada no pronto socorro com poliúria, confusão mental e\nperda ponderal. Ao exame físico apresentava-se\ntorporoso, hipocorado, com níveis pressóricos de\n112/55 mmHg, frequência cardíaca de 93 bpm, temperatura axilar de 36,8°C, ausculta cardíaca e\nrespiratória sem alterações, sem dor ou visceromegalias à palpação abdominal, sem déficit\nneurológico focal. Os exames laboratoriais evidenciaram hemácias: 4,8 milhões/mm³, hemoglobina:\n16,9 g/dL, hematócrito: 55%, leucócitos: 8920/mm³, plaquetas: 288.000/mm³, glicose: 822 mg/dL,\nsódio: 158 mmol/L, potássio: 3,8 mmol/L, magnésio: 2,1 mg/dL, uréia: 56 mg/dL, creatinina: 1,0\nmg/dL; gasometria de sangue venoso: pH: 7,09, pCO?: 47 mmHg, pO?: 36 mmHg, bicarbonato: 18\nmeq/L; exame de urina: pH: 5,2, densidade: 1,045, glicose: ++++, proteínas: +, cetonas: ++++,\nbilirrubina: negativo, urobilinogênio: negativo, leucócitos: +, nitrito: negativo. Neste momento\ndevem\nser prescritos para este paciente.","options":{"A":"Cloreto de sódio a 0,9% e cloreto de potássio a 10%.","B":"Cloreto de sódio a 0,45%, cloreto de potássio a 10%, insulina regular.","C":"Cloreto de sódio a 0,9%, cloreto de potássio a 10%, insulina regular, bicarbonato de sódio a\n8,4%.","D":"Cloreto de sódio a 0,45%, cloreto de potássio a 10%, insulina regular, bicarbonato de sódio a\n5%."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-335073","number":"335073","sourceNumber":"335073","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere um paciente portador de Diabetes mellitus tipo 2 há três anos, em uso de um\ncomprimido de metformina XR, 500 mg, duas vezes por dia (1.000 mg por dia), em\nmonoterapia.Apresenta um mapa da glicemia capilar com glicemia de jejum < 110 mg/dL e\n\npós-prandial > 190 mg/dL. Com base nas características dos fármacos listados, a melhor opção\nterapêutica para corrigir a hiperglicemia pós-prandial desse paciente é","options":{"A":"associar pioglitazona.","B":"associar um inibidor de DPP-4.","C":"associar insulina análoga.","D":"aumentar a metformina XR para 1.000 mg a cada 12 horas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-337628","number":"337628","sourceNumber":"337628","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Durante o ajuste das doses de insulina pode ser comum a ocorrência do efeito\nSomogyi. Nesse contexto, a medida clínica mais\nrecomendada para DIMINUIR a sua ocorrência\nserá:","options":{"A":"A dose de NPH deve ser diminuída pela manhã.","B":"A dose de NPH deve ser aumentada pela manhã.","C":"A dose de NPH deve ser diminuída à noite.","D":"A dose de NPH deve ser aumentada à noite."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-335105","number":"335105","sourceNumber":"335105","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Paciente do sexo feminino, sete anos de idade, com queixa de dor abdominal e\nvômitos. Relata que vem apresentando\npolidipsia, polifagia e aumento da diurese há duas\nsemanas. Está desidratada, com hálito cetônico e apresenta hiperpneia. Glicemia capilar 350 mg/dl.\nAcerca do tratamento inicial dessa paciente, assinale a alternativa correta.","options":{"A":"Deve ser prescrita hidratação venosa, com soro glicosado 5%.","B":"Deve ser prescrita insulina regular venosa para redução da glicemia até valores abaixo de 100 ?\n\n80 mg/dL.","C":"Deve ser feito monitoramento de íons e restauração do equilíbrio hidroeletrolítico em 24 ? 36\nhoras.","D":"Deve ser prescrita, imediatamente, correção de bicarbonato para correção da acidose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-313280","number":"313280","sourceNumber":"313280","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Com relação ao tratamento medicamentoso da Diabetes tipo 2 com Metformina, temos\ncomo possível efeito colateral:","options":{"A":"Aumento do peso.","B":"Infecção urinária.","C":"Deficiência de vitamina B12.","D":"Hipotensão e confusão mental.","E":"Aumento transitório da creatinina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-314032","number":"314032","sourceNumber":"314032","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"O Diabetes Mellitus (DM) do tipo 2 é um distúrbio progressivo definido por déficits na\nsecreção e ação da insulina, que causam metabolismo anormal da glicose e transtornos\nmetabólicos relacionados. Em relação ao diagnóstico do DM do tipo 2 em adulto, assinalar a\nalternativa CORRETA:","options":{"A":"Uma glicemia de jejum acima de 126mg/dL confirma o diagnóstico, na ausência de sintomas\ninequívocos de hiperglicemia.","B":"Uma hemoglobina glicosilada maior ou igual a 6,5% confirma o diagnóstico, na ausência de\nsintomas inequívocos de hiperglicemia.","C":"Uma glicemia maior que 140mg/dL, 2 horas após sobrecarga com 75g de glicose, confirma o\ndiagnóstico, na ausência de sintomas inequívocos de hiperglicemia.","D":"A confirmação do diagnóstico de DM é suficiente com um exame alterado, na ausência de\nsintomas inequívocos de hiperglicemia.","E":"Pacientes com sintomas clássicos de hiperglicemia devem ser submetidos à dosagem de\nglicemia ao acaso e independente do jejum; se glicemia aleatória ? 200mg/dL, confirma o\ndiagnóstico."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-313300","number":"313300","sourceNumber":"313300","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Um paciente, de 37 anos, portador de diabetes tipo 2, após a troca do hipoglicemiante\noral, tem apresentado retenção hídrica, anemia\nleve, ganho ponderal de peso e sinais de\ninsuficiência cardíaca. Pela sintomatologia, o hipoglicemiante em uso é:","options":{"A":"Metformina.","B":"Glimepirida.","C":"Pioglitazona.","D":"Acarbose.","E":"Clorpropamida."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-305031","number":"305031","sourceNumber":"305031","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Considere que um paciente de sete anos de idade, sexo feminino, com queixa de dor\nabdominal e vômitos, relata que vem apresentando polidipsia, polifagia e aumento da diurese há\nduas semanas. Está desidratada, com hálito cetônico e quadro de hiperpneia. Glicemia capilar =\n350 mg/dL. Nese caso, qual é o tratamento inicial dessa paciente?","options":{"A":"Deve ser prescrito hidratação venosa, com soro glicosado a 5%.","B":"Deve ser prescrito insulina regular venosa para redução da glicemia até valores abaixo de 100 ?\n\n80 mg/dL.","C":"Deve ser feito monitoramento de íons e restauração do equilíbrio hidroeletrolítico em 24 ? 36\nhoras.","D":"Deve ser prescrito, imediatamente, bicarbonato para correção da acidose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-314083","number":"314083","sourceNumber":"314083","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação a diabetes tipo 1 e a diabetes tipo MODY, assinalar a alternativa\nCORRETA:","options":{"A":"Acantose nigricans é patognomônico de diabetes tipo 1.","B":"Cetoacidose é mais comum do tipo MODY.","C":"Hiperglicemia costuma ser mais intensa no tipo MODY.","D":"Autoanticorpos são mais frequentemente positivos no tipo 1.","E":"O tipo MODY costuma ter início mais abrupto e de evolução mais grave e acelerada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-04-287845","number":"287845","sourceNumber":"287845","collectionBlock":"med:med-clinica-medica-med-clm-04","collectionLabel":"MED · MED CLM 04","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 04","subtopic":"","stem":"Em relação às cirurgias gástricas, assinalar a alternativa CORRETA:","options":{"A":"A técnica Y de Roux raramente é utilizada nas cirurgias bariátricas.","B":"A técnica da banda gástrica ajustável é a que mais promove alterações metabólicas.","C":"A gastrectomia vertical não promove mudança no controle da hipertensão arterial sistêmica e da\ndiabetes.","D":"A técnica duodenal Switch é a associação entre gastrectomia vertical e desvio intestinal.","E":"A técnica mais utilizada no Brasil é da banda gástrica ajustável."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 04/MED CLM 04.txt","sourceLabel":"MED · MED CLM 04","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 04","MED"],"answerSource":"explicit","commentDeferred":true}]};
